const e={id:"capitals",name:"ערי בירה",description:"כל מדינות העולם והבירות שלהן, ועוד טריטוריות שאינן מדינות. מסודר מהמפורסמות למאתגרות — וכדאי ללמוד גם בכיוון ההפוך.",cards:[["מהי בירת צרפת?","פריז","אירופה","נבנתה סביב אי בנהר הסן — איל דה לה סיטה, שעליו עומדת נוטרדאם. מגדל אייפל נבנה ב-1889 כמבנה זמני לתערוכה עולמית — ונשאר.",["פריז היא בירתה של איזו מדינה?","צרפת"]],["מהי בירת בריטניה?","לונדון","אירופה",'הרומאים ייסדו אותה בשם לונדיניום, לפני כאלפיים שנה. "ביג בן" הוא בכלל שמו של הפעמון הגדול, לא של המגדל.',["לונדון היא בירתה של איזו מדינה?","בריטניה"]],["מהי בירת איטליה?","רומא","אירופה","לפי המסורת נבנתה על שבע גבעות. בתוכה שוכנת מדינה אחרת לגמרי — הוותיקן.",["רומא היא בירתה של איזו מדינה?","איטליה"]],["מהי בירת ספרד?","מדריד","אירופה","הבירה הגבוהה באיחוד האירופי, כ-650 מטר מעל פני הים, כמעט בדיוק במרכז ספרד.",["מדריד היא בירתה של איזו מדינה?","ספרד"]],["מהי בירת גרמניה?","ברלין","אירופה","חולקה בחומה בין 1961 ל-1989. אחרי האיחוד הועברה אליה הבירה מבון, ושער ברנדנבורג הפך לסמל האיחוד.",["ברלין היא בירתה של איזו מדינה?","גרמניה"]],["מהי בירת ארצות הברית?","וושינגטון די.סי.","אמריקה",'"די.סי." — מחוז קולומביה: העיר אינה שייכת לשום מדינה. היא נבנתה מאפס כבירה, וג׳ורג׳ וושינגטון בחר את מקומה.',["וושינגטון די.סי. היא בירתה של איזו מדינה?","ארצות הברית"]],["מהי בירת רוסיה?","מוסקבה","אירופה",'בלב העיר הקרמלין — "מבצר" ברוסית — והכיכר האדומה. "אדומה" פירושה במקור "יפה", ברוסית העתיקה.',["מוסקבה היא בירתה של איזו מדינה?","רוסיה"]],["מהי בירת סין?","בייג׳ינג","אסיה",'פירוש השם: "הבירה הצפונית". בלב העיר "העיר האסורה" — ארמון הקיסרים במשך כ-500 שנה, שהכניסה אליו נאסרה על פשוטי העם.',["בייג׳ינג היא בירתה של איזו מדינה?","סין"]],["מהי בירת יפן?","טוקיו","אסיה",'פירוש השם: "הבירה המזרחית". עד 1868 נקראה אדו, ואז עבר אליה הקיסר מקיוטו — הבירה הקודמת.',["טוקיו היא בירתה של איזו מדינה?","יפן"]],["מהי בירת מצרים?","קהיר","אפריקה","מהערים הגדולות באפריקה ובעולם הערבי. הפירמידות של גיזה עומדות בשוליה המערביים.",["קהיר היא בירתה של איזו מדינה?","מצרים"]],["מהי בירת ישראל?","ירושלים","אסיה","קדושה ליהדות, לנצרות ולאסלאם. העיר העתיקה, בתוך החומות שבנה הסולטן סולימאן, משתרעת על פחות מקילומטר רבוע.",["ירושלים היא בירתה של איזו מדינה?","ישראל"]],["מהי בירת יוון?","אתונה","אירופה","קרויה על שם האלה אתנה, שלפי המיתוס זכתה בעיר בתחרות מול פוסידון: היא נתנה לתושבים עץ זית, והוא — מעיין של מים מלוחים.",["אתונה היא בירתה של איזו מדינה?","יוון"]],["מהי בירת טורקיה?","אנקרה","אסיה","לא איסטנבול: אתאטורק בחר ב-1923 באנקרה, במרכז אנטוליה, כדי לסמן התחלה חדשה לרפובליקה.",["אנקרה היא בירתה של איזו מדינה?","טורקיה"]],["מהי בירת הודו?","ניו דלהי","אסיה","נבנתה בידי הבריטים בשנות ה-20 וה-30 של המאה ה-20, ליד דלהי העתיקה. היום היא רובע בתוך דלהי רבתי.",["ניו דלהי היא בירתה של איזו מדינה?","הודו"]],["מהי בירת ברזיל?","ברזיליה","אמריקה","נבנתה מאפס בתוך כארבע שנים ונחנכה ב-1960, כדי לפתח את פנים המדינה. מלמעלה היא נראית כמו מטוס, או ציפור.",null],["מהי בירת ארגנטינה?","בואנוס איירס","אמריקה",'פירוש השם: "רוחות טובות". הטנגו נולד בשכונות הנמל שלה, בסוף המאה ה-19.',["בואנוס איירס היא בירתה של איזו מדינה?","ארגנטינה"]],["מהי בירת קנדה?","אוטווה","אמריקה","נבחרה בידי המלכה ויקטוריה ב-1857 — פשרה בין טורונטו דוברת האנגלית למונטריאול דוברת הצרפתית. בחורף התעלה בעיר הופכת למסלול החלקה ארוך.",["אוטווה היא בירתה של איזו מדינה?","קנדה"]],["מהי בירת אוסטרליה?","קנברה","אוקיאניה","פשרה בין סידני למלבורן, שכל אחת רצתה להיות הבירה. העיר תוכננה במיוחד, אחרי תחרות אדריכלים בינלאומית.",["קנברה היא בירתה של איזו מדינה?","אוסטרליה"]],["מהי בירת מקסיקו?","מקסיקו סיטי","אמריקה","נבנתה על חורבות טנוצ׳טיטלן, בירת האצטקים, שעמדה על אי באגם. בגלל הקרקע הבוצית, חלקים מהעיר שוקעים כמה סנטימטרים בשנה.",null],["מהי בירת הולנד?","אמסטרדם","אירופה","הבירה הרשמית — אבל הממשלה והפרלמנט יושבים בהאג. יש בה יותר מ-100 קילומטרים של תעלות.",["אמסטרדם היא בירתה של איזו מדינה?","הולנד"]],["מהי בירת בלגיה?","בריסל","אירופה",'מושב הנציבות האירופית ומטה נאט״ו. סמל העיר הוא פסל זעיר: "מאנקן פיס", ילד קטן שמשתין למזרקה.',["בריסל היא בירתה של איזו מדינה?","בלגיה"]],["מהי בירת פורטוגל?","ליסבון","אירופה","בנויה על שבע גבעות, כמו רומא. ב-1755 החריבו אותה רעידת אדמה וצונאמי — מהאסונות הגדולים בתולדות אירופה.",["ליסבון היא בירתה של איזו מדינה?","פורטוגל"]],["מהי בירת אוסטריה?","וינה","אירופה","בירת האימפריה ההבסבורגית, ועירם של מוצרט, בטהובן ושטראוס. גם פרויד והרצל חיו בה.",["וינה היא בירתה של איזו מדינה?","אוסטריה"]],["מהי בירת שווייץ?","ברן","אירופה",'רשמית אין לשווייץ בירה: ברן היא "העיר הפדרלית", קטנה בהרבה מציריך ומז׳נבה. הדוב הוא סמל העיר — ולפי האגדה גם מקור שמה.',["ברן היא בירתה של איזו מדינה?","שווייץ"]],["מהי בירת שוודיה?","שטוקהולם","אירופה","בנויה על 14 איים, במקום שבו אגם מלארן פוגש את הים הבלטי. כאן מוענקים פרסי נובל — כולם, מלבד פרס השלום.",["שטוקהולם היא בירתה של איזו מדינה?","שוודיה"]],["מהי בירת נורווגיה?","אוסלו","אירופה","כאן מוענק פרס נובל לשלום, בניגוד לשאר הפרסים שמוענקים בשטוקהולם. בעבר נקראה כריסטיאניה.",["אוסלו היא בירתה של איזו מדינה?","נורווגיה"]],["מהי בירת דנמרק?","קופנהגן","אירופה",'פירוש השם: "נמל הסוחרים". פסל בת הים הקטנה, לפי סיפורו של הנס כריסטיאן אנדרסן, הוא סמל העיר.',["קופנהגן היא בירתה של איזו מדינה?","דנמרק"]],["מהי בירת פולין?","ורשה","אירופה","בגטו ורשה, הגדול באירופה, פרץ ב-1943 מרד הגטו. העיר העתיקה, שהנאצים פוצצו כמעט כולה, נבנתה מחדש לפי ציורים ותצלומים.",["ורשה היא בירתה של איזו מדינה?","פולין"]],["מהי בירת צ׳כיה?","פראג","אירופה",'"עיר מאה הצריחים". בה חי פרנץ קפקא, ובה, לפי האגדה, יצר המהר״ל את הגולם.',["פראג היא בירתה של איזו מדינה?","צ׳כיה"]],["מהי בירת הונגריה?","בודפשט","אירופה","שתי ערים שהתאחדו ב-1873: בודה על הגבעות, ופשט במישור — משני צידי הדנובה. הרצל נולד בפשט.",["בודפשט היא בירתה של איזו מדינה?","הונגריה"]],["מהי בירת אירלנד?","דבלין","אירופה",'בגאלית: "בריכה שחורה". כאן מתרחשת עלילת "יוליסס" של ג׳יימס ג׳ויס, וכאן מבשלים את הגינס.',["דבלין היא בירתה של איזו מדינה?","אירלנד"]],["מהי בירת פינלנד?","הלסינקי","אירופה","בנויה על חצי אי ועל איים בים הבלטי. עד 1917 הייתה תחת שלטון רוסיה, ולפני כן — שוודיה.",["הלסינקי היא בירתה של איזו מדינה?","פינלנד"]],["מהי בירת אוקראינה?","קייב","אירופה",'מהערים העתיקות במזרח אירופה — מרכזה של ממלכת "רוס של קייב" לפני יותר מאלף שנה. גולדה מאיר נולדה בה.',["קייב היא בירתה של איזו מדינה?","אוקראינה"]],["מהי בירת איראן?","טהרן","אסיה","בירה רק מסוף המאה ה-18. מאחוריה מתנשאים הרי אלבורז, ובהם הר דמוונד — הגבוה במזרח התיכון.",["טהרן היא בירתה של איזו מדינה?","איראן"]],["מהי בירת עיראק?","בגדד","אסיה",'נוסדה ב-762 כ"עיר העגולה" של הח׳ליפים העבאסים. בימי הביניים — מהערים הגדולות בעולם, ועיר "אלף לילה ולילה".',["בגדד היא בירתה של איזו מדינה?","עיראק"]],["מהי בירת ערב הסעודית?","ריאד","אסיה",'פירוש השם בערבית: "גנים" — היא צמחה סביב נווה מדבר בלב חצי האי ערב.',["ריאד היא בירתה של איזו מדינה?","ערב הסעודית"]],["מהי בירת ירדן?","עמאן","אסיה","בשמה העתיק, רבת עמון, היא מוזכרת בתנ״ך. בתקופה הרומית נקראה פילדלפיה.",["עמאן היא בירתה של איזו מדינה?","ירדן"]],["מהי בירת לבנון?","ביירות","אסיה",'כונתה בעבר "פריז של המזרח התיכון". ב-2020 הרס פיצוץ ענק בנמל חלקים גדולים מהעיר.',["ביירות היא בירתה של איזו מדינה?","לבנון"]],["מהי בירת סוריה?","דמשק","אסיה",'נחשבת לאחת הערים העתיקות בעולם שמיושבות ברציפות. "הרחוב הישר" שלה מוזכר כבר בברית החדשה.',["דמשק היא בירתה של איזו מדינה?","סוריה"]],["מהי בירת דרום אפריקה (המנהלית)?","פרטוריה","אפריקה",'אחת משלוש הבירות: כאן יושבת הממשלה. באביב רחובותיה מתמלאים בעצי ז׳קרנדה סגולים — ומכאן הכינוי "עיר הז׳קרנדה".',["פרטוריה היא הבירה המנהלית של איזו מדינה?","דרום אפריקה"]],["מהי בירת תאילנד?","בנגקוק","אסיה",'השם המלא שלה בתאית הוא מהשמות הארוכים בעולם. התאים קוראים לה בקיצור "קרונג תפ" — "עיר המלאכים".',["בנגקוק היא בירתה של איזו מדינה?","תאילנד"]],["מהי בירת וייטנאם?","האנוי","אסיה",'פירוש השם: "בתוך הנהר" — היא שוכנת בעיקול של הנהר האדום. העיר חגגה אלף שנה ב-2010.',["האנוי היא בירתה של איזו מדינה?","וייטנאם"]],["מהי בירת דרום קוריאה?","סיאול","אסיה","כמחצית מתושבי דרום קוריאה גרים במטרופולין שלה — ורק כ-50 ק״מ מפרידים בינה לבין הגבול עם הצפון.",["סיאול היא בירתה של איזו מדינה?","דרום קוריאה"]],["מהי בירת צפון קוריאה?","פיונגיאנג","אסיה","נבנתה מחדש כמעט כולה אחרי מלחמת קוריאה, ברחובות רחבים ובמונומנטים. רק מי שנחשב נאמן למשטר רשאי לגור בה.",["פיונגיאנג היא בירתה של איזו מדינה?","צפון קוריאה"]],["מהי בירת אינדונזיה?","ג׳קרטה","אסיה","שוקעת מהר: חלקים ממנה ירדו כמה מטרים בעשורים האחרונים. לכן אינדונזיה בונה בירה חדשה, נוסנטרה, באי בורנאו.",["ג׳קרטה היא בירתה של איזו מדינה?","אינדונזיה"]],["מהי בירת הפיליפינים?","מנילה","אסיה",'מהערים הצפופות בעולם. במאה ה-16 בנו בה הספרדים את "אינטרמורוס" — העיר המוקפת חומה.',["מנילה היא בירתה של איזו מדינה?","הפיליפינים"]],["מהי בירת מלזיה?","קואלה לומפור","אסיה",'פירוש השם במלאית: "שפך בוצי" — במפגש שני נהרות. מגדלי פטרונס התאומים היו הבניינים הגבוהים בעולם בשנים 1998–2004.',["קואלה לומפור היא בירתה של איזו מדינה?","מלזיה"]],["מהי בירת סינגפור?","סינגפור","אסיה","המדינה כולה עיר אחת. ב-1965 נפרדה מהפדרציה המלזית, והפכה מנמל קטן לאחד המרכזים הפיננסיים של העולם.",null],["מהי בירת פקיסטן?","איסלמאבאד","אסיה",'נבנתה במיוחד כבירה בשנות ה-60, במקום קראצ׳י. פירוש השם: "עיר האסלאם".',["איסלמאבאד היא בירתה של איזו מדינה?","פקיסטן"]],["מהי בירת אפגניסטן?","קאבול","אסיה","שוכנת בעמק בגובה של כ-1,800 מטר, בין רכסי ההינדו כוש — מהבירות הגבוהות בעולם.",["קאבול היא בירתה של איזו מדינה?","אפגניסטן"]],["מהי בירת מרוקו?","רבאט","אפריקה","רבים בטוחים שהבירה היא קזבלנקה או מרקש — אבל זו רבאט, על חוף האוקיינוס האטלנטי.",["רבאט היא בירתה של איזו מדינה?","מרוקו"]],["מהי בירת תוניסיה?","תוניס","אפריקה","בשוליה חורבות קרתגו — העיר הפיניקית שהתחרתה ברומא על השליטה בים התיכון, עד שנחרבה ב-146 לפנה״ס.",null],["מהי בירת אלג׳יריה?","אלג׳יר","אפריקה",'"אל-ג׳זאיר" — "האיים" בערבית, על שם איים קטנים מול החוף. הקסבה, העיר העתיקה, היא אתר מורשת עולמית.',null],["מהי בירת לוב?","טריפולי","אפריקה",'פירוש השם ביוונית: "שלוש ערים". יש עוד טריפולי — בצפון לבנון.',["טריפולי היא בירתה של איזו מדינה?","לוב"]],["מהי בירת ניגריה?","אבוג׳ה","אפריקה","נבנתה בשנות ה-80 במרכז המדינה, והחליפה את לאגוס כבירה ב-1991 — כדי שתהיה ניטרלית בין הקבוצות האתניות.",["אבוג׳ה היא בירתה של איזו מדינה?","ניגריה"]],["מהי בירת קניה?","ניירובי","אפריקה",'בשפת המסאי: "מים קרים". יש בה שמורת טבע ממש בשולי העיר — ג׳ירפות על רקע גורדי שחקים.',["ניירובי היא בירתה של איזו מדינה?","קניה"]],["מהי בירת אתיופיה?","אדיס אבבה","אפריקה",'פירוש השם באמהרית: "פרח חדש". כאן יושב מטה האיחוד האפריקאי, והיא מהבירות הגבוהות בעולם — כ-2,350 מטר.',["אדיס אבבה היא בירתה של איזו מדינה?","אתיופיה"]],["מהי בירת גאנה?","אקרה","אפריקה","על חוף מפרץ גינאה — הבירה הקרובה ביותר לנקודה שבה קו המשווה פוגש את קו האורך אפס.",["אקרה היא בירתה של איזו מדינה?","גאנה"]],["מהי בירת קובה?","הוואנה","אמריקה","העיר העתיקה, עם המבצרים הספרדיים, היא אתר מורשת עולמית. ברחובותיה עוד נוסעות מכוניות אמריקאיות משנות ה-50.",["הוואנה היא בירתה של איזו מדינה?","קובה"]],["מהי בירת צ׳ילה?","סנטיאגו","אמריקה","שוכנת בעמק בין האנדים להרי החוף, ובחורף רואים ממנה פסגות מושלגות.",["סנטיאגו היא בירתה של איזו מדינה?","צ׳ילה"]],["מהי בירת פרו?","לימה","אמריקה","נוסדה בידי הכובש הספרדי פיסארו ב-1535. כמעט לא יורד בה גשם, אבל רוב החורף היא עטופה בערפל.",["לימה היא בירתה של איזו מדינה?","פרו"]],["מהי בירת קולומביה?","בוגוטה","אמריקה","יושבת על רמה בגובה של כ-2,600 מטר באנדים — מהבירות הגבוהות בעולם.",["בוגוטה היא בירתה של איזו מדינה?","קולומביה"]],["מהי בירת ונצואלה?","קראקס","אמריקה","עיר הולדתו של סימון בוליבר, משחרר דרום אמריקה מהשלטון הספרדי.",["קראקס היא בירתה של איזו מדינה?","ונצואלה"]],["מהי בירת ניו זילנד?","וולינגטון","אוקיאניה",'הבירה הדרומית בעולם של מדינה ריבונית, ומהסוערות שבהן — מכונה "וולינגטון הסוערת".',["וולינגטון היא בירתה של איזו מדינה?","ניו זילנד"]],["מהי בירת רומניה?","בוקרשט","אירופה","ארמון הפרלמנט שבנה בה הרודן צ׳אושסקו הוא מהבניינים הגדולים והכבדים בעולם.",["בוקרשט היא בירתה של איזו מדינה?","רומניה"]],["מהי בירת בולגריה?","סופיה","אירופה","קרויה על שם כנסיית סופיה הקדושה העתיקה שבה. הר ויטושה, שמעל העיר, משמש בחורף אתר סקי.",["סופיה היא בירתה של איזו מדינה?","בולגריה"]],["מהי בירת קרואטיה?","זאגרב","אירופה",'בה "מוזיאון הקשרים השבורים", שמציג חפצים שנשארו אחרי פרידות של זוגות מכל העולם.',["זאגרב היא בירתה של איזו מדינה?","קרואטיה"]],["מהי בירת סרביה?","בלגרד","אירופה",'פירוש השם: "העיר הלבנה". בגלל מיקומה, על מפגש הסאווה והדנובה, נכבשה ונהרסה עשרות פעמים בהיסטוריה.',["בלגרד היא בירתה של איזו מדינה?","סרביה"]],["מהי בירת איסלנד?","רייקיאוויק","אירופה","כשני שלישים מתושבי איסלנד גרים בה ובפרבריה. הכנסייה הגדולה שלה, הלגרימסקירקיה, מעוצבת בהשראת עמודי בזלת.",["רייקיאוויק היא בירתה של איזו מדינה?","איסלנד"]],["מהי בירת בלארוס?","מינסק","אירופה","כמעט נהרסה כולה במלחמת העולם השנייה, ונבנתה מחדש בסגנון סובייטי מונומנטלי.",["מינסק היא בירתה של איזו מדינה?","בלארוס"]],["מהי בירת קזחסטן?","אסטנה","אסיה",'שינתה את שמה כמה פעמים: אקמולה, אסטנה, נור-סולטן — ושוב אסטנה, ב-2022. "אסטנה" בקזחית פירושו פשוט "בירה".',["אסטנה היא בירתה של איזו מדינה?","קזחסטן"]],["מהי בירת איחוד האמירויות?","אבו דאבי","אסיה","הבירה היא אבו דאבי ולא דובאי, אף שדובאי מפורסמת יותר. היא בנויה על אי, והאמירות שלה היא העשירה מבין השבע.",["אבו דאבי היא בירתה של איזו מדינה?","איחוד האמירויות"]],["מהי בירת קטר?","דוחא","אסיה","צמחה מכפר של דייגים וצוללני פנינים לעיר של גורדי שחקים בתוך עשרות שנים, בזכות הגז הטבעי.",["דוחא היא בירתה של איזו מדינה?","קטר"]],["מהי בירת כווית?","כווית סיטי","אסיה","מגדלי כווית — שלושה מגדלים עם כדורים — הם סמל העיר. בקיץ הטמפרטורה בה עוברת לא פעם את 50 המעלות.",null],["מהי בירת תימן?","צנעא","אסיה","מהערים העתיקות שמיושבות ברציפות, בגובה של כ-2,300 מטר. בתי המגדל המעוטרים שבעיר העתיקה הם אתר מורשת עולמית.",["צנעא היא בירתה של איזו מדינה?","תימן"]],["מהי בירת עומאן?","מסקט","אסיה","על חוף מפרץ עומאן, בין הרים לים. במשך מאות שנים — נמל מסחר חשוב בדרך להודו ולמזרח אפריקה.",["מסקט היא בירתה של איזו מדינה?","עומאן"]],["מהי בירת בחריין?","מנאמה","אסיה","יושבת על האי הגדול של בחריין, שמחובר לערב הסעודית בגשר המלך פהד — כ-25 ק״מ מעל הים.",["מנאמה היא בירתה של איזו מדינה?","בחריין"]],["מהי בירת קפריסין?","ניקוסיה","אירופה",'הבירה המחולקת האחרונה באירופה: "הקו הירוק" חוצה אותה בין הצד היווני לצד הטורקי.',["ניקוסיה היא בירתה של איזו מדינה?","קפריסין"]],["מהי בירת מלטה?","ולטה","אירופה","מהבירות הקטנות באירופה, פחות מקילומטר רבוע. נבנתה במאה ה-16 בידי אבירי מסדר יוחנן הקדוש.",["ולטה היא בירתה של איזו מדינה?","מלטה"]],["מהי בירת לוקסמבורג?","לוקסמבורג","אירופה",'בנויה על צוקים מעל ערוצים עמוקים, ומבוצרת כל כך שכונתה "גיברלטר של הצפון".',null],["מהי בירת סלובקיה?","ברטיסלבה","אירופה","הבירה היחידה בעולם שגובלת בשתי מדינות: אוסטריה והונגריה.",["ברטיסלבה היא בירתה של איזו מדינה?","סלובקיה"]],["מהי בירת סלובניה?","ליובליאנה","אירופה","הדרקון הוא סמל העיר — לפי האגדה, יאסון והארגונאוטים הרגו כאן דרקון. מרכז העיר סגור לתנועת מכוניות.",["ליובליאנה היא בירתה של איזו מדינה?","סלובניה"]],["מהי בירת אסטוניה?","טאלין","אירופה","העיר העתיקה שלה, מימי הביניים, מהשמורות באירופה. בית מרקחת שבכיכר העירייה פועל, לפי המסורת, מ-1422.",["טאלין היא בירתה של איזו מדינה?","אסטוניה"]],["מהי בירת לטביה?","ריגה","אירופה","העיר הגדולה באזור הבלטי, עם ריכוז עצום של בנייני אר נובו — כשליש מהבניינים במרכז העיר.",["ריגה היא בירתה של איזו מדינה?","לטביה"]],["מהי בירת ליטא?","וילנה","אירופה",'"ירושלים של ליטא" — מרכז הלימוד היהודי במזרח אירופה, ועירו של הגאון מווילנה במאה ה-18.',["וילנה היא בירתה של איזו מדינה?","ליטא"]],["מהי בירת בנגלדש?","דאקה","אסיה",'"עיר המסגדים", ומהערים הצפופות בעולם. ברחובותיה נעים מאות אלפי ריקשות אופניים.',["דאקה היא בירתה של איזו מדינה?","בנגלדש"]],["מהי בירת נפאל?","קטמנדו","אסיה","בעמק בגובה של כ-1,400 מטר, מוקפת בהרי ההימלאיה — נקודת המוצא של רוב המסעות לאוורסט.",["קטמנדו היא בירתה של איזו מדינה?","נפאל"]],["מהי בירת מיאנמר?","נאיפידאו","אסיה","בירה מתוכננת שנבנתה בחשאיות ונחנכה ב-2005. בכבישים הרחבים שלה, עם עשרות נתיבים, כמעט אין תנועה.",["נאיפידאו היא בירתה של איזו מדינה?","מיאנמר"]],["מהי בירת קמבודיה?","פנום פן","אסיה","על מפגש נהרות המקונג והטונלה סאפ. ב-1975 פינו ממנה הקמר רוז׳ את כל התושבים לכפרים.",["פנום פן היא בירתה של איזו מדינה?","קמבודיה"]],["מהי בירת סרי לנקה (הרשמית)?","סרי ג׳איוורדנפורה קוטה","אסיה","פרבר של קולומבו, העיר הגדולה, שבה נמצאים רוב משרדי הממשלה. הפרלמנט יושב על אי באגם מלאכותי.",["סרי ג׳איוורדנפורה קוטה היא הבירה הרשמית של איזו מדינה?","סרי לנקה"]],["מהי בירת בוסניה והרצגובינה?","סרייבו","אירופה","כאן נרצח פרנץ פרדיננד ב-1914 — היריות שהציתו את מלחמת העולם הראשונה. ב-1984 אירחה את אולימפיאדת החורף.",["סרייבו היא בירתה של איזו מדינה?","בוסניה והרצגובינה"]],["מהי בירת אלבניה?","טירנה","אירופה","בניינים רבים בה צבועים בצבעים עזים — יוזמה של ראש העירייה (ולימים ראש הממשלה) אדי ראמה, שהוא גם צייר.",["טירנה היא בירתה של איזו מדינה?","אלבניה"]],["מהי בירת צפון מקדוניה?","סקופיה","אירופה",'עיר הולדתה של אמא תרזה. מרכז העיר מלא בעשרות פסלים ומונומנטים שהוקמו בפרויקט שנוי במחלוקת, "סקופיה 2014".',["סקופיה היא בירתה של איזו מדינה?","צפון מקדוניה"]],["מהי בירת מונטנגרו?","פודגוריצה","אירופה","בזמן יוגוסלביה נקראה טיטוגרד, על שם טיטו. היא נהרסה כמעט כולה בהפצצות של מלחמת העולם השנייה.",["פודגוריצה היא בירתה של איזו מדינה?","מונטנגרו"]],["מהי בירת מולדובה?","קישינב","אירופה",'בפוגרום קישינב ב-1903 נרצחו כ-50 יהודים, וביאליק כתב בעקבותיו את "בעיר ההרגה".',["קישינב היא בירתה של איזו מדינה?","מולדובה"]],["מהי בירת גאורגיה?","טביליסי","אסיה",'פירוש השם: "חם" — על שם המעיינות החמים שבה. בעיר העתיקה בתי מרחץ גופרתיים עם כיפות.',["טביליסי היא בירתה של איזו מדינה?","גאורגיה"]],["מהי בירת ארמניה?","ירוואן","אסיה","מהערים העתיקות שמיושבות ברציפות — נוסדה ב-782 לפנה״ס, לפני רומא. הר אררט המושלג נשקף ממנה.",["ירוואן היא בירתה של איזו מדינה?","ארמניה"]],["מהי בירת אזרבייג׳ן?","באקו","אסיה","הבירה הנמוכה בעולם — כ-28 מטר מתחת לפני הים, על חוף הים הכספי.",["באקו היא בירתה של איזו מדינה?","אזרבייג׳ן"]],["מהי בירת אוזבקיסטן?","טשקנט","אסיה","העיר הגדולה במרכז אסיה. אחרי רעידת אדמה ב-1966 נבנתה מחדש כעיר סובייטית לדוגמה.",["טשקנט היא בירתה של איזו מדינה?","אוזבקיסטן"]],["מהי בירת טורקמניסטן?","אשגבט","אסיה","עיר של בניינים מצופים שיש לבן — היא אפילו רשומה בספר השיאים בזכות זה.",["אשגבט היא בירתה של איזו מדינה?","טורקמניסטן"]],["מהי בירת קירגיזסטן?","בישקק","אסיה","בתקופה הסובייטית נקראה פרונזה. הפסגות המושלגות של רכס טיין שאן נשקפות כמעט מכל מקום בה.",["בישקק היא בירתה של איזו מדינה?","קירגיזסטן"]],["מהי בירת טג׳יקיסטן?","דושנבה","אסיה",'פירוש השם בטג׳יקית: "יום שני" — על שם שוק שהתקיים בה בימי שני.',["דושנבה היא בירתה של איזו מדינה?","טג׳יקיסטן"]],["מהי בירת מונגוליה?","אולן בטור","אסיה","הבירה הקרה בעולם — הטמפרטורה הממוצעת בה לאורך השנה מתחת לאפס. כמעט חצי מתושבי מונגוליה גרים בה.",["אולן בטור היא בירתה של איזו מדינה?","מונגוליה"]],["מהי בירת לאוס?","ויינטיאן","אסיה","על גדות המקונג, מול תאילנד. מהבירות השקטות באסיה, עם שער ניצחון משלה — פטוקסאי.",["ויינטיאן היא בירתה של איזו מדינה?","לאוס"]],["מהי בירת ברוניי?","בנדר סרי בגאואן","אסיה",'חלק ממנה הוא "כפר מים" עתיק: בתים על כלונסאות מעל הנהר, שבהם גרים אלפי אנשים.',["בנדר סרי בגאואן היא בירתה של איזו מדינה?","ברוניי"]],["מהי בירת האיים המלדיביים?","מאלה","אסיה","מהבירות הצפופות בעולם: עשרות אלפי אנשים על אי שאורכו כשני קילומטרים. שדה התעופה יושב על אי נפרד.",["מאלה היא בירתה של איזו מדינה?","האיים המלדיביים"]],["מהי בירת בהוטן?","טהימפו","אסיה","הבירה היחידה בעולם בלי רמזורים: שוטר תנועה מכוון את התנועה בצומת המרכזי.",["טהימפו היא בירתה של איזו מדינה?","בהוטן"]],["מהי בירת טימור המזרחית?","דילי","אסיה",'על חוף הים, ובשוליה פסל ענק של ישו — "קריסטו ריי" — שהוקם ב-1996.',["דילי היא בירתה של איזו מדינה?","טימור המזרחית"]],["מהי בירת סודן?","חרטום","אפריקה",'במפגש הנילוס הלבן והנילוס הכחול. לפי ההסבר הנפוץ, השם בערבית פירושו "חדק" — על שם צורת רצועת הקרקע שבין הנהרות.',["חרטום היא בירתה של איזו מדינה?","סודן"]],["מהי בירת דרום סודן?","ג׳ובה","אפריקה","הבירה של המדינה הצעירה בעולם, על גדות הנילוס הלבן. רוב הרחובות בה עדיין לא סלולים.",["ג׳ובה היא בירתה של איזו מדינה?","דרום סודן"]],["מהי בירת סומליה?","מוגדישו","אפריקה","נמל עתיק על האוקיינוס ההודי, שסחר עם ערב, פרס וסין כבר בימי הביניים.",["מוגדישו היא בירתה של איזו מדינה?","סומליה"]],["מהי בירת אריתריאה?","אסמרה","אפריקה",'"רומא הקטנה": עשרות מבנים בסגנון ארט דקו ופוטוריסטי מהתקופה האיטלקית — אתר מורשת עולמית.',["אסמרה היא בירתה של איזו מדינה?","אריתריאה"]],["מהי בירת ג׳יבוטי?","ג׳יבוטי","אפריקה","נמל אסטרטגי בכניסה לים סוף. בתחומה יושבים בסיסים צבאיים של ארה״ב, צרפת, סין ויפן.",null],["מהי בירת טנזניה (הרשמית)?","דודומה","אפריקה","הוכרזה כבירה כבר ב-1973, אבל דאר א-סלאם שעל החוף נשארה העיר הגדולה ומרכז הכלכלה.",["דודומה היא הבירה הרשמית של איזו מדינה?","טנזניה"]],["מהי בירת אוגנדה?","קמפלה","אפריקה","נבנתה על גבעות, והשם בא מסוג של אנטילופה שחי פעם באזור — האימפלה.",["קמפלה היא בירתה של איזו מדינה?","אוגנדה"]],["מהי בירת רואנדה?","קיגלי","אפריקה",'מהבירות הנקיות באפריקה: פעם בחודש, ביום "אומוגנדה", התושבים יוצאים לעבודה קהילתית.',["קיגלי היא בירתה של איזו מדינה?","רואנדה"]],["מהי בירת בורונדי (הרשמית)?","גיטגה","אפריקה","הבירה הפוליטית מאז 2019, במרכז המדינה. בוז׳ומבורה, על אגם טנגניקה, נשארה המרכז הכלכלי.",["גיטגה היא הבירה הרשמית של איזו מדינה?","בורונדי"]],["מהי בירת הרפובליקה הדמוקרטית של קונגו?","קינשאסה","אפריקה","העיר הגדולה בעולם ששפתה הרשמית צרפתית — גדולה אפילו מפריז. בעבר נקראה לאופולדוויל.",["קינשאסה היא בירתה של איזו מדינה?","הרפובליקה הדמוקרטית של קונגו"]],["מהי בירת רפובליקת קונגו?","ברזוויל","אפריקה",'על גדת נהר קונגו, מול קינשאסה. במלחמת העולם השנייה הייתה בירת "צרפת החופשית" של דה גול.',["ברזוויל היא בירתה של איזו מדינה?","רפובליקת קונגו"]],["מהי בירת אנגולה?","לואנדה","אפריקה","נמל שהפורטוגזים ייסדו ב-1576. בעשור הקודם נחשבה לאחת הערים היקרות בעולם, בזכות — ובגלל — הנפט.",["לואנדה היא בירתה של איזו מדינה?","אנגולה"]],["מהי בירת זמביה?","לוסקה","אפריקה","צמחה כתחנה על מסילת הרכבת בתחילת המאה ה-20, והפכה לבירה ב-1935.",["לוסקה היא בירתה של איזו מדינה?","זמביה"]],["מהי בירת זימבבואה?","הרארה","אפריקה","בעבר נקראה סולסברי, על שם ראש ממשלת בריטניה. היא שוכנת על רמה בגובה של כ-1,500 מטר, ולכן מזג האוויר בה נוח.",["הרארה היא בירתה של איזו מדינה?","זימבבואה"]],["מהי בירת מוזמביק?","מאפוטו","אפריקה","נמל על האוקיינוס ההודי, שנקרא בעבר לורנסו מרקש. תחנת הרכבת המפוארת שלה מיוחסת, כנראה בטעות, לגוסטב אייפל.",["מאפוטו היא בירתה של איזו מדינה?","מוזמביק"]],["מהי בירת מדגסקר?","אנטננריבו","אפריקה",'פירוש השם במלגשית: "עיר האלף" — על שם אלף לוחמים ששמרו עליה. היא בנויה על רכס של גבעות.',["אנטננריבו היא בירתה של איזו מדינה?","מדגסקר"]],["מהי בירת נמיביה?","וינדהוק","אפריקה","עדיין מורגשת בה ההשפעה הגרמנית — נמיביה הייתה מושבה גרמנית. עומדת בה כנסייה לותרנית בסגנון גרמני, ומתקיים בה אוקטוברפסט.",["וינדהוק היא בירתה של איזו מדינה?","נמיביה"]],["מהי בירת בוצוואנה?","חבורונה","אפריקה","נבנתה כמעט מאפס לקראת העצמאות ב-1966, והפכה לאחת הערים הצומחות במהירות באפריקה.",["חבורונה היא בירתה של איזו מדינה?","בוצוואנה"]],["מהי בירת סנגל?","דקאר","אפריקה","על חצי האי כף ורדה — הנקודה המערבית ביותר ביבשת אפריקה. מוכרת מראלי פריז-דקאר.",["דקאר היא בירתה של איזו מדינה?","סנגל"]],["מהי בירת מאלי?","במאקו","אפריקה",'על גדות נהר ניז׳ר. השם בשפת במבארה: "נהר התנינים".',["במאקו היא בירתה של איזו מדינה?","מאלי"]],["מהי בירת חוף השנהב (הרשמית)?","יאמוסוקרו","אפריקה",'עיר הולדתו של הנשיא הראשון, שבנה בה את "גבירתנו של השלום" — מהכנסיות הגדולות בעולם. הכלכלה מרוכזת באביג׳אן.',["יאמוסוקרו היא הבירה הרשמית של איזו מדינה?","חוף השנהב"]],["מהי בירת קמרון?","יאונדה","אפריקה",'העיר השנייה בגודלה בקמרון — הגדולה היא דואלה, עיר הנמל. יאונדה מכונה "עיר שבע הגבעות".',["יאונדה היא בירתה של איזו מדינה?","קמרון"]],["מהי בירת אורוגוואי?","מונטווידאו","אמריקה","הבירה הדרומית ביותר ביבשת אמריקה, וכמחצית מתושבי אורוגוואי גרים בה.",["מונטווידאו היא בירתה של איזו מדינה?","אורוגוואי"]],["מהי בירת פרגוואי?","אסונסיון","אמריקה",'מהערים העתיקות בדרום אמריקה — נוסדה ב-1537, ומכונה "אם הערים".',["אסונסיון היא בירתה של איזו מדינה?","פרגוואי"]],["מהי בירת בוליביה (מושב הממשלה)?","לה פאס","אמריקה","מושב הממשלה הגבוה בעולם — כ-3,600 מטר. רכבל עירוני מחבר אותה לעיר אל אלטו שמעליה. הבירה החוקתית היא סוקרה.",["לה פאס היא מושב הממשלה של איזו מדינה?","בוליביה"]],["מהי בירת אקוודור?","קיטו","אמריקה","כ-2,850 מטר מעל פני הים, וכמעט על קו המשווה. העיר העתיקה שלה הייתה מהראשונות שהוכרזו אתר מורשת עולמית, ב-1978.",["קיטו היא בירתה של איזו מדינה?","אקוודור"]],["מהי בירת גואטמלה?","גואטמלה סיטי","אמריקה","הבירה עברה אליה אחרי שרעידות אדמה הרסו את הבירה הקודמת, אנטיגואה, ב-1773.",null],["מהי בירת קוסטה ריקה?","סן חוסה","אמריקה","מהערים הראשונות בעולם שהותקנה בהן תאורת רחוב חשמלית — ב-1884.",["סן חוסה היא בירתה של איזו מדינה?","קוסטה ריקה"]],["מהי בירת פנמה?","פנמה סיטי","אמריקה","בתוך גבולות העיר שוכן יער גשם טרופי — הפארק המטרופוליטני. וממנה נשקפות הספינות שנכנסות לתעלה.",null],["מהי בירת ג׳מייקה?","קינגסטון","אמריקה","הנמל הטבעי שלה מהגדולים בעולם. כאן פעל בוב מארלי — ביתו הוא היום מוזיאון.",["קינגסטון היא בירתה של איזו מדינה?","ג׳מייקה"]],["מהי בירת האיטי?","פורט-או-פרנס","אמריקה","נפגעה קשות ברעידת האדמה של 2010, שבה נהרגו יותר מ-200 אלף איש.",["פורט-או-פרנס היא בירתה של איזו מדינה?","האיטי"]],["מהי בירת הרפובליקה הדומיניקנית?","סנטו דומינגו","אמריקה","העיר האירופית העתיקה ביבשת אמריקה שמיושבת ברציפות — נוסדה ב-1496. בה הקתדרלה הראשונה ביבשת.",["סנטו דומינגו היא בירתה של איזו מדינה?","הרפובליקה הדומיניקנית"]],["מהי בירת פיג׳י?","סובה","אוקיאניה","העיר הגדולה בפיג׳י, על חוף האי ויטי לבו. יושבים בה מוסדות אזוריים של מדינות האוקיינוס השקט.",["סובה היא בירתה של איזו מדינה?","פיג׳י"]],["מהי בירת פפואה גינאה החדשה?","פורט מורסבי","אוקיאניה","העיר הגדולה באיי האוקיינוס השקט. נקראה על שם אביו של הקפטן הבריטי ג׳ון מורסבי, שהגיע אליה ב-1873.",["פורט מורסבי היא בירתה של איזו מדינה?","פפואה גינאה החדשה"]],["מהי בירת אנדורה?","אנדורה לה וייה","אירופה","הבירה הגבוהה באירופה — כ-1,000 מטר מעל פני הים, בעמק בהרי הפירנאים.",null],["מהי בירת מונקו?","מונקו","אירופה","מונטה קרלו, עם הקזינו המפורסם, היא רובע שלה — ומרוץ הפורמולה 1 עובר ברחובותיה הצרים.",null],["מהי בירת סן מרינו?","סן מרינו","אירופה","העיר יושבת על הר טיטאנו, ושלושת המגדלים שעל פסגתו מופיעים על הדגל.",null],["מהי בירת ליכטנשטיין?","ואדוץ","אירופה","עיירה של כ-5,000 תושבים, מתחת לטירת הנסיך שעל הצוק — והנסיך גר בה עד היום.",["ואדוץ היא בירתה של איזו מדינה?","ליכטנשטיין"]],["מהי בירת הוותיקן?","העיר הוותיקן","אירופה","בתוכה בזיליקת פטרוס הקדוש והקפלה הסיסטינית, שאת תקרתה צייר מיכלאנג׳לו.",null],["מהי בירת קוסובו?","פרישטינה","אירופה","בה פסל ענק של ביל קלינטון ושדרה על שמו — תודה על התערבות נאט״ו ב-1999.",["פרישטינה היא בירתה של איזו מדינה?","קוסובו"]],["מהי בירת צ׳אד?","נג׳מנה","אפריקה","בעבר נקראה פור לאמי. היא שוכנת על הגבול עם קמרון, ממש מעבר לנהר.",["נג׳מנה היא בירתה של איזו מדינה?","צ׳אד"]],["מהי בירת ניז׳ר?","ניאמיי","אפריקה","על גדות נהר ניז׳ר. לא הרחק ממנה חיים העדרים האחרונים של ג׳ירפות מערב אפריקה.",["ניאמיי היא בירתה של איזו מדינה?","ניז׳ר"]],["מהי בירת בורקינה פאסו?","וואגאדוגו","אפריקה","מארחת את פספאקו — פסטיבל הקולנוע הגדול באפריקה, מאז 1969.",["וואגאדוגו היא בירתה של איזו מדינה?","בורקינה פאסו"]],["מהי בירת בנין (הרשמית)?","פורטו נובו","אפריקה",'פירוש השם בפורטוגזית: "נמל חדש". הממשלה יושבת ברובה בקוטונו, העיר הגדולה.',["פורטו נובו היא הבירה הרשמית של איזו מדינה?","בנין"]],["מהי בירת טוגו?","לומה","אפריקה","בירה על הגבול ממש — עם גאנה. אחד השווקים המפורסמים בה מתמחה בחומרים לטקסי וודו.",["לומה היא בירתה של איזו מדינה?","טוגו"]],["מהי בירת גינאה?","קונאקרי","אפריקה","נבנתה על חצי אי צר שנמשך אל תוך האוקיינוס האטלנטי.",["קונאקרי היא בירתה של איזו מדינה?","גינאה"]],["מהי בירת גינאה ביסאו?","ביסאו","אפריקה","נמל על שפך נהר ז׳בה. היא הייתה בירת מושבה פורטוגזית עד 1974.",null],["מהי בירת סיירה לאונה?","פריטאון","אפריקה",'נוסדה ב-1792 כיישוב לעבדים משוחררים — ומכאן שמה, "עיר החופש". הנמל הטבעי שלה מהגדולים בעולם.',["פריטאון היא בירתה של איזו מדינה?","סיירה לאונה"]],["מהי בירת ליבריה?","מונרוביה","אפריקה","קרויה על שם נשיא ארה״ב ג׳יימס מונרו — לצד וושינגטון, הבירה היחידה שקרויה על שם נשיא אמריקאי.",["מונרוביה היא בירתה של איזו מדינה?","ליבריה"]],["מהי בירת גמביה?","בנג׳ול","אפריקה","שוכנת על אי בשפך נהר גמביה. בעבר נקראה באת׳רסט.",["בנג׳ול היא בירתה של איזו מדינה?","גמביה"]],["מהי בירת מאוריטניה?","נואקשוט","אפריקה","נבנתה כמעט מאפס ב-1958 כבירה העתידית, וצמחה מכפר דייגים לעיר גדולה. חולות נודדים מהמדבר מאיימים עליה.",["נואקשוט היא בירתה של איזו מדינה?","מאוריטניה"]],["מהי בירת כף ורדה?","פראיה","אפריקה",'על האי סנטיאגו, הגדול בכף ורדה. השם בפורטוגזית: "חוף".',["פראיה היא בירתה של איזו מדינה?","כף ורדה"]],["מהי בירת סאו טומה ופרינסיפה?","סאו טומה","אפריקה","העיר הגדולה באי, ונמל של מטעי הקקאו. נקראה על שם תומאס הקדוש.",null],["מהי בירת גינאה המשוונית?","מלאבו","אפריקה","יושבת על האי ביוקו, ולא ביבשה. המדינה בונה בירה חדשה ביבשה — סיודד דה לה פאס.",["מלאבו היא בירתה של איזו מדינה?","גינאה המשוונית"]],["מהי בירת גבון?","ליברוויל","אפריקה",'נוסדה ב-1849 בידי עבדים משוחררים, ומכאן שמה בצרפתית: "עיר החופש".',["ליברוויל היא בירתה של איזו מדינה?","גבון"]],["מהי בירת הרפובליקה המרכז-אפריקאית?","בנגי","אפריקה","על גדת נהר אובנגי, מול הרפובליקה הדמוקרטית של קונגו. השם בא מהמפלים שבנהר.",["בנגי היא בירתה של איזו מדינה?","הרפובליקה המרכז-אפריקאית"]],["מהי בירת מלאווי?","לילונגווה","אפריקה",'הפכה לבירה ב-1975 במקום זומבה. היא מחולקת ל"אזורים" ממוספרים במקום לשכונות.',["לילונגווה היא בירתה של איזו מדינה?","מלאווי"]],["מהי בירת לסוטו?","מסרו","אפריקה","שוכנת על גבול דרום אפריקה, לאורך נהר קלדון. כמעט כל מה שנכנס ללסוטו עובר דרכה.",["מסרו היא בירתה של איזו מדינה?","לסוטו"]],["מהי בירת אסוואטיני?","מבבנה","אפריקה","הבירה המנהלית. הבירה המלכותית והמחוקקת היא לובמבה, בעמק הסמוך.",["מבבנה היא בירתה של איזו מדינה?","אסוואטיני"]],["מהי בירת קומורו?","מורוני","אפריקה","על האי גרנד קומור, למרגלות הר הגעש קרתלה — מהגדולים והפעילים בעולם.",["מורוני היא בירתה של איזו מדינה?","קומורו"]],["מהי בירת מאוריציוס?","פורט לואי","אפריקה","עיר נמל שבנו הצרפתים ב-1735. בשוק המרכזי שלה נפגשים המטבחים של הודו, סין, אפריקה וצרפת.",["פורט לואי היא בירתה של איזו מדינה?","מאוריציוס"]],["מהי בירת סיישל?","ויקטוריה","אפריקה","מהבירות הקטנות בעולם. במרכזה מגדל שעון קטן — העתק של שעון בלונדון.",["ויקטוריה היא בירתה של איזו מדינה?","סיישל"]],["מהי בירת בליז?","בלמופאן","אמריקה","מהבירות הקטנות בעולם. נבנתה בפנים הארץ אחרי שהוריקן הרס ב-1961 את בליז סיטי, הבירה הקודמת שעל החוף.",["בלמופאן היא בירתה של איזו מדינה?","בליז"]],["מהי בירת אל סלוודור?","סן סלוודור","אמריקה",'שוכנת ב"עמק הערסלים" — כונה כך בגלל רעידות האדמה התכופות, שמנדנדות את הקרקע.',null],["מהי בירת הונדורס?","טגוסיגלפה","אמריקה","שדה התעופה שלה נחשב לאחד המסוכנים בעולם — מסלול קצר בין הרים.",["טגוסיגלפה היא בירתה של איזו מדינה?","הונדורס"]],["מהי בירת ניקרגואה?","מנגואה","אמריקה","על שפת אגם מנגואה. רעידת אדמה ב-1972 הרסה את מרכז העיר, והוא מעולם לא נבנה מחדש במלואו.",["מנגואה היא בירתה של איזו מדינה?","ניקרגואה"]],["מהי בירת איי בהאמה?","נסאו","אמריקה",'על האי ניו פרובידנס. בתחילת המאה ה-18 הייתה "רפובליקת הפיראטים" — מקלט לשודדי ים, ובהם "שחור הזקן".',["נסאו היא בירתה של איזו מדינה?","איי בהאמה"]],["מהי בירת ברבדוס?","ברידג׳טאון","אמריקה","העיר ההיסטורית שלה, עם המבצר, היא אתר מורשת עולמית. ג׳ורג׳ וושינגטון ביקר בה בצעירותו — הנסיעה היחידה שלו אל מחוץ לאמריקה.",["ברידג׳טאון היא בירתה של איזו מדינה?","ברבדוס"]],["מהי בירת טרינידד וטובגו?","פורט אוף ספיין","אמריקה","כאן מתקיים הקרנבל הגדול בקריביים — ומכאן יצאו הקליפסו ותופי הפח, הסטיל דראם.",["פורט אוף ספיין היא בירתה של איזו מדינה?","טרינידד וטובגו"]],["מהי בירת גיאנה?","ג׳ורג׳טאון","אמריקה","עיר נמוכה, שחלקים ממנה מתחת לפני הים בגאות ומוגנים בחומת ים. הקתדרלה שלה נחשבת מהמבנים הגבוהים בעולם שנבנו מעץ.",["ג׳ורג׳טאון היא בירתה של איזו מדינה?","גיאנה"]],["מהי בירת סורינאם?","פרמריבו","אמריקה","המרכז ההיסטורי, עם בתי עץ בסגנון הולנדי, הוא אתר מורשת עולמית. בית כנסת ומסגד גדול עומדים בה זה לצד זה.",["פרמריבו היא בירתה של איזו מדינה?","סורינאם"]],["מהי בירת אנטיגואה וברבודה?","סנט ג׳ונס","אמריקה","נמל על האי אנטיגואה. על הגבעה שמעל העיר עומדת קתדרלה בעלת שני מגדלים לבנים.",["סנט ג׳ונס היא בירתה של איזו מדינה?","אנטיגואה וברבודה"]],["מהי בירת דומיניקה?","רוזו","אמריקה","עיר קטנה על החוף המערבי של האי, לא רחוק מיער גשם וממעיינות חמים.",["רוזו היא בירתה של איזו מדינה?","דומיניקה"]],["מהי בירת גרנדה?","סנט ג׳ורג׳ס","אמריקה","נמל בצורת פרסה, שנחשב לאחד היפים בקריביים, מוקף בבתים ציוריים על גבעות.",["סנט ג׳ורג׳ס היא בירתה של איזו מדינה?","גרנדה"]],["מהי בירת סנט קיטס ונוויס?","באסטר","אמריקה",'נוסדה בידי הצרפתים במאה ה-17, ושמה הצרפתי נשאר גם תחת שלטון בריטניה. הכיכר המרכזית שלה מכונה "הקרקס", על שם פיקדילי סירקוס בלונדון.',["באסטר היא בירתה של איזו מדינה?","סנט קיטס ונוויס"]],["מהי בירת סנט לוסיה?","קסטריס","אמריקה","האי שלה החליף ידיים בין בריטניה לצרפת 14 פעמים. העיר נשרפה כמה פעמים ונבנתה מחדש.",["קסטריס היא בירתה של איזו מדינה?","סנט לוסיה"]],["מהי בירת סנט וינסנט והגרנדינים?","קינגסטאון","אמריקה","עיר נמל קטנה, ובה הגן הבוטני העתיק ביבשת אמריקה — נוסד ב-1765.",["קינגסטאון היא בירתה של איזו מדינה?","סנט וינסנט והגרנדינים"]],["מהי בירת סמואה?","אפיה","אוקיאניה",'הסופר רוברט לואיס סטיבנסון, מחבר "אי המטמון", חי בה את שנותיו האחרונות, וקבור על הר מעליה.',["אפיה היא בירתה של איזו מדינה?","סמואה"]],["מהי בירת טונגה?","נוקואלופה","אוקיאניה",'פירוש השם: "מקום האהבה". בה ארמון המלך — בית עץ לבן בסגנון ויקטוריאני.',["נוקואלופה היא בירתה של איזו מדינה?","טונגה"]],["מהי בירת ונואטו?","פורט וילה","אוקיאניה","שוכנת על האי אפאטה. מדי כמה שנים פוגעות בה סופות ציקלון.",["פורט וילה היא בירתה של איזו מדינה?","ונואטו"]],["מהי בירת איי שלמה?","הוניארה","אוקיאניה","על האי גואדלקנל, שבו התחולל אחד הקרבות המרים של מלחמת העולם השנייה (1942–1943).",["הוניארה היא בירתה של איזו מדינה?","איי שלמה"]],["מהי בירת קיריבטי?","טאראווה","אוקיאניה","אטול ארוך וצר, שבדרומו גרה רוב האוכלוסייה. בקרב טאראווה (1943) נהרגו אלפי חיילים בתוך שלושה ימים.",["טאראווה היא בירתה של איזו מדינה?","קיריבטי"]],["מהי בירת טובאלו?","פונפוטי","אוקיאניה","אטול שמסלול שדה התעופה תופס חלק ניכר משטחו — כשאין טיסות, משחקים עליו כדורגל.",["פונפוטי היא בירתה של איזו מדינה?","טובאלו"]],["מהי בירת נאורו?","יארן","אוקיאניה","לנאורו אין בירה רשמית; יארן היא מקום מושב הממשלה. האי כולו קטן כל כך שאפשר להקיף אותו ברכב בפחות מחצי שעה.",["יארן היא בירתה של איזו מדינה?","נאורו"]],["מהי בירת פלאו?","נגרולמוד","אוקיאניה","בירה שנבנתה ביער, הרחק מהעיר הגדולה קורור. בניין הקפיטול שלה מזכיר את הקפיטול בוושינגטון.",["נגרולמוד היא בירתה של איזו מדינה?","פלאו"]],["מהי בירת איי מרשל?","מאג׳ורו","אוקיאניה","אטול בצורת טבעת, שרוב תושבי איי מרשל גרים בו. הנקודה הגבוהה שבו רק כמה מטרים מעל הים.",["מאג׳ורו היא בירתה של איזו מדינה?","איי מרשל"]],["מהי בירת מיקרונזיה?","פאליקיר","אוקיאניה","מהבירות הקטנות בעולם, על האי פונפיי. בקרבתה — נאן מדול, עיר עתיקה שנבנתה על איים מלאכותיים.",["פאליקיר היא בירתה של איזו מדינה?","מיקרונזיה"]],["מהי בירת גרינלנד?","נואוק","טריטוריות",'השם בגרינלנדית: "הכף". כשליש מתושבי גרינלנד גרים בה.',["נואוק היא בירתה של איזו טריטוריה?","גרינלנד"]],["מהי בירת פוארטו ריקו?","סן חואן","טריטוריות","מהערים הוותיקות שייסדו האירופאים ביבשת אמריקה — 1521. המבצר הספרדי אל מורו שומר על הכניסה לנמל.",["סן חואן היא בירתה של איזו טריטוריה?","פוארטו ריקו"]],["מהי בירת איי פארו?","תורסהאוון","טריטוריות",'מהבירות הקטנות בעולם. פירוש השם: "הנמל של תור" — אל הרעם הנורדי.',["תורסהאוון היא בירתה של איזו טריטוריה?","איי פארו"]],["מהי בירת גיברלטר?","גיברלטר","טריטוריות","על הצוק חיים הקופים היחידים שחיים בטבע באירופה. לפי האגדה, כל עוד הם שם — גם הבריטים יישארו.",null],["מהי בירת ברמודה?","המילטון","טריטוריות","עיר קטנה עם בתים בצבעי פסטל וגגות לבנים, שבנויים לאיסוף מי גשמים — אין בברמודה נהרות.",["המילטון היא בירתה של איזו טריטוריה?","ברמודה"]],["מהי בירת האי מאן?","דאגלס","טריטוריות","לאורך הטיילת שלה עדיין נוסעת חשמלית רתומה לסוסים, שפועלת מ-1876.",["דאגלס היא בירתה של איזו טריטוריה?","האי מאן"]],["מהי בירת ג׳רזי?","סנט הלייר","טריטוריות",'על חוף הים, מול "טירת אליזבת" — מבצר שאפשר להגיע אליו ברגל רק בשפל.',["סנט הלייר היא בירתה של איזו טריטוריה?","ג׳רזי"]],["מהי בירת גרנזי?","סנט פיטר פורט","טריטוריות",'עיר נמל על מדרון. בה "בית אוטוויל", שבו חי ויקטור הוגו בגלותו — ושבו השלים את "עלובי החיים".',["סנט פיטר פורט היא בירתה של איזו טריטוריה?","גרנזי"]],["מהי בירת איי אולנד?","מארייהאמן","טריטוריות","נקראה על שם הקיסרית מריה אלכסנדרובנה, אשת הצאר — מזכרת לשלטון הרוסי באיים.",["מארייהאמן היא בירתה של איזו טריטוריה?","איי אולנד"]],["מהי בירת סבאלבארד?","לונגיירביין","טריטוריות","היישוב הצפוני בעולם שגרים בו יותר מאלף איש. לפי הנוהג, חולים קשים מועברים ליבשה — הקרקע הקפואה לא מאפשרת קבורה רגילה.",["לונגיירביין היא בירתה של איזו טריטוריה?","סבאלבארד"]],["מהי בירת פולינזיה הצרפתית?","פאפייטה","טריטוריות","על האי טהיטי. הצייר פול גוגן חי באזור, וצייר בו את הציורים הטהיטיים המפורסמים שלו.",["פאפייטה היא בירתה של איזו טריטוריה?","פולינזיה הצרפתית"]],["מהי בירת קלדוניה החדשה?","נומאה","טריטוריות",'שוכנת על חצי אי, עם השפעה צרפתית חזקה — מכונה "פריז של האוקיינוס השקט".',["נומאה היא בירתה של איזו טריטוריה?","קלדוניה החדשה"]],["מהי בירת איי קיימן?","ג׳ורג׳ טאון","טריטוריות","מרכז בנקאות בינלאומי, שרשומות בו עשרות אלפי חברות. הנמל שלה מקבל ספינות תענוגות רבות.",["ג׳ורג׳ טאון היא בירתה של איזו טריטוריה?","איי קיימן"]],["מהי בירת איי הבתולה הבריטיים?","רוד טאון","טריטוריות",'על האי טורטולה. "רוד" באנגלית ימית הוא מעגן בטוח לספינות — ומכאן השם.',["רוד טאון היא בירתה של איזו טריטוריה?","איי הבתולה הבריטיים"]],["מהי בירת איי הבתולה של ארצות הברית?","שרלוט אמלי","טריטוריות","נקראה על שם מלכת דנמרק, שרלוטה אמליה. בה בית הכנסת העתיק ביותר בשטח ארה״ב שפעיל ברציפות — עם רצפת חול.",["שרלוט אמלי היא בירתה של איזו טריטוריה?","איי הבתולה של ארצות הברית"]],["מהי בירת גואם?","האגאטנה","טריטוריות","מהבירות הקטנות בעולם — כאלף תושבים. הספרדים שלטו בה יותר מ-200 שנה, עד 1898.",["האגאטנה היא בירתה של איזו טריטוריה?","גואם"]],["מהי בירת סמואה האמריקנית?","פאגו פאגו","טריטוריות","יושבת על אחד הנמלים הטבעיים העמוקים באוקיינוס השקט — מכתש של הר געש שהים חדר אליו.",["פאגו פאגו היא בירתה של איזו טריטוריה?","סמואה האמריקנית"]],["מהי בירת איי מריאנה הצפוניים?","סאיפאן","טריטוריות","האי הגדול באיי מריאנה הצפוניים. ב-1944 התחולל בו קרב קשה במלחמת העולם השנייה.",["סאיפאן היא בירתה של איזו טריטוריה?","איי מריאנה הצפוניים"]],["מהי בירת ארובה?","אורנייסטאד","טריטוריות",'פירוש השם: "עיר אורנז׳" — על שם בית המלוכה ההולנדי. בתים צבעוניים בסגנון הולנדי-קריבי.',["אורנייסטאד היא בירתה של איזו טריטוריה?","ארובה"]],["מהי בירת קוראסאו?","וילמסטאד","טריטוריות",'החזיתות הצבעוניות לאורך הנמל הן אתר מורשת עולמית. גשר צף, "המלכה אמה", נפתח כדי לתת לספינות לעבור.',["וילמסטאד היא בירתה של איזו טריטוריה?","קוראסאו"]],["מהי בירת סינט מארטן?","פיליפסבורג","טריטוריות","עיר צרה בין הים לאגם מלח — נמל של ספינות תענוגות וקניות פטורות ממס.",["פיליפסבורג היא בירתה של איזו טריטוריה?","סינט מארטן"]],["מהי בירת איי פוקלנד?","סטנלי","טריטוריות","העיירה היחידה באיים, עם כ-2,500 תושבים — ובתים בגגות פח צבעוניים.",["סטנלי היא בירתה של איזו טריטוריה?","איי פוקלנד"]],["מהי בירת סנט הלנה?","ג׳יימסטאון","טריטוריות",'עיר בעמק צר בין צוקים. "סולם יעקב" שבה מטפס 699 מדרגות אל ראש הגבעה.',["ג׳יימסטאון היא בירתה של איזו טריטוריה?","סנט הלנה"]],["מהי בירת ראוניון?","סן-דני","טריטוריות",'העיר הגדולה בשטחים הצרפתיים שמעבר לים. פירוש השם: "דניס הקדוש".',["סן-דני היא בירתה של איזו טריטוריה?","ראוניון"]],["מהי בירת מרטיניק?","פור-דה-פראנס","טריטוריות","הקיסרית ז׳וזפין, אשת נפוליאון, נולדה במרטיניק. הפסל שלה בכיכר המרכזית עומד בלי ראש — תושבים כרתו אותו ב-1991, בגלל תמיכתה בעבדות.",["פור-דה-פראנס היא בירתה של איזו טריטוריה?","מרטיניק"]],["מהי בירת גוואדלופ?","בס-טר","טריטוריות",'פירוש השם: "אדמה נמוכה" — אבל היא שוכנת למרגלות הר הגעש לה סופרייר, הגבוה באיים הקריביים הקטנים.',["בס-טר היא בירתה של איזו טריטוריה?","גוואדלופ"]],["מהי בירת גיאנה הצרפתית?","קאיין","טריטוריות","בעבר מושבת עונשין: באי השדים, מול החוף, היה כלוא אלפרד דרייפוס.",["קאיין היא בירתה של איזו טריטוריה?","גיאנה הצרפתית"]],["מהי בירת מאיוט?","מאמודזו","טריטוריות","העיר הגדולה במאיוט, על האי הראשי. האיים מוקפים באחת הלגונות הגדולות בעולם.",["מאמודזו היא בירתה של איזו טריטוריה?","מאיוט"]],["מהי בירת איי קוק?","אווארואה","טריטוריות","על האי רארוטונגה. הכביש שמקיף את כל האי ארוך כ-32 ק״מ בלבד.",["אווארואה היא בירתה של איזו טריטוריה?","איי קוק"]],["מהי בירת ניואה?","אלופי","טריטוריות","מהבירות הקטנות בעולם — כמה מאות תושבים. ציקלון ב-2004 הרס חלקים גדולים ממנה.",["אלופי היא בירתה של איזו טריטוריה?","ניואה"]],["מהי בירת איי טרקס וקאיקוס?","קוקבורן טאון","טריטוריות","על האי גרנד טורק. לפי אחת הגרסאות, כאן — ולא באיי בהאמה — נחת קולומבוס לראשונה.",["קוקבורן טאון היא בירתה של איזו טריטוריה?","איי טרקס וקאיקוס"]],["מהי בירת אנגווילה?","דה ואלי","טריטוריות",'פשוט "העמק" — עיירה קטנה במרכז האי, עם כמה אלפי תושבים.',["דה ואלי היא בירתה של איזו טריטוריה?","אנגווילה"]],["מהי בירת מונטסראט?","בריידס","טריטוריות","בירה זמנית, מאז שהר הגעש סופרייר הילס קבר את הבירה הקודמת, פלימות׳, בשנות ה-90.",["בריידס היא בירתה של איזו טריטוריה?","מונטסראט"]],["מהי בירת סהרה המערבית?","אל-עיון","טריטוריות",'העיר הגדולה בשטח, בשליטת מרוקו. פירוש השם בערבית: "המעיינות".',["אל-עיון היא בירתה של איזו טריטוריה?","סהרה המערבית"]],["מהי בירת סן פייר ומיקלון?","סן פייר","טריטוריות","עיירה צרפתית מול חופי קנדה, עם אירו, באגטים ושוטרים צרפתים. בתקופת היובש בארה״ב — מרכז להברחת אלכוהול.",null],["מהי בירת ווליס ופוטונה?","מאטה-אוטו","טריטוריות","על האי ווליס, עם קתדרלה גדולה מאבן וולקנית; כמעט כל התושבים קתולים.",["מאטה-אוטו היא בירתה של איזו טריטוריה?","ווליס ופוטונה"]]]},a={id:"continents",name:"מדינות ויבשות",description:"כל מדינות העולם והטריטוריות — באיזו יבשת כל אחת נמצאת. משלים את חבילת ערי הבירה, ומסודר מהקל לקשה.",cards:[["באיזו יבשת נמצאת צרפת?","אירופה","מפורסמות","המדינה המתוירת ביותר בעולם. בזכות שטחיה מעבר לים — מהקריביים ועד האוקיינוס השקט — יש לה יותר אזורי זמן מלכל מדינה אחרת.",null],["באיזו יבשת נמצאת בריטניה?","אירופה","מפורסמות","הממלכה המאוחדת: אנגליה, סקוטלנד וויילס שעל האי בריטניה הגדולה, ועוד צפון אירלנד.",null],["באיזו יבשת נמצאת איטליה?","אירופה","מפורסמות","בצורת מגף שבועט בכדור — סיציליה. בתוך שטחה יושבות שתי מדינות עצמאיות: הוותיקן וסן מרינו.",null],["באיזו יבשת נמצאת ספרד?","אירופה","מפורסמות","חולקת עם פורטוגל את חצי האי האיברי. האיים הקנריים שלה נמצאים בכלל מול חופי אפריקה.",null],["באיזו יבשת נמצאת גרמניה?","אירופה","מפורסמות","המדינה המאוכלסת ביותר באיחוד האירופי. היא גובלת בתשע מדינות — יותר מכל מדינה באירופה מלבד רוסיה.",null],["באיזו יבשת נמצאת ארצות הברית?","צפון אמריקה","מפורסמות","50 מדינות, ושתיים מהן לא נוגעות בשאר: אלסקה, שנקנתה מרוסיה ב-1867, והוואי שבלב האוקיינוס השקט.",null],["באיזו יבשת נמצאת רוסיה?","אירופה ואסיה — משתרעת על שתיהן","מפורסמות","הרי אורל הם הגבול בין החלק האירופי לאסייתי. רוב התושבים גרים באירופה, אבל רוב השטח — סיביר — נמצא באסיה.",null],["באיזו יבשת נמצאת סין?","אסיה","מפורסמות","למרות הרוחב העצום שלה, בכל סין יש אזור זמן אחד בלבד — שעון בייג׳ינג.",null],["באיזו יבשת נמצאת יפן?","אסיה","מפורסמות",'ארבעה איים עיקריים ואלפי איים קטנים, על "טבעת האש" של האוקיינוס השקט — ולכן רעידות אדמה הן חלק משגרת החיים בה.',null],["באיזו יבשת נמצאת מצרים?","אפריקה","מפורסמות","רובה באפריקה, אבל חצי האי סיני נמצא באסיה — כך שהיא מדינה בין-יבשתית. רוב תושביה גרים ברצועה צרה לאורך הנילוס.",null],["באיזו יבשת נמצאת ישראל?","אסיה","מפורסמות","ישראל נמצאת בדרום-מערב אסיה, אבל מתחרה במסגרות אירופיות — בכדורגל ובאירוויזיון — מסיבות פוליטיות, לא גאוגרפיות.",null],["באיזו יבשת נמצאת יוון?","אירופה","מפורסמות","יש בה יותר מ-6,000 איים, שרק כ-200 מהם מיושבים.",null],["באיזו יבשת נמצאת טורקיה?","אירופה ואסיה — משתרעת על שתיהן","מפורסמות","מיצר הבוספורוס חוצה את איסטנבול: חלק מהעיר באירופה וחלק באסיה. אבל רוב שטחה של טורקיה — אנטוליה — נמצא באסיה.",null],["באיזו יבשת נמצאת הודו?","אסיה","מפורסמות","תת-היבשת ההודית יושבת על לוח טקטוני משלה, שמתנגש באסיה — ומההתנגשות הזאת נולדו הרי ההימלאיה.",null],["באיזו יבשת נמצאת ברזיל?","דרום אמריקה","מפורסמות","כמעט חצי מיבשת דרום אמריקה. היא גובלת בכל מדינות היבשת מלבד שתיים: צ׳ילה ואקוודור.",null],["באיזו יבשת נמצאת ארגנטינה?","דרום אמריקה","מפורסמות","נמתחת מהאזור הטרופי ועד טיירה דל פואגו בקצה הדרומי. ההר הגבוה ביבשת, אקונקגואה, נמצא בה.",null],["באיזו יבשת נמצאת קנדה?","צפון אמריקה","מפורסמות","המדינה השנייה בגודלה בעולם, ובעלת קו החוף הארוך ביותר. רוב התושבים גרים קרוב לגבול הדרומי, עם ארה״ב.",null],["באיזו יבשת נמצאת אוסטרליה?","אוקיאניה","מפורסמות","מדינה שהיא גם יבשת שלמה. כשמצרפים אליה את ניו זילנד ואת איי האוקיינוס השקט, היבשת נקראת אוקיאניה.",null],["באיזו יבשת נמצאת מקסיקו?","צפון אמריקה","מפורסמות","גאוגרפית, מרכז אמריקה והקריביים הם חלק מצפון אמריקה — ומקסיקו היא החוליה שמחברת אותם לארה״ב ולקנדה.",null],["באיזו יבשת נמצאת הולנד?","אירופה","מפורסמות",'כרבע משטחה נמצא מתחת לפני הים, מוגן בסכרים ובמשאבות. "נדרלנד" פירושו "ארצות נמוכות".',null],["באיזו יבשת נמצאת בלגיה?","אירופה","מפורסמות","שלוש שפות רשמיות — הולנדית, צרפתית וגרמנית. מבחינה פוליטית היא כמעט שתי מדינות: פלנדריה בצפון וולוניה בדרום.",null],["באיזו יבשת נמצאת פורטוגל?","אירופה","מפורסמות","המדינה המערבית ביותר ביבשת אירופה. ממנה יצאו מגלי הארצות הגדולים, כמו ואסקו דה גאמה.",null],["באיזו יבשת נמצאת אוסטריה?","אירופה","מפורסמות","מדינה בלי ים, שכשני שלישים ממנה הם הרי האלפים. פעם הייתה לב האימפריה ההבסבורגית.",null],["באיזו יבשת נמצאת שווייץ?","אירופה","מפורסמות","ארבע שפות רשמיות — גרמנית, צרפתית, איטלקית ורומאנש. ניטרלית מאז 1815, והצטרפה לאו״ם רק ב-2002.",null],["באיזו יבשת נמצאת שוודיה?","אירופה","מפורסמות","המדינה הגדולה בסקנדינביה. בצפונה, מעבר לחוג הקוטב, השמש לא שוקעת באמצע הקיץ.",null],["באיזו יבשת נמצאת נורווגיה?","אירופה","מפורסמות","קו החוף שלה, עם כל הפיורדים, ארוך פי כמה מאורך המדינה. גם סבאלבארד, בדרך לקוטב הצפוני, שייך לה.",null],["באיזו יבשת נמצאת דנמרק?","אירופה","מפורסמות","חצי האי יוטלנד ועוד מאות איים. לממלכה שייכות גם גרינלנד ואיי פארו — כך שרוב שטחה נמצא בכלל בצפון אמריקה.",null],["באיזו יבשת נמצאת פולין?","אירופה","מפורסמות","אחרי מלחמת העולם השנייה גבולותיה הוזזו מערבה בכמאתיים קילומטרים. בשטחה הקימו הנאצים את רוב מחנות ההשמדה.",null],["באיזו יבשת נמצאת צ׳כיה?","אירופה","מפורסמות",'עד 1993 הייתה חלק מצ׳כוסלובקיה, שהתפצלה בשלום — "הגירושים של הקטיפה".',null],["באיזו יבשת נמצאת הונגריה?","אירופה","מפורסמות","מדינה בלי ים, שהדנובה חוצה אותה. ההונגרית לא קרובה לשום שפה שכנה — קרובותיה הרחוקות הן הפינית והאסטונית.",null],["באיזו יבשת נמצאת אירלנד?","אירופה","מפורסמות",'"האי הירוק", בזכות הגשמים. האי מחולק: רובו מדינה עצמאית, והצפון חלק מהממלכה המאוחדת.',null],["באיזו יבשת נמצאת פינלנד?","אירופה","מפורסמות",'"ארץ אלף האגמים" — למעשה יש בה כ-188 אלף אגמים. חלק ניכר ממנה נמצא מעבר לחוג הקוטב.',null],["באיזו יבשת נמצאת אוקראינה?","אירופה","מפורסמות",'המדינה הגדולה ביותר שכולה בתוך אירופה. אדמת הצ׳רנוזם השחורה והפורייה שלה הפכה אותה ל"אסם התבואה של אירופה".',null],["באיזו יבשת נמצאת איראן?","אסיה","מפורסמות",'רמה גבוהה בין הים הכספי למפרץ הפרסי. עד 1935 נקראה בעולם "פרס".',null],["באיזו יבשת נמצאת עיראק?","אסיה","מפורסמות",'בין הפרת לחידקל — מסופוטמיה, "ארץ שני הנהרות". כאן קמו שומר ובבל, מהתרבויות הראשונות בעולם.',null],["באיזו יבשת נמצאת ערב הסעודית?","אסיה","מפורסמות","תופסת את רוב חצי האי ערב, ואין בה אפילו נהר קבוע אחד. בשטחה מכה ומדינה, הערים הקדושות לאסלאם.",null],["באיזו יבשת נמצאת ירדן?","אסיה","מפורסמות","כמעט בלי ים: קו חוף של כ-26 ק״מ, במפרץ עקבה. פטרה, העיר החצובה בסלע, נמצאת בדרומה.",null],["באיזו יבשת נמצאת לבנון?","אסיה","מפורסמות","מהמדינות הקטנות במזרח התיכון. שמה מהשורש לב״ן — על שם השלג הלבן שעל הרי הלבנון.",null],["באיזו יבשת נמצאת סוריה?","אסיה","מפורסמות","השבר הסורי-אפריקאי, שעובר גם בישראל — בערבה, בים המלח ובבקעת הירדן — נקרא על שמה. רמת הגולן בשליטת ישראל מאז 1967.",null],["באיזו יבשת נמצאת דרום אפריקה?","אפריקה","מפורסמות","שלוש ערי בירה: פרטוריה (ממשלה), קייפטאון (פרלמנט) ובלומפונטיין (בתי משפט). בתוך שטחה שוכנת מדינה שלמה — לסוטו.",null],["באיזו יבשת נמצאת תאילנד?","אסיה","מוכרות",'המדינה היחידה בדרום-מזרח אסיה שלא הייתה מעולם מושבה של מעצמה אירופית. "תאי" פירושו "חופשי".',null],["באיזו יבשת נמצאת וייטנאם?","אסיה","מוכרות","ארוכה וצרה, בצורת S, לאורך ים סין הדרומי. בנקודה הצרה ביותר שלה, רוחבה כ-50 ק״מ בלבד.",null],["באיזו יבשת נמצאת דרום קוריאה?","אסיה","מוכרות",'החצי הדרומי של חצי האי הקוריאני. הגבול עם הצפון — "האזור המפורז" — הוא מהגבולות המבוצרים בעולם.',null],["באיזו יבשת נמצאת צפון קוריאה?","אסיה","מוכרות","המדינה הסגורה בעולם. מלחמת קוריאה (1950–1953) הסתיימה בשביתת נשק, ולא בהסכם שלום.",null],["באיזו יבשת נמצאת אינדונזיה?","אסיה","מוכרות","יותר מ-17 אלף איים, והמדינה המוסלמית המאוכלסת בעולם. החלק שלה באי גינאה החדשה כבר נחשב לאוקיאניה.",null],["באיזו יבשת נמצאת הפיליפינים?","אסיה","מוכרות","יותר מ-7,000 איים. נקראה על שם מלך ספרד פיליפ השני, שבימיו כבשה אותה ספרד.",null],["באיזו יבשת נמצאת מלזיה?","אסיה","מוכרות","בנויה משני חלקים שהים מפריד ביניהם: חצי האי המלאי, וצפון האי בורנאו.",null],["באיזו יבשת נמצאת סינגפור?","אסיה","מוכרות",'מדינה-עיר על אי, בקצה חצי האי המלאי. השם מסנסקריט: "עיר האריה".',null],["באיזו יבשת נמצאת פקיסטן?","אסיה","מוכרות","נוסדה ב-1947, כשהודו הבריטית חולקה. בשטחה הפסגה השנייה בגובהה בעולם, K2.",null],["באיזו יבשת נמצאת אפגניסטן?","אסיה","מוכרות",'מדינה בלי ים בלב אסיה, שהרי ההינדו כוש חוצים אותה. כונתה "בית הקברות של האימפריות": בריטניה, ברית המועצות וארה״ב נכשלו בה.',null],["באיזו יבשת נמצאת מרוקו?","אפריקה","מוכרות","רק כ-14 ק״מ של מיצר גיברלטר מפרידים בינה לבין ספרד. הרי האטלס חוצים אותה.",null],["באיזו יבשת נמצאת תוניסיה?","אפריקה","מוכרות",'המדינה הצפונית ביותר ביבשת אפריקה. המהפכה בה, בסוף 2010, הציתה את "האביב הערבי".',null],["באיזו יבשת נמצאת אלג׳יריה?","אפריקה","מוכרות","המדינה הגדולה באפריקה בשטח, ויותר מ-80% ממנה הם מדבר סהרה.",null],["באיזו יבשת נמצאת לוב?","אפריקה","מוכרות","כ-90% משטחה מדבר. רוב התושבים גרים ברצועה צרה לאורך חוף הים התיכון.",null],["באיזו יבשת נמצאת ניגריה?","אפריקה","מוכרות","המדינה המאוכלסת ביותר באפריקה — יותר מ-200 מיליון תושבים, ומאות שפות.",null],["באיזו יבשת נמצאת קניה?","אפריקה","מוכרות","קו המשווה חוצה אותה. הסוואנות שלה מפורסמות בנדידה השנתית של עדרי הגנו והזברות.",null],["באיזו יבשת נמצאת אתיופיה?","אפריקה","מוכרות","מהמדינות העתיקות בעולם, ומהיחידות באפריקה שלא היו מעולם מושבה (מלבד כיבוש איטלקי קצר). רוב שטחה רמה גבוהה.",null],["באיזו יבשת נמצאת גאנה?","אפריקה","מוכרות",'הראשונה באפריקה שמדרום לסהרה שקיבלה עצמאות, ב-1957. בתקופה הבריטית נקראה "חוף הזהב".',null],["באיזו יבשת נמצאת קובה?","צפון אמריקה","מוכרות","האי הגדול בקריביים, כ-150 ק״מ מפלורידה. גאוגרפית — חלק מצפון אמריקה.",null],["באיזו יבשת נמצאת צ׳ילה?","דרום אמריקה","מוכרות","המדינה הארוכה והצרה בעולם: כ-4,300 ק״מ אורך, ורוחב ממוצע של פחות מ-200 ק״מ. בצפונה מדבר אטקמה, היבש בעולם.",null],["באיזו יבשת נמצאת פרו?","דרום אמריקה","מוכרות","כאן היה לב אימפריית האינקה, ובהרים — מאצ׳ו פיצ׳ו. אגם טיטיקקה שעל הגבול עם בוליביה הוא מהאגמים הגבוהים בעולם שאפשר לשוט בהם.",null],["באיזו יבשת נמצאת קולומביה?","דרום אמריקה","מוכרות","המדינה היחידה בדרום אמריקה עם חופים גם לאוקיינוס השקט וגם לים הקריבי. נקראה על שם קולומבוס.",null],["באיזו יבשת נמצאת ונצואלה?","דרום אמריקה","מוכרות",'בשטחה מפל אנחל — המפל הגבוה בעולם, כמעט קילומטר. השם פירושו "ונציה הקטנה".',null],["באיזו יבשת נמצאת ניו זילנד?","אוקיאניה","מוכרות","שני איים עיקריים, כ-2,000 ק״מ מאוסטרליה. מהמקומות האחרונים בעולם שבני אדם התיישבו בהם — לפני פחות מאלף שנה.",null],["באיזו יבשת נמצאת רומניה?","אירופה","מוכרות","הרי הקרפטים עוברים בה, ובהם טרנסילבניה — הבית של אגדת דרקולה. הדנובה נשפכת בה לים השחור.",null],["באיזו יבשת נמצאת בולגריה?","אירופה","מוכרות",'על חוף הים השחור. בבולגריה תנועות הראש הפוכות: הנהון פירושו "לא", וניעור הראש — "כן".',null],["באיזו יבשת נמצאת קרואטיה?","אירופה","מוכרות","חוף אדריאטי ארוך עם יותר מאלף איים. המדינה בצורת סהר.",null],["באיזו יבשת נמצאת סרביה?","אירופה","מוכרות","מדינה בלי ים, בלב הבלקן. הדנובה והסאווה נפגשות בבירה, בלגרד.",null],["באיזו יבשת נמצאת איסלנד?","אירופה","מוכרות","יושבת בדיוק על הרכס שבו הלוח האמריקאי והלוח האירואסייתי מתרחקים זה מזה — ולכן היא מלאה בהרי געש ובגייזרים.",null],["באיזו יבשת נמצאת בלארוס?","אירופה","מוכרות","מדינה בלי ים, שטוחה ומיוערת, בין רוסיה לפולין. כמעט שליש משטחה מכוסה ביערות.",null],["באיזו יבשת נמצאת קזחסטן?","אסיה","מוכרות","המדינה הגדולה בעולם שאין לה ים פתוח. חלק קטן ממנה, מערבית לנהר אורל, נחשב לאירופה.",null],["באיזו יבשת נמצאת איחוד האמירויות?","אסיה","מוכרות","שבע אמירויות, ובהן אבו דאבי ודובאי. בדובאי עומד הבניין הגבוה בעולם — בורג׳ ח׳ליפה.",null],["באיזו יבשת נמצאת קטר?","אסיה","מוכרות","חצי אי קטן שבולט לתוך המפרץ הפרסי. אירחה את מונדיאל 2022 — הראשון במזרח התיכון.",null],["באיזו יבשת נמצאת כווית?","אסיה","מוכרות","קטנה, עם מאגרי נפט עצומים. ב-1990 פלשה אליה עיראק — ומכאן מלחמת המפרץ.",null],["באיזו יבשת נמצאת תימן?","אסיה","מוכרות",'בקצה הדרום-מערבי של חצי האי ערב, מול מיצר באב אל-מנדב. רוב יהודי תימן עלו ממנה ארצה ב"מרבד הקסמים".',null],["באיזו יבשת נמצאת עומאן?","אסיה","מוכרות","בקצה הדרום-מזרחי של חצי האי ערב. חלק קטן ממנה, חצי האי מוסנדם, מנותק מהשאר ושולט על מיצר הורמוז.",null],["באיזו יבשת נמצאת בחריין?","אסיה","מוכרות","מדינת איים קטנה במפרץ הפרסי, שמחוברת לערב הסעודית בגשר ארוך. חתמה על הסכמי אברהם עם ישראל ב-2020.",null],["באיזו יבשת נמצאת קפריסין?","אירופה","מוכרות","גאוגרפית היא יושבת באסיה, מול חופי סוריה וטורקיה — אבל פוליטית ותרבותית היא אירופית, וחברה באיחוד האירופי.",null],["באיזו יבשת נמצאת מלטה?","אירופה","מוכרות","מהמדינות הקטנות באירופה, בין סיציליה ללוב. המלטית היא השפה השמית היחידה שנכתבת באותיות לטיניות.",null],["באיזו יבשת נמצאת לוקסמבורג?","אירופה","מוכרות","דוכסות גדולה — המדינה היחידה בעולם שנושאת את התואר הזה. מהמדינות העשירות בעולם לנפש.",null],["באיזו יבשת נמצאת סלובקיה?","אירופה","מוכרות","החצי המזרחי של צ׳כוסלובקיה לשעבר. הרי הטטרה, החלק הגבוה של הקרפטים, נמצאים בצפונה.",null],["באיזו יבשת נמצאת סלובניה?","אירופה","מוכרות","מדינה קטנה בין האלפים לים האדריאטי, עם רצועת חוף של פחות מ-50 ק״מ. יותר ממחצית שטחה מכוסה ביערות.",null],["באיזו יבשת נמצאת אסטוניה?","אירופה","מוכרות","הצפונית מבין שלוש המדינות הבלטיות. מהמדינות הדיגיטליות בעולם: כמעט כל שירות ממשלתי זמין בה ברשת.",null],["באיזו יבשת נמצאת לטביה?","אירופה","מוכרות","האמצעית מבין שלוש המדינות הבלטיות, עם חוף ארוך של דיונות ויערות אורנים.",null],["באיזו יבשת נמצאת ליטא?","אירופה","מוכרות","הגדולה והדרומית מבין המדינות הבלטיות. במאה ה-15, הדוכסות הגדולה של ליטא הייתה מהמדינות הגדולות באירופה.",null],["באיזו יבשת נמצאת בנגלדש?","אסיה","מוכרות","רובה דלתא ענקית של הגנגס והברהמפוטרה — מישורית, פורייה, ומוצפת לעיתים קרובות. מהמדינות הצפופות בעולם.",null],["באיזו יבשת נמצאת נפאל?","אסיה","מוכרות","שמונה מעשר הפסגות הגבוהות בעולם נמצאות בה או על גבולה, ובהן האוורסט. הדגל שלה הוא היחיד בעולם שאינו מלבני.",null],["באיזו יבשת נמצאת מיאנמר?","אסיה","מוכרות","לשעבר בורמה. מדינה של אלפי מקדשים בודהיסטיים — הבולט שבהם מישור באגאן.",null],["באיזו יבשת נמצאת קמבודיה?","אסיה","מוכרות","אנגקור ואט, מתחם המקדשים הגדול בעולם, מופיע על הדגל שלה.",null],["באיזו יבשת נמצאת סרי לנקה?","אסיה","מוכרות","אי בצורת טיפה מדרום להודו. ב-1960 נבחרה בו ראש הממשלה הראשונה בעולם, כשעוד נקרא ציילון.",null],["באיזו יבשת נמצאת בוסניה והרצגובינה?","אירופה","בינוניות","כמעט בלי ים: רצועת חוף של כ-20 ק״מ בלבד. במלחמה של שנות ה-90 עמדה הבירה, סרייבו, במצור ארוך.",null],["באיזו יבשת נמצאת אלבניה?","אירופה","בינוניות","על חוף הים האדריאטי והיוני, מול איטליה. עשרות שנים הייתה מהמדינות הסגורות בעולם, תחת משטר קומוניסטי.",null],["באיזו יבשת נמצאת צפון מקדוניה?","אירופה","בינוניות",'שינתה את שמה ב-2019, בהסכם עם יוון — שטענה ש"מקדוניה" הוא שם של חבל יווני.',null],["באיזו יבשת נמצאת מונטנגרו?","אירופה","בינוניות",'פירוש השם: "ההר השחור". עצמאית רק מאז 2006, אחרי משאל עם על פירוק האיחוד עם סרביה.',null],["באיזו יבשת נמצאת מולדובה?","אירופה","בינוניות","מדינה בלי ים בין רומניה לאוקראינה, ומהעניות באירופה. רצועת טרנסניסטריה שבה מנותקת בפועל מהשלטון.",null],["באיזו יבשת נמצאת גאורגיה?","אסיה","בינוניות","יושבת על הגבול שבין אירופה לאסיה — הרי הקווקז. מייצרים בה יין כבר כ-8,000 שנה.",null],["באיזו יבשת נמצאת ארמניה?","אסיה","בינוניות","המדינה הראשונה שאימצה את הנצרות כדת רשמית — בשנת 301.",null],["באיזו יבשת נמצאת אזרבייג׳ן?","אסיה","בינוניות","על חוף הים הכספי, ולכן עשירה בנפט. חלק קטן ממנה, צפונית לרכס הקווקז, נחשב לפעמים לאירופה.",null],["באיזו יבשת נמצאת אוזבקיסטן?","אסיה","בינוניות","אחת משתי המדינות בעולם שמוקפות רק במדינות בלי ים. בשטחה הערים העתיקות של דרך המשי — סמרקנד ובוכרה.",null],["באיזו יבשת נמצאת טורקמניסטן?","אסיה","בינוניות",'רובה מדבר קרקום. "שער הגיהינום" שבה — מכתש גז שבוער ברציפות מאז 1971.',null],["באיזו יבשת נמצאת קירגיזסטן?","אסיה","בינוניות","כ-90% ממנה הרים — רכס טיין שאן. אגם איסיק-כול שבה לא קופא בחורף, למרות הגובה.",null],["באיזו יבשת נמצאת טג׳יקיסטן?","אסיה","בינוניות",'יותר מ-90% משטחה הרים, רובם ברכס הפמיר — "גג העולם".',null],["באיזו יבשת נמצאת מונגוליה?","אסיה","בינוניות","המדינה הדלילה בעולם, ובדרומה מדבר גובי. כאן קמה במאה ה-13 האימפריה של ג׳ינגיס חאן.",null],["באיזו יבשת נמצאת לאוס?","אסיה","בינוניות","המדינה היחידה בדרום-מזרח אסיה שאין לה ים. נהר המקונג זורם לאורכה.",null],["באיזו יבשת נמצאת ברוניי?","אסיה","בינוניות","מדינה זעירה בצפון האי בורנאו, מוקפת בחלקה במלזיה. השולטן שלה מהעשירים בעולם — בזכות הנפט.",null],["באיזו יבשת נמצאת האיים המלדיביים?","אסיה","בינוניות","המדינה הנמוכה בעולם: רוב האדמה בה כמטר אחד מעל פני הים, ולכן עליית מפלס הים היא איום קיומי עליה.",null],["באיזו יבשת נמצאת בהוטן?","אסיה","בינוניות",'ממלכה קטנה בהימלאיה, שמודדת "אושר לאומי גולמי" ולא רק תוצר. מהמדינות היחידות שקולטות יותר פחמן משהן פולטות.',null],["באיזו יבשת נמצאת טימור המזרחית?","אסיה","בינוניות","החצי המזרחי של האי טימור, מצפון לאוסטרליה. קיבלה עצמאות ב-2002, אחרי עשרות שנים של שלטון אינדונזי.",null],["באיזו יבשת נמצאת סודן?","אפריקה","בינוניות","יש בה יותר פירמידות מאשר במצרים — של ממלכת כוש הנובית הקדומה.",null],["באיזו יבשת נמצאת דרום סודן?","אפריקה","בינוניות","המדינה הצעירה בעולם — נפרדה מסודן ב-2011. בשטחה ביצת סוד, מהביצות הגדולות בעולם.",null],["באיזו יבשת נמצאת סומליה?","אפריקה","בינוניות",'בעלת קו החוף הארוך ביותר ביבשת אפריקה, ב"קרן אפריקה".',null],["באיזו יבשת נמצאת אריתריאה?","אפריקה","בינוניות","על חוף ים סוף. היא נפרדה מאתיופיה ב-1993 — ובכך הפכה את אתיופיה למדינה בלי ים.",null],["באיזו יבשת נמצאת ג׳יבוטי?","אפריקה","בינוניות","מדינה קטנה במיקום אסטרטגי, ליד מיצר באב אל-מנדב. אגם אסל שבה הוא הנקודה הנמוכה באפריקה.",null],["באיזו יבשת נמצאת טנזניה?","אפריקה","בינוניות","בשטחה הקילימנג׳רו, ההר הגבוה באפריקה, וגם האי זנזיבר. השם מחבר את טנגניקה וזנזיבר, שהתאחדו ב-1964.",null],["באיזו יבשת נמצאת אוגנדה?","אפריקה","בינוניות","שוכנת על אגם ויקטוריה, וממנו יוצא הנילוס הלבן. ב-1976 נחתו בה כוחות צה״ל, במבצע אנטבה.",null],["באיזו יבשת נמצאת רואנדה?","אפריקה","בינוניות",'"ארץ אלף הגבעות". ב-1994 התחולל בה רצח עם, שבו נרצחו כ-800 אלף איש בתוך כמאה יום.',null],["באיזו יבשת נמצאת בורונדי?","אפריקה","בינוניות","מדינה קטנה לחוף אגם טנגניקה — מהאגמים העמוקים בעולם. מהמדינות הצפופות והעניות באפריקה.",null],["באיזו יבשת נמצאת הרפובליקה הדמוקרטית של קונגו?","אפריקה","בינוניות","המדינה השנייה בגודלה באפריקה. נהר קונגו, העמוק בעולם, זורם בה — וממנו שמה.",null],["באיזו יבשת נמצאת רפובליקת קונגו?","אפריקה","בינוניות",'הקטנה מבין שתי ה"קונגו". הבירות של שתיהן, ברזוויל וקינשאסה, עומדות זו מול זו משני צידי הנהר.',null],["באיזו יבשת נמצאת אנגולה?","אפריקה","בינוניות","מושבה פורטוגזית לשעבר על חוף האוקיינוס האטלנטי. לחבל קבינדה שלה אין רציפות יבשתית עם שאר המדינה.",null],["באיזו יבשת נמצאת זמביה?","אפריקה","בינוניות",'מפלי ויקטוריה, על הגבול עם זימבבואה, הם מהמפלים הגדולים בעולם — המקומיים קוראים להם "העשן הרועם".',null],["באיזו יבשת נמצאת זימבבואה?","אפריקה","בינוניות",'נקראה על שם "זימבבואה הגדולה" — עיר אבן מימי הביניים, שחורבותיה עומדות בה עד היום. בעבר נקראה רודזיה.',null],["באיזו יבשת נמצאת מוזמביק?","אפריקה","בינוניות","רצועת חוף ארוכה על האוקיינוס ההודי, מול מדגסקר. על הדגל שלה מופיע רובה קלצ׳ניקוב.",null],["באיזו יבשת נמצאת מדגסקר?","אפריקה","בינוניות","האי הרביעי בגודלו בעולם. הוא נפרד מהיבשות לפני עשרות מיליוני שנים — ולכן רוב הצמחים ובעלי החיים בו, כמו הלמורים, לא קיימים בשום מקום אחר.",null],["באיזו יבשת נמצאת נמיביה?","אפריקה","בינוניות","מדבר נמיב שבה נחשב למדבר העתיק בעולם, ובו דיונות אדומות מהגבוהות בעולם.",null],["באיזו יבשת נמצאת בוצוואנה?","אפריקה","בינוניות","מדינה בלי ים, שרובה מדבר קלהרי. הדלתא של נהר אוקוונגו שבה נשפכת לתוך המדבר — ולא לים.",null],["באיזו יבשת נמצאת סנגל?","אפריקה","בינוניות","גמביה כמעט חוצה אותה לשניים. השפה הרשמית צרפתית, אבל הנפוצה ביותר היא וולוף.",null],["באיזו יבשת נמצאת מאלי?","אפריקה","בינוניות",'בשטחה טימבוקטו — במאות ה-14 עד ה-16 מרכז של מסחר ולימוד, ששמה הפך לכינוי ל"סוף העולם". רובה מדבר.',null],["באיזו יבשת נמצאת חוף השנהב?","אפריקה","בינוניות","נקראה על שם סחר השנהב בתקופה הקולוניאלית. היא יצרנית הקקאו הגדולה בעולם.",null],["באיזו יבשת נמצאת קמרון?","אפריקה","בינוניות",'מכונה "אפריקה בזעיר אנפין": בתחומה מדבר, סוואנה, יער גשם, הרי געש וחופים.',null],["באיזו יבשת נמצאת אורוגוואי?","דרום אמריקה","בינוניות","השנייה בקטנות בדרום אמריקה. היא אירחה וזכתה במונדיאל הראשון, ב-1930.",null],["באיזו יבשת נמצאת פרגוואי?","דרום אמריקה","בינוניות","מדינה בלי ים בלב היבשת, עם שתי שפות רשמיות: ספרדית וגוארני — שפה של העם הילידי.",null],["באיזו יבשת נמצאת בוליביה?","דרום אמריקה","בינוניות","מדינה בלי ים מאז שאיבדה את רצועת החוף שלה לצ׳ילה במלחמה בשלהי המאה ה-19 — ועדיין מחזיקה צי ימי, באגם טיטיקקה.",null],["באיזו יבשת נמצאת אקוודור?","דרום אמריקה","בינוניות",'בספרדית שמה פשוט "קו המשווה" — שחוצה אותה. גם איי גלפגוס שייכים לה.',null],["באיזו יבשת נמצאת גואטמלה?","צפון אמריקה","בינוניות","לב תרבות המאיה — עיר המקדשים טיקאל נמצאת בה. בדרומה שרשרת של הרי געש.",null],["באיזו יבשת נמצאת קוסטה ריקה?","צפון אמריקה","בינוניות","ביטלה את הצבא שלה ב-1948. כרבע משטחה שמורות טבע.",null],["באיזו יבשת נמצאת פנמה?","צפון אמריקה","בינוניות","הגשר היבשתי בין צפון לדרום אמריקה. תעלת פנמה חוצה אותה ומחברת בין שני האוקיינוסים.",null],["באיזו יבשת נמצאת ג׳מייקה?","צפון אמריקה","בינוניות","אי בקריביים, דרומית לקובה. הולדתה של מוזיקת הרגאיי — ושל הספרינטר יוסיין בולט.",null],["באיזו יבשת נמצאת האיטי?","צפון אמריקה","בינוניות","החצי המערבי של האי היספניולה. הרפובליקה השחורה הראשונה בעולם — קמה במרד עבדים, ב-1804.",null],["באיזו יבשת נמצאת הרפובליקה הדומיניקנית?","צפון אמריקה","בינוניות","החצי המזרחי של היספניולה. כאן הוקם היישוב האירופי הקבוע הראשון ביבשת אמריקה.",null],["באיזו יבשת נמצאת פיג׳י?","אוקיאניה","בינוניות","יותר מ-300 איים בדרום האוקיינוס השקט. קו האורך ה-180 עובר דרכה.",null],["באיזו יבשת נמצאת פפואה גינאה החדשה?","אוקיאניה","בינוניות","המחצית המזרחית של האי גינאה החדשה. מדברים בה יותר מ-800 שפות — יותר מבכל מדינה אחרת.",null],["באיזו יבשת נמצאת אנדורה?","אירופה","בינוניות",'נסיכות קטנה בהרי הפירנאים, בין צרפת לספרד. יש לה שני "נסיכים משותפים": נשיא צרפת והבישוף של אורחל הספרדית.',null],["באיזו יבשת נמצאת מונקו?","אירופה","מאתגרות","המדינה השנייה בקטנותה בעולם. משפחת גרימלדי שולטת בה כבר יותר מ-700 שנה.",null],["באיזו יבשת נמצאת סן מרינו?","אירופה","מאתגרות","מוקפת לגמרי באיטליה, ונחשבת לרפובליקה העתיקה בעולם — לפי המסורת נוסדה בשנת 301.",null],["באיזו יבשת נמצאת ליכטנשטיין?","אירופה","מאתגרות","נסיכות קטנה בין שווייץ לאוסטריה — אחת משתי המדינות בעולם שמוקפות רק במדינות בלי ים.",null],["באיזו יבשת נמצאת הוותיקן?","אירופה","מאתגרות","בתוך רומא. את הצבא שלה, המשמר השווייצרי, מגייסים מאז 1506, והוא לובש מדים בסגנון הרנסנס.",null],["באיזו יבשת נמצאת קוסובו?","אירופה","מאתגרות","הכריזה עצמאות מסרביה ב-2008. מדינות רבות מכירות בה — אבל לא כולן, וסרביה בראשן.",null],["באיזו יבשת נמצאת צ׳אד?","אפריקה","מאתגרות","מדינה בלי ים, שנקראת על שם אגם צ׳אד — שהתכווץ ביותר מ-90% מאז שנות ה-60.",null],["באיזו יבשת נמצאת ניז׳ר?","אפריקה","מאתגרות","נקראת על שם נהר ניז׳ר. רובה סהרה, והיא מהמדינות החמות בעולם.",null],["באיזו יבשת נמצאת בורקינה פאסו?","אפריקה","מאתגרות",'פירוש השם: "ארץ האנשים הישרים". עד 1984 נקראה וולטה עילית.',null],["באיזו יבשת נמצאת בנין?","אפריקה","מאתגרות","רצועה צרה בין טוגו לניגריה. כאן שכנה ממלכת דהומיי, שהייתה לה יחידה מפורסמת של לוחמות.",null],["באיזו יבשת נמצאת טוגו?","אפריקה","מאתגרות","מהמדינות הצרות בעולם: החוף שלה רחב כ-50 ק״מ בלבד, והיא נמתחת צפונה לאורך כ-550 ק״מ.",null],["באיזו יבשת נמצאת גינאה?","אפריקה","מאתגרות",'מקור הנהרות הגדולים של מערב אפריקה — ניז׳ר, סנגל וגמביה — ולכן היא מכונה "מגדל המים של מערב אפריקה".',null],["באיזו יבשת נמצאת גינאה ביסאו?","אפריקה","מאתגרות","מושבה פורטוגזית לשעבר, עם ארכיפלג של עשרות איים מול החוף — איי ביז׳אגוס.",null],["באיזו יבשת נמצאת סיירה לאונה?","אפריקה","מאתגרות",'פירוש השם בפורטוגזית: "הרי הלביאה". בשנות ה-90 התחוללה בה מלחמת אזרחים סביב "יהלומי הדם".',null],["באיזו יבשת נמצאת ליבריה?","אפריקה","מאתגרות","נוסדה כמושבה לעבדים משוחררים מארה״ב, ודגלה מזכיר את הדגל האמריקאי. יחד עם אתיופיה — היחידות באפריקה שלא היו מושבות אירופיות.",null],["באיזו יבשת נמצאת גמביה?","אפריקה","מאתגרות","המדינה הקטנה ביבשת אפריקה: רצועה צרה משני צידי נהר גמביה, מוקפת כולה בסנגל — מלבד החוף.",null],["באיזו יבשת נמצאת מאוריטניה?","אפריקה","מאתגרות","רובה סהרה. רכבת המשא שלה, שמובילה עפרות ברזל, היא מהארוכות בעולם — כ-2.5 ק״מ.",null],["באיזו יבשת נמצאת כף ורדה?","אפריקה","מאתגרות","ארכיפלג של עשרה איים וולקניים באוקיינוס האטלנטי, מול סנגל. לא היו מיושבים עד שהגיעו הפורטוגזים, במאה ה-15.",null],["באיזו יבשת נמצאת סאו טומה ופרינסיפה?","אפריקה","מאתגרות","שני איים קטנים במפרץ גינאה, ליד קו המשווה. השנייה בקטנותה מבין מדינות אפריקה.",null],["באיזו יבשת נמצאת גינאה המשוונית?","אפריקה","מאתגרות","המדינה היחידה באפריקה ששפתה הרשמית ספרדית. גילוי נפט בשנות ה-90 הפך אותה לעשירה — לפחות על הנייר.",null],["באיזו יבשת נמצאת גבון?","אפריקה","מאתגרות","כ-85% משטחה מכוסה ביער גשם. בזכות נפט, היא מהמדינות העשירות יחסית באפריקה.",null],["באיזו יבשת נמצאת הרפובליקה המרכז-אפריקאית?","אפריקה","מאתגרות","מדינה בלי ים, בדיוק בלב היבשת — ומכאן שמה. עשירה ביהלומים, ובכל זאת מהעניות בעולם.",null],["באיזו יבשת נמצאת מלאווי?","אפריקה","מאתגרות","אגם מלאווי תופס כחמישית משטחה, ויש בו יותר מינים של דגים מבכל אגם אחר בעולם.",null],["באיזו יבשת נמצאת לסוטו?","אפריקה","מאתגרות","מוקפת כולה בדרום אפריקה. המדינה היחידה בעולם שכל שטחה גבוה מ-1,000 מטר מעל פני הים.",null],["באיזו יבשת נמצאת אסוואטיני?","אפריקה","מאתגרות","עד 2018 נקראה סווזילנד. מהמונרכיות המוחלטות האחרונות בעולם.",null],["באיזו יבשת נמצאת קומורו?","אפריקה","מאתגרות","ארכיפלג וולקני בין מוזמביק למדגסקר. אחד מארבעת האיים, מאיוט, נשאר בשליטת צרפת.",null],["באיזו יבשת נמצאת מאוריציוס?","אפריקה","מאתגרות","אי באוקיינוס ההודי, מזרחית למדגסקר. כאן חי הדודו — ציפור שנכחדה פחות ממאה שנה אחרי שבני האדם הגיעו.",null],["באיזו יבשת נמצאת סיישל?","אפריקה","מאתגרות","115 איים באוקיינוס ההודי — המדינה הקטנה באפריקה, גם בשטח וגם באוכלוסייה.",null],["באיזו יבשת נמצאת בליז?","צפון אמריקה","מאתגרות","המדינה היחידה במרכז אמריקה ששפתה הרשמית אנגלית. לאורך החוף — שונית המחסום השנייה בגודלה בעולם.",null],["באיזו יבשת נמצאת אל סלוודור?","צפון אמריקה","מאתגרות","המדינה הקטנה והצפופה ביותר במרכז אמריקה — והיחידה שם בלי חוף לים הקריבי.",null],["באיזו יבשת נמצאת הונדורס?","צפון אמריקה","מאתגרות",'מדינה הררית במרכז אמריקה. הביטוי "רפובליקת בננות" נטבע עליה, כשחברות בננות אמריקאיות שלטו בה בפועל.',null],["באיזו יבשת נמצאת ניקרגואה?","צפון אמריקה","מאתגרות","המדינה הגדולה במרכז אמריקה. באגם ניקרגואה שבה חיים כרישים — שהגיעו מהים במעלה הנהר.",null],["באיזו יבשת נמצאים איי בהאמה?","צפון אמריקה","מאתגרות","כ-700 איים מזרחית לפלורידה. על אחד מהם, לפי ההערכות, נחת קולומבוס לראשונה, ב-1492.",null],["באיזו יבשת נמצאת ברבדוס?","צפון אמריקה","מאתגרות","האי המזרחי ביותר בקריביים. הזמרת ריהאנה נולדה בו.",null],["באיזו יבשת נמצאת טרינידד וטובגו?","צפון אמריקה","מאתגרות","שני איים מול חופי ונצואלה — גאוגרפית כמעט דרום אמריקה. בטרינידד יש אגם זפת טבעי, הגדול בעולם.",null],["באיזו יבשת נמצאת גיאנה?","דרום אמריקה","מאתגרות","המדינה היחידה בדרום אמריקה ששפתה הרשמית אנגלית. רוב שטחה יער גשם.",null],["באיזו יבשת נמצאת סורינאם?","דרום אמריקה","מאתגרות","המדינה הקטנה בדרום אמריקה, ושפתה הרשמית הולנדית. בהסכם של 1667 היא נשארה בידי ההולנדים — וניו אמסטרדם, היא ניו יורק, בידי הבריטים.",null],["באיזו יבשת נמצאת אנטיגואה וברבודה?","צפון אמריקה","מאתגרות",'שני איים בקריביים. באנטיגואה, כך אומרים שם, יש 365 חופים — "חוף לכל יום בשנה".',null],["באיזו יבשת נמצאת דומיניקה?","צפון אמריקה","מאתגרות",'"אי הטבע של הקריביים" — הררי ומכוסה ביער גשם. לא לבלבל עם הרפובליקה הדומיניקנית.',null],["באיזו יבשת נמצאת גרנדה?","צפון אמריקה","מאתגרות",'"אי התבלינים" — מהיצרניות הגדולות של אגוז מוסקט, שמופיע גם על הדגל שלה.',null],["באיזו יבשת נמצאת סנט קיטס ונוויס?","צפון אמריקה","מאתגרות","המדינה הקטנה ביבשת אמריקה, גם בשטח וגם באוכלוסייה.",null],["באיזו יבשת נמצאת סנט לוסיה?","צפון אמריקה","מאתגרות","אי הררי בקריביים. שני הרי הפיטונס שלה, צוקים וולקניים חדים שמזדקרים מהים, הם אתר מורשת עולמית.",null],["באיזו יבשת נמצאת סנט וינסנט והגרנדינים?","צפון אמריקה","מאתגרות",'אי וולקני ושרשרת של איים קטנים בקריביים. חלק מסרטי "שודדי הקריביים" צולמו בה.',null],["באיזו יבשת נמצאת סמואה?","אוקיאניה","מאתגרות",'ב-2011 "קפצה" לצד השני של קו התאריך — כדי להתיישר עם אוסטרליה וניו זילנד — ופשוט דילגה על 30 בדצמבר.',null],["באיזו יבשת נמצאת טונגה?","אוקיאניה","מאתגרות","הממלכה הפולינזית היחידה ששמרה על עצמאותה — מעולם לא הייתה מושבה.",null],["באיזו יבשת נמצאת ונואטו?","אוקיאניה","מאתגרות","ארכיפלג וולקני בדרום האוקיינוס השקט. קפיצת הבנג׳י נולדה מטקס שבו קופצים מגבהים עם גפנים קשורות לרגליים, באחד מאייה.",null],["באיזו יבשת נמצאים איי שלמה?","אוקיאניה","מאתגרות","כ-900 איים מזרחית לפפואה גינאה החדשה. נקראו על שם שלמה המלך: המגלה הספרדי קיווה למצוא בהם את אוצרותיו.",null],["באיזו יבשת נמצאת קיריבטי?","אוקיאניה","מאתגרות","פרושה על פני מיליוני קמ״ר של אוקיינוס, משני צידי קו המשווה ושל קו התאריך. היא הראשונה בעולם שנכנסת לשנה החדשה.",null],["באיזו יבשת נמצאת טובאלו?","אוקיאניה","מאתגרות","מהמדינות הקטנות בעולם, ושום מקום בה לא גבוה מכחמישה מטרים. סיומת האינטרנט שלה, ‎.tv, מכניסה לה הכנסה נכבדה.",null],["באיזו יבשת נמצאת נאורו?","אוקיאניה","מאתגרות","הרפובליקה הקטנה בעולם, ואין לה בירה רשמית. עושרה בא מכריית פוספט — שהרסה את רוב פני האי.",null],["באיזו יבשת נמצאת פלאו?","אוקיאניה","מאתגרות",'ארכיפלג במערב האוקיינוס השקט. "אגם המדוזות" שלו מלא במיליוני מדוזות שכמעט אינן עוקצות.',null],["באיזו יבשת נמצאים איי מרשל?","אוקיאניה","מאתגרות","אטולים במרכז האוקיינוס השקט. באטול ביקיני ערכה ארה״ב ניסויים גרעיניים — ובגד הים נקרא על שמו.",null],["באיזו יבשת נמצאת מיקרונזיה?","אוקיאניה","מאתגרות",'כ-600 איים בארבע מדינות פדרליות. "מיקרונזיה" ביוונית: "איים קטנים".',null],["באיזו יבשת נמצאת גרינלנד?","צפון אמריקה","טריטוריות","גאוגרפית שייכת לצפון אמריקה, אבל פוליטית — לדנמרק. רוב שטחה מכוסה בשכבת קרח בעובי של קילומטרים.",null],["באיזו יבשת נמצאת פוארטו ריקו?","צפון אמריקה","טריטוריות","טריטוריה של ארה״ב בקריביים. תושביה אזרחים אמריקאים, אבל לא מצביעים בבחירות לנשיאות.",null],["באיזו יבשת נמצאים איי פארו?","אירופה","טריטוריות",'18 איים בין איסלנד לנורווגיה, תחת ריבונות דנמרק. השם בפארואית: "איי הכבשים".',null],["באיזו יבשת נמצאת גיברלטר?","אירופה","טריטוריות","טריטוריה בריטית בקצה הדרומי של ספרד, על צוק ענק. ספרד דורשת אותה בחזרה מאז 1713.",null],["באיזו יבשת נמצאת ברמודה?","צפון אמריקה","טריטוריות",'טריטוריה בריטית באוקיינוס האטלנטי — לא בקריביים, כמו שרבים חושבים. "משולש ברמודה" נקרא על שמה.',null],["באיזו יבשת נמצאת האי מאן?","אירופה","טריטוריות","בים האירי, בין בריטניה לאירלנד. תלוי בכתר הבריטי אבל אינו חלק מהממלכה המאוחדת, ויש לו פרלמנט עתיק משלו — הטינוולד.",null],["באיזו יבשת נמצאת ג׳רזי?","אירופה","טריטוריות","האי הגדול באיי התעלה, קרוב יותר לצרפת מלאנגליה. מדינת ניו ג׳רזי האמריקאית נקראה על שמו.",null],["באיזו יבשת נמצאת גרנזי?","אירופה","טריטוריות","אי בתעלת למאנש, תלוי בכתר הבריטי. פרת גרנזי, בצבע חום-זהוב, קרויה על שמו.",null],["באיזו יבשת נמצאים איי אולנד?","אירופה","טריטוריות","ארכיפלג בין שוודיה לפינלנד, תחת ריבונות פינלנד — אבל התושבים דוברים שוודית, והאיים מפורזים.",null],["באיזו יבשת נמצאת סבאלבארד?","אירופה","טריטוריות",'ארכיפלג נורווגי בדרך לקוטב הצפוני. בו נמצאת "כספת זרעי יום הדין" — מאגר עולמי של זרעים לשעת חירום.',null],["באיזו יבשת נמצאת פולינזיה הצרפתית?","אוקיאניה","טריטוריות","118 איים ואטולים, ובהם טהיטי ובורה בורה, פרושים על שטח ים בגודל של אירופה.",null],["באיזו יבשת נמצאת קלדוניה החדשה?","אוקיאניה","טריטוריות","טריטוריה צרפתית ממזרח לאוסטרליה, עם אחת מלגונות האלמוגים הגדולות בעולם. עשירה בניקל.",null],["באיזו יבשת נמצאים איי קיימן?","צפון אמריקה","טריטוריות","טריטוריה בריטית בקריביים, ומרכז פיננסי בינלאומי — רשומות בה יותר חברות מתושבים.",null],["באיזו יבשת נמצאים איי הבתולה הבריטיים?","צפון אמריקה","טריטוריות","טריטוריה בריטית בקריביים. קולומבוס קרא לאיים על שם אורסולה הקדושה ו-11 אלף הבתולות שלה.",null],["באיזו יבשת נמצאים איי הבתולה של ארצות הברית?","צפון אמריקה","טריטוריות","ארה״ב קנתה אותם מדנמרק ב-1917. בניגוד לשאר ארה״ב, נוהגים בהם בצד שמאל של הכביש.",null],["באיזו יבשת נמצאת גואם?","אוקיאניה","טריטוריות","טריטוריה של ארה״ב במערב האוקיינוס השקט, עם בסיסים צבאיים גדולים. האי הגדול באיי מריאנה.",null],["באיזו יבשת נמצאת סמואה האמריקנית?","אוקיאניה","טריטוריות","החלק המזרחי של איי סמואה, טריטוריה של ארה״ב. אחד המקומות האחרונים בעולם שבהם השנה מתחלפת.",null],["באיזו יבשת נמצאים איי מריאנה הצפוניים?","אוקיאניה","טריטוריות","טריטוריה של ארה״ב. לא הרחק מהם נמצא תהום מריאנה — המקום העמוק ביותר באוקיינוסים.",null],["באיזו יבשת נמצאת ארובה?","צפון אמריקה","טריטוריות","אי הולנדי מול חופי ונצואלה, מחוץ לחגורת ההוריקנים — ולכן כמעט תמיד יבש ושמשי.",null],["באיזו יבשת נמצאת קוראסאו?","צפון אמריקה","טריטוריות",'אי הולנדי בקריביים, שנתן את שמו לליקר הכחול. בית הכנסת "מקווה ישראל-עמנואל" שבו הוא הוותיק ביבשת אמריקה שפעיל ברציפות.',null],["באיזו יבשת נמצאת סינט מארטן?","צפון אמריקה","טריטוריות","החצי ההולנדי של אי קטן; החצי השני, סן מרטן, צרפתי. מהאיים הקטנים בעולם שמחולקים בין שתי מדינות.",null],["באיזו יבשת נמצאים איי פוקלנד?","דרום אמריקה","טריטוריות",'טריטוריה בריטית מול ארגנטינה, שקוראת להם "איי מלווינס". ב-1982 נלחמו עליהם שתי המדינות.',null],["באיזו יבשת נמצאת סנט הלנה?","אפריקה","טריטוריות","אי מבודד באמצע האוקיינוס האטלנטי הדרומי. לכאן הוגלה נפוליאון אחרי ווטרלו, וכאן מת.",null],["באיזו יבשת נמצאת ראוניון?","אפריקה","טריטוריות","אי וולקני באוקיינוס ההודי — חלק רשמי מצרפת ומהאיחוד האירופי, למרות המרחק.",null],["באיזו יבשת נמצאת מרטיניק?","צפון אמריקה","טריטוריות","אי צרפתי בקריביים. ב-1902 השמידה התפרצות הר פלה את העיר סן פייר, ונספו כ-28 אלף איש.",null],["באיזו יבשת נמצאת גוואדלופ?","צפון אמריקה","טריטוריות","ארכיפלג צרפתי בקריביים, בצורת פרפר: שני איים עיקריים שמפריד ביניהם ערוץ צר.",null],["באיזו יבשת נמצאת גיאנה הצרפתית?","דרום אמריקה","טריטוריות","חלק רשמי מצרפת בדרום אמריקה. מכאן משגרת סוכנות החלל האירופית רקטות — קרוב לקו המשווה.",null],["באיזו יבשת נמצאת מאיוט?","אפריקה","טריטוריות","אחד מאיי קומורו, שבחר להישאר צרפתי. מאז 2011 הוא חלק רשמי מצרפת.",null],["באיזו יבשת נמצאים איי קוק?","אוקיאניה","טריטוריות",'15 איים בדרום האוקיינוס השקט, ב"התאגדות חופשית" עם ניו זילנד. נקראו על שם הנווט ג׳יימס קוק.',null],["באיזו יבשת נמצאת ניואה?","אוקיאניה","טריטוריות","מהאיים הגדולים בעולם שבנויים מאלמוגים. גרים בו כ-2,000 איש — ורבים יותר מבני האי גרים בניו זילנד.",null],["באיזו יבשת נמצאים איי טרקס וקאיקוס?","צפון אמריקה","טריטוריות","טריטוריה בריטית מדרום-מזרח לאיי בהאמה, עם חופים לבנים ומים צלולים במיוחד.",null],["באיזו יבשת נמצאת אנגווילה?","צפון אמריקה","טריטוריות","אי בריטי קטן בקריביים. סיומת האינטרנט שלו, ‎.ai, הפכה למבוקשת בעידן הבינה המלאכותית — ומכניסה לו הכנסה נכבדה.",null],["באיזו יבשת נמצאת מונטסראט?","צפון אמריקה","טריטוריות",'"האי האמרלד של הקריביים" — רבים מהמתיישבים המקוריים בו היו אירים. התפרצות געשית בשנות ה-90 החריבה את בירתו.',null],["באיזו יבשת נמצאת סהרה המערבית?","אפריקה","טריטוריות","שטח במחלוקת על חוף האוקיינוס האטלנטי: מרוקו שולטת ברובו, וחזית הפוליסריו דורשת עצמאות.",null],["באיזו יבשת נמצאת סן פייר ומיקלון?","צפון אמריקה","טריטוריות",'שני איים צרפתיים קטנים מול חופי קנדה — כל מה שנשאר לצרפת מ"צרפת החדשה" בצפון אמריקה.',null],["באיזו יבשת נמצאת ווליס ופוטונה?","אוקיאניה","טריטוריות","טריטוריה צרפתית באוקיינוס השקט, שיש בה עדיין שלושה מלכים מסורתיים.",null],["כמה יבשות יש לפי החלוקה המקובלת?","שבע","עובדות ושיאים","אסיה, אפריקה, צפון אמריקה, דרום אמריקה, אנטארקטיקה, אירופה ואוסטרליה. יש גם חלוקות אחרות: חמש הטבעות האולימפיות מסמלות חמש יבשות מיושבות.",null],["מהי היבשת הגדולה ביותר בשטח?","אסיה","עובדות ושיאים","כשליש משטח היבשה בעולם — ויותר ממחצית מבני האדם חיים בה.",null],["מהי היבשת הקטנה ביותר בשטח?","אוסטרליה","עובדות ושיאים","היא גם השטוחה והיבשה ביותר מבין היבשות המיושבות.",["באיזה שיא מחזיקה אוסטרליה בין היבשות?","הקטנה ביותר בשטח"]],["מהי היבשת המאוכלסת ביותר?","אסיה","עובדות ושיאים","יותר מ-4.5 מיליארד בני אדם — ובראשן הודו וסין, שבכל אחת מהן יותר ממיליארד.",null],["מהי היבשת היחידה ללא אוכלוסייה קבועה?","אנטארקטיקה","עובדות ושיאים","רק אנשי מחקר, באלפים, בתחנות. היא גם היבשת הקרה, היבשה והגבוהה ביותר בממוצע.",["מה מיוחד באנטארקטיקה מבחינת האוכלוסייה?","זו היבשת היחידה שאין בה תושבים קבועים"]],["מהי היבשת השנייה בגודלה?","אפריקה","עובדות ושיאים","יש בה 54 מדינות — יותר מבכל יבשת אחרת. המפות הרגילות מקטינות אותה: בפועל ארה״ב, סין והודו יחד היו נכנסות בתוכה.",["איזה מקום תופסת אפריקה בגודל, בין היבשות?","השני — אחרי אסיה"]],["מהי המדינה הגדולה בעולם בשטח?","רוסיה","עובדות ושיאים","כמעט פי שניים מקנדה, השנייה ברשימה. היא משתרעת על 11 אזורי זמן.",["באיזה שיא מחזיקה רוסיה בין מדינות העולם?","הגדולה בעולם בשטח"]],["מהי המדינה הקטנה בעולם?","הוותיקן","עובדות ושיאים","כ-0.44 קמ״ר — בערך שמינית מסנטרל פארק בניו יורק. גרים בה כמה מאות אנשים בלבד.",["באיזה שיא מחזיק הוותיקן בין מדינות העולם?","המדינה הקטנה בעולם"]],["מהי המדינה המאוכלסת בעולם?","הודו","עובדות ושיאים","עקפה את סין ב-2023, ויש בה יותר מ-1.4 מיליארד תושבים.",["באיזה שיא מחזיקה הודו מאז 2023?","המדינה המאוכלסת בעולם"]],["איזו מדינה משתרעת על היבשת כולה?","אוסטרליה","עובדות ושיאים","המדינה היחידה בעולם שהיא גם יבשת שלמה. לאורך החוף שלה שונית המחסום הגדולה — המבנה הגדול בעולם שבנו יצורים חיים.",null],["כמה מדינות חברות באו״ם?","193","עובדות ושיאים","האחרונה שהצטרפה היא דרום סודן, ב-2011.",null],["כמה מדינות יש בעולם, כולל משקיפות באו״ם?","195","עובדות ושיאים","193 החברות, ועוד שתי משקיפות: הוותיקן ופלסטין.",null],["איזו יבשת חוצה את קו המשווה במרכזה?","אפריקה","עובדות ושיאים","אפריקה היא היבשת היחידה שגם קו המשווה, גם חוג הסרטן וגם חוג הגדי עוברים דרכה.",null],["לאיזו יבשת שייך חצי האי סיני?","אסיה","עובדות ושיאים","תעלת סואץ נחשבת לגבול בין אפריקה לאסיה — ולכן סיני, שממזרח לה, נמצא באסיה, אף שהוא שייך למצרים.",null],["מהי טריטוריה, בשונה ממדינה?","שטח בשליטת מדינה אחרת, בלי ריבונות מלאה","עובדות ושיאים","למשל גרינלנד, ששייכת לדנמרק, או פוארטו ריקו, ששייכת לארה״ב. לחלק מהטריטוריות יש שלטון עצמי רחב.",["איך נקרא שטח שנמצא בשליטת מדינה אחרת, בלי ריבונות מלאה?","טריטוריה"]],["לאיזו מדינה שייכת גרינלנד?","דנמרק","עובדות ושיאים","לגרינלנד שלטון עצמי רחב. גרים בה כ-57 אלף איש — על שטח גדול פי חמישים מדנמרק.",["איזה אי ענק בצפון האוקיינוס האטלנטי שייך לדנמרק?","גרינלנד"]],["לאיזו מדינה שייכת פוארטו ריקו?","ארצות הברית","עובדות ושיאים","ארה״ב קיבלה אותה מספרד ב-1898, אחרי מלחמת ספרד-ארה״ב. השאלה אם להפוך אותה למדינה ה-51 עולה שוב ושוב.",null],["לאיזו מדינה שייכת פולינזיה הצרפתית?","צרפת","עובדות ושיאים","באטולים מורורואה ופנגטאופה שבה ערכה צרפת ניסויים גרעיניים, עד 1996.",null]]},r={id:"geo-terms",name:"מושגים בגאוגרפיה",description:"מושגי יסוד — ממיצרים ועד אקלים ותבליט. מה שמופיע בתשבצים ובחדשות ולא תמיד ברור.",cards:[["מהו מיצר?","רצועת ים צרה המחברת שני גופי מים","תבליט ומים","דוגמאות: מיצר גיברלטר, בין אירופה לאפריקה, ומיצר הורמוז — שדרכו עוברת כחמישית מהנפט בעולם.",["איך נקראת רצועת ים צרה שמחברת שני גופי מים?","מיצר"]],["מהו מפרץ?","חלק מים החודר לתוך היבשה","תבליט ומים","המפרץ הגדול בעולם הוא מפרץ בנגל, ליד הודו. ובישראל — מפרץ חיפה ומפרץ אילת.",["איך נקרא חלק של ים שחודר לתוך היבשה?","מפרץ"]],["מהו חצי אי?","שטח יבשה המוקף מים משלושה צדדים","תבליט ומים",'"חצי" אי, כי רק צד אחד שלו מחובר ליבשה. חצי האי הגדול בעולם הוא חצי האי ערב.',["איך נקרא שטח יבשה שמוקף מים משלושה צדדים?","חצי אי"]],["מהו ארכיפלג?","קבוצת איים","תבליט ומים",'מיוונית: "הים הראשי" — כך כינו היוונים את הים האגאי, שזרוע באיים. אינדונזיה היא הארכיפלג הגדול בעולם.',["איך נקראת קבוצת איים?","ארכיפלג"]],["מהי דלתא של נהר?","מניפת סעיפים שהנהר יוצר בשפכו לים","תבליט ומים","על שם האות היוונית דלתא, Δ — כך נראית מלמעלה הדלתא של הנילוס, וכך כינה אותה כבר ההיסטוריון הרודוטוס.",["איך נקראת מניפת הסעיפים שהנהר יוצר כשהוא נשפך לים?","דלתא"]],["מהו יובל?","נהר קטן הנשפך לנהר גדול יותר","תבליט ומים",'"יובל" מאותו שורש של "הובלה": הוא מוביל מים אל הנהר הגדול. לאמזונס יש יותר מאלף יובלים.',["איך נקרא נהר קטן שנשפך לנהר גדול ממנו?","יובל"]],["מהו אגן ניקוז?","כל השטח שממנו מים זורמים לנהר אחד","תבליט ומים","בין שני אגנים עובר קו פרשת המים: טיפת גשם שנופלת מצד אחד שלו תגיע לנהר אחד, ומהצד השני — לנהר אחר.",["איך נקרא כל השטח שממנו המים זורמים לנהר אחד?","אגן ניקוז"]],["מהי פסגה?","הנקודה הגבוהה ביותר של הר","תבליט ומים",'מכאן גם "ועידת פסגה" — מפגש של המנהיגים הבכירים ביותר.',["איך נקראת הנקודה הגבוהה ביותר של הר?","פסגה"]],["מהי רמה?","שטח גבוה ושטוח יחסית","תבליט ומים","רמת הגולן היא דוגמה קרובה. הרמה הגבוהה בעולם היא רמת טיבט — בגובה ממוצע של יותר מ-4,500 מטר.",["איך נקרא שטח גבוה ושטוח יחסית?","רמה"]],["מהו עמק?","שקע מוארך בין הרים","תבליט ומים","בישראל: עמק יזרעאל ועמק החולה. והשבר הסורי-אפריקאי יצר בקע ארוך, שבו זורם הירדן ושוכן ים המלח.",["איך נקרא שקע מוארך בין הרים?","עמק"]],["מהו קניון?","עמק צר ועמוק עם דפנות תלולות","תבליט ומים","מספרדית cañón — צינור. הגרנד קניון שבאריזונה עמוק כמעט שני קילומטרים, ונחצב בידי נהר הקולורדו במשך מיליוני שנים.",["איך נקרא עמק צר ועמוק עם דפנות תלולות?","קניון"]],["מהו קרחון?","גוש קרח עצום הזז לאט על פני הקרקע","תבליט ומים","כשני שלישים מהמים המתוקים בעולם קפואים בקרחונים — רובם באנטארקטיקה ובגרינלנד.",["איך נקרא גוש קרח עצום שזז לאט על פני הקרקע?","קרחון"]],["מהו פיורד?","מפרץ צר ועמוק שנוצר מקרחון","תבליט ומים","המילה נורווגית. הפיורד הארוך בנורווגיה, סוגנפיורד, חודר יותר מ-200 ק״מ לתוך היבשה.",["איך נקרא מפרץ צר ועמוק שנוצר מקרחון?","פיורד"]],["מהי טונדרה?","אזור קפוא בצפון, ללא עצים","אקלים וקווי המפה",'מתחת לפני הקרקע יש בה שכבה שקפואה כל השנה — "פרמפרוסט". בקיץ הקצר רק השכבה העליונה מפשירה, ונוצרות ביצות.',["איך נקרא אזור קפוא בצפון, בלי עצים?","טונדרה"]],["מהי טייגה?","יער מחטני ענק בצפון אירואסיה וצפון אמריקה","אקלים וקווי המפה","היער היבשתי הגדול בעולם — רצועה של אורנים, אשוחים ולגשים, מסקנדינביה דרך סיביר ועד קנדה.",["איך נקרא היער המחטני העצום בצפון אירואסיה ובצפון אמריקה?","טייגה"]],["מהי סוואנה?","ערבה טרופית עם עשב גבוה ועצים מפוזרים","אקלים וקווי המפה",'הנוף של "מלך האריות": עשב גבוה, עצי שיטה בודדים ועדרים גדולים. יש בה עונה גשומה ועונה יבשה.',["איך נקראת ערבה טרופית עם עשב גבוה ועצים מפוזרים?","סוואנה"]],["מהי סטפה?","ערבת עשב ממוזגת, ללא עצים","אקלים וקווי המפה",'הסטפה האירואסייתית נמתחת מהונגריה ועד מנצ׳וריה. זו הייתה "הדרך המהירה" של שבטי הפרשים — מההונים ועד המונגולים.',["איך נקראת ערבת עשב ממוזגת, בלי עצים?","סטפה"]],["מהו אקלים ים תיכוני?","קיץ חם ויבש, חורף מתון וגשום","אקלים וקווי המפה","מלבד אגן הים התיכון — וישראל בתוכו — הוא קיים גם בקליפורניה, במרכז צ׳ילה, באזור קייפטאון ובדרום אוסטרליה. ובכולם גדלים כרמים.",["איך נקרא אקלים של קיץ חם ויבש וחורף מתון וגשום?","אקלים ים תיכוני"]],["מהו אקלים טרופי?","חם וגשום כל השנה","אקלים וקווי המפה","בעיקר בין חוג הסרטן לחוג הגדי. ביערות הגשם הטרופיים חיים כמחצית ממיני הצמחים ובעלי החיים בעולם.",["איך נקרא אקלים חם וגשום לאורך כל השנה?","אקלים טרופי"]],["מהו קו המשווה?","קו הרוחב האמצעי, במרחק שווה משני הקטבים","אקלים וקווי המפה","אורכו כ-40,000 ק״מ. מי שעומד עליו מסתובב עם כדור הארץ במהירות של כ-1,670 קמ״ש.",["איך נקרא קו הרוחב האמצעי, שנמצא במרחק שווה משני הקטבים?","קו המשווה"]],["מהו קו רוחב?","קו מדומה המקביל לקו המשווה","אקלים וקווי המפה","נמדד במעלות — מ-0 בקו המשווה ועד 90 בקטבים. תל אביב יושבת בערך על קו רוחב 32 צפון.",["איך נקרא קו מדומה שמקביל לקו המשווה?","קו רוחב"]],["מהו קו אורך?","קו מדומה מהקוטב הצפוני לדרומי","אקלים וקווי המפה","כל קווי האורך נפגשים בקטבים. בים היה קשה מאוד למדוד אותם — עד שהומצא, במאה ה-18, שעון ימי מדויק.",["איך נקרא קו מדומה שעובר מהקוטב הצפוני לקוטב הדרומי?","קו אורך"]],["היכן עובר קו האורך אפס?","גריניץ׳, לונדון","אקלים וקווי המפה","נקבע בוועידה בינלאומית ב-1884, כי רוב הספינות בעולם כבר השתמשו במפות בריטיות. מכאן גם GMT — שעון גריניץ׳.",["איזה קו אורך עובר בגריניץ׳ שבלונדון?","קו האורך אפס"]],["מהו קו התאריך?","קו האורך 180 מעלות — שם מתחלף התאריך","אקלים וקווי המפה",'הקו אינו ישר: הוא עוקף מדינות שלמות כדי לא לחצות אותן. מי שחוצה אותו מערבה "מאבד" יום, ומי שחוצה מזרחה — "מרוויח" יום.',["איך נקרא הקו שבו מתחלף התאריך — סביב קו האורך 180?","קו התאריך"]],["מהו חוג הסרטן?","קו הרוחב הצפוני שבו השמש בזנית ב-21 ביוני","אקלים וקווי המפה","בערך 23.5 מעלות צפון. השם מתקופה שבה השמש, ביום הארוך בשנה, עמדה במזל סרטן.",["איך נקרא קו הרוחב הצפוני שבו השמש בזנית ב-21 ביוני?","חוג הסרטן"]],["מהו חוג הגדי?","קו הרוחב הדרומי שבו השמש בזנית ב-21 בדצמבר","אקלים וקווי המפה","בערך 23.5 מעלות דרום. הוא עובר בין השאר דרך אוסטרליה, דרום אפריקה, ברזיל וצ׳ילה.",["איך נקרא קו הרוחב הדרומי שבו השמש בזנית ב-21 בדצמבר?","חוג הגדי"]],["מהי טקטוניקת לוחות?","התיאוריה שקליפת כדור הארץ בנויה מלוחות נעים","אקלים וקווי המפה","הלוחות זזים כמה סנטימטרים בשנה — בערך בקצב שבו צומחות ציפורניים. ישראל יושבת על הגבול בין הלוח הערבי ללוח האפריקאי.",["איך נקראת התיאוריה שקליפת כדור הארץ בנויה מלוחות נעים?","טקטוניקת לוחות"]],["מהו שבר גאולוגי?","סדק בקרום כדור הארץ שלאורכו יש תזוזה","אקלים וקווי המפה","שבר סן אנדראס בקליפורניה הוא המפורסם בעולם. בישראל — השבר הסורי-אפריקאי, לאורך הערבה, ים המלח והירדן.",["איך נקרא סדק בקרום כדור הארץ שלאורכו יש תזוזה?","שבר גאולוגי"]],["מהו הר געש מגן?","הר געש רחב ומשופע מתון, מלבה נוזלית","אקלים וקווי המפה","השם — כי הוא נראה כמו מגן של לוחם מונח על הארץ. הרי הגעש של הוואי הם הדוגמה הקלאסית.",["איך נקרא הר געש רחב ומשופע מתון, שנוצר מלבה נוזלית?","הר געש מגן"]],["מהו צונאמי?","גל ענק בים שנוצר מרעידת אדמה תת-ימית","אקלים וקווי המפה",'ביפנית: "גל הנמל". בלב האוקיינוס הוא כמעט לא מורגש, אבל ליד החוף הוא מתרומם לגובה עצום. הצונאמי של 2004 באוקיינוס ההודי הרג כ-230 אלף איש.',["איך נקרא גל ענק בים שנוצר מרעידת אדמה תת-ימית?","צונאמי"]],["מהו סולם ריכטר?","סולם למדידת עוצמת רעידות אדמה","אקלים וקווי המפה",'כל דרגה בסולם מייצגת אנרגיה גדולה פי כ-32. הסייסמולוגים עברו מזמן לסולם מתקדם יותר, אבל בתקשורת עדיין אומרים "בסולם ריכטר".',["איך נקרא הסולם המפורסם למדידת עוצמת רעידות אדמה?","סולם ריכטר"]],["מהו מדבר?","אזור שבו יורדים פחות מ-250 מ״מ גשם בשנה","אקלים וקווי המפה","מדבר מוגדר לפי כמות הגשם, לא לפי החום — ולכן גם אנטארקטיקה הקפואה היא מדבר. בישראל, יותר ממחצית השטח מדברי.",["איך נקרא אזור שבו יורדים פחות מ-250 מ״מ גשם בשנה?","מדבר"]],["מהו נווה מדבר?","אזור פורה במדבר, סביב מקור מים","אקלים וקווי המפה",'בלועזית: אואזיס. עין גדי, ליד ים המלח, היא נווה מדבר מפורסם — כבר בשיר השירים: "בכרמי עין גדי".',["איך נקרא אזור פורה במדבר, סביב מקור מים?","נווה מדבר (אואזיס)"]],["מהו מדבור?","תהליך שבו קרקע פורייה הופכת למדבר","אקלים וקווי המפה","הסיבות: בצורת, רעייה מופרזת וכריתת עצים. אזור הסאהל, מדרום לסהרה, הוא הדוגמה המוכרת ביותר.",["איך נקרא התהליך שבו קרקע פורייה הופכת למדבר?","מדבור"]],["מהי שחיקה (סחיפה)?","בלייה והסעה של קרקע וסלע על ידי מים או רוח","אקלים וקווי המפה","המים חצבו את הגרנד קניון, והרוח פיסלה את צורות הסלע של המדבר. גם המכתש ברמון נוצר מסחיפה — לא מפגיעת מטאוריט.",["איך נקראת בלייה והסעה של קרקע וסלע על ידי מים או רוח?","סחיפה (שחיקה)"]],["מהי קרקע סחף?","קרקע פורייה שהובאה על ידי נהר","אקלים וקווי המפה","הנילוס הציף את גדותיו מדי שנה והשאיר שכבת סחף פורייה — וכך הפך את מצרים לאסם התבואה של העולם העתיק, עד שסכר אסואן עצר את השיטפונות.",["איך נקראת קרקע פורייה שהביא נהר?","קרקע סחף"]],["מהו אקוויפר?","שכבת סלע נקבובית האוגרת מי תהום","אקלים וקווי המפה","בישראל יש שני אקוויפרים גדולים: אקוויפר החוף ואקוויפר ההר. המים מחלחלים בהם לאט, בתוך הסלע הנקבובי.",["איך נקראת שכבת סלע נקבובית שאוגרת מי תהום?","אקוויפר"]],["מהי צפיפות אוכלוסין?","מספר התושבים לקילומטר רבוע","אוכלוסייה ושיאים","מונקו היא המדינה הצפופה בעולם — יותר מ-18 אלף תושבים לקמ״ר. ישראל צפופה מאוד בין המדינות המפותחות, עם יותר מ-400 לקמ״ר.",["איך נקרא מספר התושבים לקילומטר רבוע?","צפיפות אוכלוסין"]],["מהי הגירה?","מעבר של אנשים ממקום מגורים אחד לאחר","אוכלוסייה ושיאים","הגירה פנימה נקראת אימיגרציה, החוצה — אמיגרציה. ולהגירה לישראל יש בעברית מילה משלה: עלייה.",["איך נקרא מעבר של אנשים ממקום מגורים אחד לאחר?","הגירה"]],["מהו עיור?","תהליך המעבר של אוכלוסייה מהכפר לעיר","אוכלוסייה ושיאים","בסביבות 2007 עבר העולם קו היסטורי: לראשונה, יותר ממחצית האנושות גרה בערים.",["איך נקרא התהליך שבו האוכלוסייה עוברת מהכפר לעיר?","עיור"]],["מהו תמ״ג?","סך הערך של כל הסחורות והשירותים שמדינה מייצרת בשנה","אוכלוסייה ושיאים","ראשי תיבות: תוצר מקומי גולמי — באנגלית GDP. כדי להשוות רמת חיים בודקים תמ״ג לנפש, כי התמ״ג הכולל תלוי בעיקר בגודל האוכלוסייה.",["איך נקרא סך הערך של כל הסחורות והשירותים שמדינה מייצרת בשנה?","תמ״ג — תוצר מקומי גולמי"]],["מהו מטרופולין?","עיר גדולה יחד עם הערים שסביבה","אוכלוסייה ושיאים",'מיוונית: meter (אם) + polis (עיר) — "עיר אם". המטרופולין הגדול בעולם הוא טוקיו רבתי, עם כ-37 מיליון תושבים.',["איך נקראת עיר גדולה יחד עם הערים שסביבה?","מטרופולין"]],["מהו נהר האמזונס?","הנהר הגדול בעולם בנפח מים, בדרום אמריקה","אוכלוסייה ושיאים","כמות המים שהוא שופך דוחקת את מי הים עשרות קילומטרים מהחוף — ספנים יכלו לדלות מים מתוקים בלב הים.",["איזה נהר הוא הגדול בעולם בנפח המים?","האמזונס"]],["מהו הנהר הארוך בעולם?","הנילוס","אוכלוסייה ושיאים","הוא זורם צפונה, דרך אגן ניקוז שמשתרע על 11 מדינות. יש חוקרים שטוענים שהאמזונס ארוך ממנו — הכול תלוי איפה מגדירים את המקור.",["באיזה שיא מחזיק הנילוס בין נהרות העולם?","הנהר הארוך בעולם (לפי רוב המדידות)"]],["מהו האוקיינוס הגדול בעולם?","האוקיינוס השקט","אוכלוסייה ושיאים",'גדול מכל היבשות יחד. מגלן קרא לו "השקט" כי הגיע אליו בתקופה של מזג אוויר רגוע.',["באיזה שיא מחזיק האוקיינוס השקט?","האוקיינוס הגדול בעולם"]],["מהו המדבר הגדול בעולם?","אנטארקטיקה — מדבר קר","אוכלוסייה ושיאים","יורדים בה פחות משקעים מאשר בסהרה. בעמקים היבשים שלה לא ירדו גשם או שלג כנראה מיליוני שנים.",null],["מהו המדבר החם הגדול בעולם?","הסהרה","אוכלוסייה ושיאים","לפני כ-6,000 שנה הסהרה הייתה ירוקה, עם אגמים, היפופוטמים ותנינים — וציורי סלע מאותה תקופה מתעדים את זה.",null],["מהו ההר הגבוה בעולם?","האוורסט","אוכלוסייה ושיאים",'8,849 מטר. בטיבטית הוא נקרא צ׳ומולונגמה — "אם העולם". אדמונד הילרי וטנזינג נורגיי היו הראשונים שהגיעו לפסגה, ב-1953.',["באיזה שיא מחזיק האוורסט?","ההר הגבוה בעולם"]],["מהי הנקודה הנמוכה ביבשה?","ים המלח","אוכלוסייה ושיאים","כ-430 מטר מתחת לפני הים — ויורד בכמטר בשנה, כי מי הירדן כמעט לא מגיעים אליו עוד.",null],["מהו האגם הגדול בעולם בשטח?","הים הכספי","אוכלוסייה ושיאים",'נקרא "ים", אבל הוא אגם — בגודל של גרמניה בערך. המים בו מלוחים למחצה.',["באיזה שיא מחזיק הים הכספי?","האגם הגדול בעולם בשטח"]],["מהו האגם העמוק בעולם?","אגם בייקל, סיביר","אוכלוסייה ושיאים","עומקו כ-1,640 מטר, והוא מכיל כחמישית מכל המים המתוקים הלא-קפואים בעולם. גילו כ-25 מיליון שנה — האגם העתיק בעולם.",["באיזה שיא מחזיק אגם בייקל?","האגם העמוק בעולם"]],["איזה מיצר מפריד בין אירופה לאפריקה?","מיצר גיברלטר","אוכלוסייה ושיאים",'רוחבו בנקודה הצרה כ-14 ק״מ. ביוון העתיקה קראו לצוקים שמשני צידיו "עמודי הרקולס" — קצה העולם הידוע.',["בין אילו יבשות מפריד מיצר גיברלטר?","אירופה ואפריקה"]],["איזה מיצר מפריד בין אסיה לאמריקה?","מיצר ברינג","אוכלוסייה ושיאים",'רוחבו כ-82 ק״מ. בעידן הקרח הוא היה יבשה — "גשר ברינג" — ודרכו הגיעו בני האדם הראשונים לאמריקה.',["בין אילו יבשות מפריד מיצר ברינג?","אסיה ואמריקה"]],["איזו תעלה מחברת את הים התיכון לים סוף?","תעלת סואץ","אוכלוסייה ושיאים","נפתחה ב-1869, וקיצרה את הדרך מאירופה להודו באלפי קילומטרים: כבר לא צריך להקיף את אפריקה.",["אילו ימים מחברת תעלת סואץ?","את הים התיכון ואת ים סוף"]],["איזו תעלה מחברת את האוקיינוס האטלנטי לשקט?","תעלת פנמה","אוכלוסייה ושיאים","נפתחה ב-1914. הספינות עוברות בה דרך תאי שיט, שמרימים אותן כ-26 מטר מעל פני הים — ומורידים בחזרה.",["אילו אוקיינוסים מחברת תעלת פנמה?","את האוקיינוס האטלנטי ואת האוקיינוס השקט"]],["מהו רכס ההרים הארוך בעולם?","האנדים","אוכלוסייה ושיאים","אם סופרים גם רכסים תת-ימיים, השיא שייך לרכס המרכז-אוקייני — עשרות אלפי קילומטרים מתחת לפני הים. על היבשה — האנדים.",null],["מהו ההר הגבוה באפריקה?","קילימנג׳רו","אוכלוסייה ושיאים","5,895 מטר, ועל הפסגה שלג — כמעט על קו המשווה. זה הר געש רדום, ואפשר לטפס אליו בלי ציוד טיפוס.",["באיזה שיא מחזיק הקילימנג׳רו?","ההר הגבוה באפריקה"]],["מהו האי הגדול בעולם?","גרינלנד","אוכלוסייה ושיאים","אוסטרליה גדולה ממנה פי שלושה וחצי, אבל נחשבת ליבשת. המפות הרגילות מגדילות את גרינלנד מאוד: בפועל אפריקה גדולה ממנה פי 14.",null],["מהי המדינה עם הכי הרבה שכנות יבשתיות?","סין ורוסיה — 14 כל אחת","אוכלוסייה ושיאים","לרוסיה יש גבול גם עם צפון קוריאה, ולסין — עם אפגניסטן, ברצועה צרה ומרוחקת בשם פרוזדור ואחאן.",null],["מהו קו וואלאס?","קו מדומה המפריד בין בעלי חיים אסייתיים לאוסטרליים","אוכלוסייה ושיאים","על שם אלפרד ראסל וולאס, שהגה את תורת האבולוציה במקביל לדרווין. הקו עובר במיצר צר באינדונזיה, בין האיים באלי ולומבוק.",["איך נקרא הקו המדומה שמפריד בין בעלי החיים של אסיה לאלה של אוסטרליה?","קו וואלאס"]]]},t={id:"israel-leaders",name:"מנהיגי ישראל",description:"כל ראשי הממשלה, כל הנשיאים, והרמטכ״לים של האירועים הגדולים. אין כאן מאה כרטיסיות — כי אין מאה מנהיגים.",cards:[["מי היה ראש הממשלה הראשון של ישראל?","דוד בן-גוריון","ראשי ממשלה",'נולד בשם דוד גרין בפלונסק שבפולין. את השם "בן-גוריון" אימץ ב-1910, על שם יוסף בן גוריון — ממנהיגי המרד הגדול ברומאים.',null],["מי היה ראש הממשלה בשנים 1948–1954?","דוד בן-גוריון","ראשי ממשלה","בסוף 1953 פרש ועבר לצריף בקיבוץ שדה בוקר שבנגב — כדי לתת דוגמה אישית להתיישבות בדרום. משה שרת החליף אותו.",["באילו שנים כיהן דוד בן-גוריון כראש הממשלה בקדנציה הראשונה שלו?","1948–1954"]],["מי היה ראש הממשלה בשנים 1954–1955?","משה שרת","ראשי ממשלה","נולד בשם משה שרתוק. לפני כן היה שר החוץ הראשון של ישראל — דיפלומט זהיר, שהתנגש לא פעם עם הקו התקיף של בן-גוריון.",["באילו שנים כיהן משה שרת כראש הממשלה?","1954–1955"]],["מי היה ראש הממשלה בשנים 1955–1963?","דוד בן-גוריון","ראשי ממשלה","חזר משדה בוקר לשלטון. בקדנציה הזאת יצאה ישראל למבצע קדש (1956) והעמידה לדין את אדולף אייכמן. ב-1963 התפטר סופית.",["באילו שנים כיהן דוד בן-גוריון כראש הממשלה בקדנציה השנייה שלו?","1955–1963"]],["מי היה ראש הממשלה בשנים 1963–1969?","לוי אשכול","ראשי ממשלה","נולד בשם לוי שקולניק. ערב מלחמת ששת הימים, תחת לחץ ציבורי, הקים ממשלת אחדות לאומית ומינה את משה דיין לשר הביטחון.",["באילו שנים כיהן לוי אשכול כראש הממשלה?","1963–1969"]],["מי היה ראש הממשלה בשנים 1969–1974?","גולדה מאיר","ראשי ממשלה","נולדה בקייב בשם גולדה מבוביץ וגדלה במילווקי שבארצות הברית. התפטרה ב-1974, בעקבות המחאה שאחרי מלחמת יום הכיפורים.",["באילו שנים כיהנה גולדה מאיר כראש הממשלה?","1969–1974"]],["מי היה ראש הממשלה בשנים 1974–1977?","יצחק רבין","ראשי ממשלה","ראש הממשלה הראשון שנולד בארץ — בירושלים, ב-1922. בקדנציה הזאת אושר מבצע אנטבה, והיא נגמרה בפרשת חשבון הדולרים של אשתו לאה.",["באילו שנים כיהן יצחק רבין כראש הממשלה בקדנציה הראשונה שלו?","1974–1977"]],["מי היה ראש הממשלה בשנים 1977–1983?","מנחם בגין","ראשי ממשלה",'חתם על השלום עם מצרים וקיבל עם סאדאת את פרס נובל לשלום. אחרי מלחמת לבנון ומות אשתו עליזה התפטר, במילים "אינני יכול עוד".',["באילו שנים כיהן מנחם בגין כראש הממשלה?","1977–1983"]],["מי היה ראש הממשלה בשנים 1983–1984?","יצחק שמיר","ראשי ממשלה","לפני הפוליטיקה היה ממפקדי הלח״י במחתרת, ואחר כך איש המוסד. נכנס לתפקיד כשבגין פרש.",["באילו שנים כיהן יצחק שמיר כראש הממשלה בקדנציה הראשונה שלו?","1983–1984"]],["מי היה ראש הממשלה בשנים 1984–1986?","שמעון פרס","ראשי ממשלה","ממשלת אחדות ברוטציה: פרס כיהן שנתיים ואז העביר את התפקיד לשמיר. בתקופתו נבלמה אינפלציה של מאות אחוזים בשנה, בתוכנית הייצוב של 1985.",["באילו שנים כיהן שמעון פרס כראש הממשלה בקדנציה הראשונה שלו?","1984–1986"]],["מי היה ראש הממשלה בשנים 1986–1992?","יצחק שמיר","ראשי ממשלה","קיבל את התפקיד ברוטציה מפרס. בתקופתו פרצה האינתיפאדה הראשונה, ובמלחמת המפרץ (1991) החליט לא להגיב לטילים שנורו מעיראק.",["באילו שנים כיהן יצחק שמיר כראש הממשלה בקדנציה השנייה שלו?","1986–1992"]],["מי היה ראש הממשלה בשנים 1992–1995?","יצחק רבין","ראשי ממשלה","בקדנציה הזאת נחתמו הסכמי אוסלו (1993) והשלום עם ירדן (1994), ורבין קיבל את פרס נובל לשלום.",["באילו שנים כיהן יצחק רבין כראש הממשלה בקדנציה השנייה שלו?","1992–1995"]],["מי היה ראש הממשלה בשנים 1995–1996?","שמעון פרס","ראשי ממשלה","נכנס לתפקיד אחרי רצח רבין, והפסיד לנתניהו בבחירות 1996 — הראשונות שבהן נבחר ראש הממשלה בבחירה ישירה — בהפרש של פחות מאחוז.",["באילו שנים כיהן שמעון פרס כראש הממשלה בקדנציה השנייה שלו?","1995–1996"]],["מי היה ראש הממשלה בשנים 1996–1999?","בנימין נתניהו","ראשי ממשלה","נבחר בגיל 46 — ראש הממשלה הצעיר ביותר בתולדות ישראל, והראשון שנולד אחרי קום המדינה (1949).",["באילו שנים כיהן בנימין נתניהו כראש הממשלה בקדנציה הראשונה שלו?","1996–1999"]],["מי היה ראש הממשלה בשנים 1999–2001?","אהוד ברק","ראשי ממשלה","החייל המעוטר ביותר בתולדות צה״ל. בתקופתו יצא צה״ל מדרום לבנון (2000), ופסגת קמפ דיוויד עם ערפאת נכשלה.",["באילו שנים כיהן אהוד ברק כראש הממשלה?","1999–2001"]],["מי היה ראש הממשלה בשנים 2001–2006?","אריאל שרון","ראשי ממשלה","הוביל את ההתנתקות מגוש קטיף (2005) והקים את מפלגת קדימה. בינואר 2006 לקה בשבץ ונכנס לתרדמת, שממנה לא התעורר עד מותו ב-2014.",["באילו שנים כיהן אריאל שרון כראש הממשלה?","2001–2006"]],["מי היה ראש הממשלה בשנים 2006–2009?","אהוד אולמרט","ראשי ממשלה","לפני כן היה ראש עיריית ירושלים. בתקופתו פרצה מלחמת לבנון השנייה, ואחרי פרישתו הורשע בשוחד — ראש הממשלה לשעבר הראשון שישב בכלא.",["באילו שנים כיהן אהוד אולמרט כראש הממשלה?","2006–2009"]],["מי היה ראש הממשלה בשנים 2009–2021?","בנימין נתניהו","ראשי ממשלה","שתים-עשרה שנים ברציפות — הכהונה הרצופה הארוכה ביותר בתולדות ישראל. היא הסתיימה כשקמה ממשלת בנט-לפיד.",["באילו שנים כיהן בנימין נתניהו ברציפות, בקדנציה הארוכה שלו?","2009–2021"]],["מי היה ראש הממשלה בשנים 2021–2022?","נפתלי בנט","ראשי ממשלה","עמד בראש ממשלת רוטציה עם יאיר לפיד, של שמונה מפלגות — ובהן, לראשונה, מפלגה ערבית עצמאית (רע״ם) כחלק מהקואליציה.",["באילו שנים כיהן נפתלי בנט כראש הממשלה?","2021–2022"]],["מי היה ראש הממשלה ב-2022, לפני נתניהו?","יאיר לפיד","ראשי ממשלה","נכנס לתפקיד ביולי 2022 לפי הסכם הרוטציה, כשממשלת בנט התפרקה. לפני הפוליטיקה היה עיתונאי ומגיש טלוויזיה, ובנו של השר טומי לפיד.",["מתי כיהן יאיר לפיד כראש הממשלה?","ב-2022, כחצי שנה — עד שנתניהו חזר"]],["מי הייתה ראש הממשלה היחידה בישראל?","גולדה מאיר","ראשי ממשלה","היא הייתה השלישית בעולם שכיהנה כראש ממשלה, אחרי סירימאוו בנדרנאיקה מציילון (היום סרי לנקה) ואינדירה גנדי מהודו.",null],["מי כיהן הכי הרבה שנים כראש ממשלה?","בנימין נתניהו","ראשי ממשלה","ביולי 2019 עקף את השיא של בן-גוריון. הכהונות שלו נפרשות על שלוש תקופות: 1996–1999, 2009–2021, ושוב מסוף 2022.",null],["איזה ראש ממשלה נרצח בתפקידו?","יצחק רבין, ב-1995","ראשי ממשלה","נרצח ב-4 בנובמבר 1995 בסוף עצרת שלום בכיכר מלכי ישראל בתל אביב, בידי יגאל עמיר. הכיכר נקראת היום כיכר רבין.",["כיצד הסתיימה הקדנציה השנייה של יצחק רבין?","ברצח — בנובמבר 1995"]],["איזה ראש ממשלה מת בתפקידו?","לוי אשכול, ב-1969","ראשי ממשלה","נפטר מהתקף לב בפברואר 1969. אריאל שרון לא מת בתפקיד: הוא לקה בשבץ ב-2006, אהוד אולמרט מילא את מקומו, ושרון נפטר רק ב-2014.",["כיצד הסתיימה כהונתו של לוי אשכול?","הוא מת בתפקיד, מהתקף לב, ב-1969"]],["מי היה ראש הממשלה הראשון שלא ממפא״י/העבודה?","מנחם בגין — המהפך, 1977","ראשי ממשלה",'29 שנים שלטה מפא״י, ואחריה מפלגת העבודה, ברציפות. בליל הבחירות הכריז המגיש חיים יבין בשידור על "מהפך" — והמילה נשארה.',null],["מי היה נשיא ישראל הראשון?","חיים ויצמן","נשיאים","כימאי בכיר: במלחמת העולם הראשונה פיתח בבריטניה תהליך לייצור אצטון לתחמושת. מכון ויצמן ברחובות נקרא על שמו.",["באיזה תפקיד כיהן חיים ויצמן במדינת ישראל?","נשיא המדינה הראשון (1949–1952)"]],["מי היה נשיא ישראל בשנים 1952–1963?","יצחק בן-צבי","נשיאים","כיהן שלוש קדנציות, עד מותו — הנשיא שכיהן הכי הרבה זמן. גם כנשיא המשיך לגור בצריף עץ צנוע בשכונת רחביה בירושלים.",["באילו שנים כיהן יצחק בן-צבי כנשיא המדינה?","1952–1963"]],["מי היה נשיא ישראל בשנים 1963–1973?","זלמן שזר","נשיאים",'סופר, עיתונאי והיסטוריון. השם "שזר" הוא ראשי התיבות של שמו המקורי — שניאור זלמן רובשוב.',["באילו שנים כיהן זלמן שזר כנשיא המדינה?","1963–1973"]],["מי היה נשיא ישראל בשנים 1973–1978?","אפרים קציר","נשיאים","מדען — ביופיזיקאי ממכון ויצמן וחתן פרס ישראל. אחיו, אהרן קציר, היה גם הוא מדען בכיר, ונרצח בפיגוע בנמל התעופה לוד ב-1972.",["באילו שנים כיהן אפרים קציר כנשיא המדינה?","1973–1978"]],["מי היה נשיא ישראל בשנים 1978–1983?","יצחק נבון","נשיאים",'הנשיא הראשון ממוצא ספרדי, יליד ירושלים. כתב את המחזה המוזיקלי "בוסתן ספרדי", שהעלה לבמה את תרבות הלדינו.',["באילו שנים כיהן יצחק נבון כנשיא המדינה?","1978–1983"]],["מי היה נשיא ישראל בשנים 1983–1993?","חיים הרצוג","נשיאים","נולד בבלפסט שבאירלנד. כשגריר באו״ם קרע מעל הדוכן את ההחלטה שהשוותה בין ציונות לגזענות (1975).",["באילו שנים כיהן חיים הרצוג כנשיא המדינה?","1983–1993"]],["מי היה נשיא ישראל בשנים 1993–2000?","עזר ויצמן","נשיאים","אחיינו של חיים ויצמן, הנשיא הראשון. טייס קרב ומפקד חיל האוויר, שבנה את החיל שהכריע את מלחמת ששת הימים.",["באילו שנים כיהן עזר ויצמן כנשיא המדינה?","1993–2000"]],["מי היה נשיא ישראל בשנים 2000–2007?","משה קצב","נשיאים","ניצח את שמעון פרס בהצבעה בכנסת — הפתעה גדולה. סיים את כהונתו בהתפטרות, ואחר כך הורשע באונס וישב בכלא.",["באילו שנים כיהן משה קצב כנשיא המדינה?","2000–2007"]],["מי היה נשיא ישראל בשנים 2007–2014?","שמעון פרס","נשיאים","נבחר בגיל 83 וסיים את הכהונה בגיל 90. בדרך כיהן כמעט בכל תפקיד בכיר: ראש ממשלה, שר החוץ, שר הביטחון ושר האוצר.",["באילו שנים כיהן שמעון פרס כנשיא המדינה?","2007–2014"]],["מי היה נשיא ישראל בשנים 2014–2021?","ראובן ריבלין","נשיאים",'ירושלמי מדור שביעי, ממשפחה שהגיעה לירושלים בתחילת המאה ה-19. מוכר בכינוי "רובי", ואוהד מושבע של בית״ר ירושלים.',["באילו שנים כיהן ראובן ריבלין כנשיא המדינה?","2014–2021"]],["מי נשיא ישראל מ-2021?","יצחק הרצוג","נשיאים","הנשיא ה-11. לפני כן היה יו״ר האופוזיציה בכנסת, ואחר כך יו״ר הסוכנות היהודית.",["מאיזו שנה מכהן יצחק הרצוג כנשיא המדינה?","2021"]],["מי כיהן גם כראש ממשלה וגם כנשיא?","שמעון פרס","נשיאים","היחיד שמילא את שני התפקידים. גם בכנסת הוא שיאן: כמעט חמישים שנה כחבר כנסת, מ-1959 ועד 2007.",null],["איזה נשיא היה בנו של נשיא קודם?","יצחק הרצוג, בנו של חיים הרצוג","נשיאים","ושלושה דורות: הסב, הרב יצחק הלוי הרצוג, היה הרב הראשי האשכנזי הראשון של מדינת ישראל.",["מה הקשר המשפחתי בין הנשיאים חיים הרצוג ויצחק הרצוג?","אב ובנו — יצחק הוא בנו של חיים"]],["מי היה הרמטכ״ל הראשון של צה״ל?","יעקב דורי","רמטכ״לים","חלה במהלך מלחמת העצמאות, ויגאל ידין, ראש אגף המבצעים, ניהל את הלחימה בפועל. אחרי השירות היה נשיא הטכניון.",["איזה תפקיד צבאי מילא יעקב דורי ראשון בתולדות צה״ל?","הרמטכ״ל הראשון"]],["מי היה הרמטכ״ל השני, וידוע כארכיאולוג?","יגאל ידין","רמטכ״לים","ניהל את החפירות הגדולות במצדה (1963–1965) וחקר את המגילות הגנוזות — שאביו, אלעזר סוקניק, רכש את הראשונות שבהן.",["במה התפרסם יגאל ידין אחרי שסיים להיות הרמטכ״ל השני?","כארכיאולוג — בחפירות מצדה ובחקר המגילות הגנוזות"]],["מי היה הרמטכ״ל במבצע קדש (1956)?","משה דיין","רמטכ״לים","הרטייה המפורסמת — מפציעה ב-1941 בלבנון, כשכדור פגע במשקפת שדרכה הביט, במבצע עם הבריטים נגד צרפת של וישי.",["באיזה מבצע של 1956 פיקד משה דיין כרמטכ״ל?","מבצע קדש"]],["מי היה הרמטכ״ל במלחמת ששת הימים?","יצחק רבין","רמטכ״לים","אחרי המלחמה קיבל תואר דוקטור של כבוד מהאוניברסיטה העברית, ובנאומו על הר הצופים זקף את הניצחון ללוחמים ולא למפקדים.",["באיזו מלחמה היה יצחק רבין הרמטכ״ל?","מלחמת ששת הימים (1967)"]],["מי היה הרמטכ״ל במלחמת ההתשה?","חיים בר-לב","רמטכ״לים",'על שמו נקרא "קו בר-לב" — שרשרת המעוזים לאורך תעלת סואץ, שנפרצה בהתקפה המצרית ביום כיפור 1973.',["באיזו מלחמה היה חיים בר-לב הרמטכ״ל?","מלחמת ההתשה"]],["מי היה הרמטכ״ל במלחמת יום הכיפורים?","דוד אלעזר","רמטכ״לים",'כולם קראו לו "דדו". ועדת אגרנט המליצה על סיום כהונתו והוא התפטר; כעבור שנתיים מת מהתקף לב, בגיל 50.',["באיזו מלחמה היה דוד (דדו) אלעזר הרמטכ״ל?","מלחמת יום הכיפורים (1973)"]],["מי היה הרמטכ״ל במבצע אנטבה?","מרדכי (מוטה) גור","רמטכ״לים",'כמפקד חטיבת הצנחנים במלחמת ששת הימים הוא שאמר בקשר "הר הבית בידינו" — המשפט המזוהה ביותר עם כיבוש העיר העתיקה.',["איזה מבצע חילוץ מפורסם התרחש ב-1976, כשמוטה גור היה הרמטכ״ל?","מבצע אנטבה"]],["מי היה הרמטכ״ל במלחמת לבנון הראשונה?","רפאל (רפול) איתן","רמטכ״לים","נגר במקצועו, ואיש מושב תל עדשים. אחרי השירות הקים את מפלגת צומת וכיהן כשר החקלאות.",["באיזו מלחמה היה רפול איתן הרמטכ״ל?","מלחמת לבנון הראשונה (1982)"]],["מי היה הרמטכ״ל באינתיפאדה הראשונה?","דן שומרון","רמטכ״לים","לפני כן פיקד על הכוח שנחת באנטבה ב-1976. האינתיפאדה פרצה בדצמבר 1987, אחרי תאונת דרכים ברצועת עזה.",["איזו התקוממות פלסטינית פרצה ב-1987, כשדן שומרון היה הרמטכ״ל?","האינתיפאדה הראשונה"]],["מי היה הרמטכ״ל במלחמת המפרץ (1991)?","דן שומרון","רמטכ״לים","39 טילי סקאד נורו מעיראק על ישראל, וישראל לא הגיבה — לבקשת ארצות הברית, ששמרה על הקואליציה שלה נגד סדאם חוסיין.",["באיזו מלחמה ב-1991 ספגה ישראל טילים מעיראק, כשדן שומרון היה הרמטכ״ל?","מלחמת המפרץ"]],["איזה רמטכ״ל הפך אחר כך לראש ממשלה?","יצחק רבין, ואהוד ברק","רמטכ״לים","רמטכ״לים רבים נכנסו לפוליטיקה — דיין, בר-לב, רפול, מופז, יעלון, אשכנזי, גנץ ואיזנקוט — אבל רק שניים הגיעו לראשות הממשלה.",["מה המשותף לקריירות של יצחק רבין ושל אהוד ברק?","שניהם היו רמטכ״לים, ואחר כך ראשי ממשלה"]],["מי היה הרמטכ״ל שאחרי דן שומרון?","אהוד ברק","רמטכ״לים",'כמפקד סיירת מטכ״ל הוביל את שחרור מטוס סבנה (1972) ואת מבצע "אביב נעורים" בביירות (1973), שבו התחפש לאישה.',["את מי החליף אהוד ברק כרמטכ״ל, ב-1991?","את דן שומרון"]],["מי היה הרמטכ״ל בשנים 1995–1998?","אמנון ליפקין-שחק","רמטכ״לים",'לפני כן היה ראש אמ״ן. כקצין צעיר השתתף במבצע "אביב נעורים" בביירות, ואחרי השירות היה שר בממשלת ברק.',["באילו שנים כיהן אמנון ליפקין-שחק כרמטכ״ל?","1995–1998"]],["מי היה הרמטכ״ל בפרוץ האינתיפאדה השנייה?","שאול מופז","רמטכ״לים","נולד בטהרן ועלה בגיל תשע. אחרי השירות היה שר הביטחון, ובהמשך יו״ר מפלגת קדימה.",["איזו התקוממות פרצה בספטמבר 2000, כששאול מופז היה הרמטכ״ל?","האינתיפאדה השנייה"]],["מי היה הרמטכ״ל במבצע חומת מגן?","שאול מופז","רמטכ״לים","המבצע יצא לדרך בסוף מרץ 2002, יומיים אחרי פיגוע ליל הסדר במלון פארק בנתניה, וכלל כניסה לערים הגדולות בגדה.",["איזה מבצע גדול ביהודה ושומרון ניהל צה״ל ב-2002, כששאול מופז היה הרמטכ״ל?","מבצע חומת מגן"]],["מי היה הרמטכ״ל בשנים 2002–2005?","משה (בוגי) יעלון","רמטכ״לים","כהונתו לא הוארכה, בין השאר בגלל התנגדותו לתוכנית ההתנתקות. את ההתנתקות עצמה (אוגוסט 2005) כבר ניהל מחליפו, דן חלוץ.",["באילו שנים כיהן משה (בוגי) יעלון כרמטכ״ל?","2002–2005"]],["מי היה הרמטכ״ל במלחמת לבנון השנייה?","דן חלוץ","רמטכ״לים","הרמטכ״ל הראשון שבא מחיל האוויר — טייס קרב ומפקד החיל. התפטר בינואר 2007, בעקבות הביקורת על ניהול המלחמה.",["באיזו מלחמה היה דן חלוץ הרמטכ״ל?","מלחמת לבנון השנייה (2006)"]],["מי היה הרמטכ״ל במבצע עופרת יצוקה?","גבי אשכנזי","רמטכ״לים","נכנס לתפקיד אחרי מלחמת לבנון השנייה, כדי לשקם את הצבא. אחרי השירות כיהן כשר החוץ (2020–2021).",["איזה מבצע בעזה ניהל גבי אשכנזי כרמטכ״ל, בחורף 2008–2009?","מבצע עופרת יצוקה"]],["מי היה הרמטכ״ל במבצע צוק איתן?","בני גנץ","רמטכ״לים","צוק איתן נמשך 50 יום — המבצע הארוך ביותר בעזה עד אז. אחרי השירות הקים את מפלגת חוסן לישראל וכיהן כשר הביטחון.",["איזה מבצע בעזה ניהל בני גנץ כרמטכ״ל, בקיץ 2014?","מבצע צוק איתן"]],["מי היה הרמטכ״ל בשנים 2015–2019?","גדי איזנקוט","רמטכ״לים",'ידוע ב"דוקטרינת דאחייה" — תגובה עוצמתית על תשתיות האויב — שניסח כאלוף פיקוד הצפון. נולד בטבריה וגדל באילת.',["באילו שנים כיהן גדי איזנקוט כרמטכ״ל?","2015–2019"]],["מי היה הרמטכ״ל בשנים 2019–2023?","אביב כוכבי","רמטכ״לים",'בתקופתו התנהל מבצע "שומר החומות" בעזה (2021). בעל תואר ראשון בפילוסופיה, ונחשב לאחד הרמטכ״לים האינטלקטואלים.',["באילו שנים כיהן אביב כוכבי כרמטכ״ל?","2019–2023"]],["מי הרמטכ״ל שנכנס לתפקיד בינואר 2023?","הרצי הלוי","רמטכ״לים","היה הרמטכ״ל בטבח 7 באוקטובר 2023 ובמלחמה שאחריו. נטל אחריות על כישלון הצבא והתפטר; אייל זמיר החליף אותו במרץ 2025.",["מתי נכנס הרצי הלוי לתפקיד הרמטכ״ל?","בינואר 2023"]],["מי היה הרמטכ״ל הראשון שנולד בישראל?","יגאל ידין","רמטכ״לים","נולד בירושלים ב-1917. רבים חושבים שזה משה דיין, יליד דגניה — אבל דיין היה הרמטכ״ל הרביעי, וידין, השני, קדם לו.",null]]},i={id:"israel-history",name:"היסטוריה של ישראל",description:"אירועים, תאריכים ומושגים — מהצהרת בלפור ועד ההסכמים האחרונים. השאלות מנוסחות כך שיש להן תשובה אחת ברורה.",cards:[["מתי פורסמה הצהרת בלפור?","1917","לפני המדינה","2 בנובמבר 1917: מכתב של 67 מילים בלבד, ששלח שר החוץ הבריטי ללורד רוטשילד. כעבור חודש כבשו הבריטים את ירושלים.",["איזו הצהרה בריטית מ-1917 תמכה בהקמת בית לאומי לעם היהודי בארץ ישראל?","הצהרת בלפור"]],["מי חתם על הצהרת בלפור?","ארתור ג׳יימס בלפור, שר החוץ הבריטי","לפני המדינה","לפני כן היה ראש ממשלת בריטניה. ב-1925 הגיע לטקס הפתיחה של האוניברסיטה העברית בהר הצופים.",["איזה מסמך היסטורי נושא את שמו של שר החוץ הבריטי ארתור ג׳יימס בלפור?","הצהרת בלפור"]],["מתי התקיים הקונגרס הציוני הראשון?","1897, בבאזל","לפני המדינה",'הרצל כתב ביומנו: "בבאזל ייסדתי את מדינת היהודים", וניבא שבתוך חמישים שנה כולם יכירו בכך. המדינה קמה כעבור 51 שנה.',["מה התקיים בבאזל ב-1897?","הקונגרס הציוני הראשון"]],["מי כינס את הקונגרס הציוני הראשון?","בנימין זאב הרצל","לפני המדינה","הרצל היה עיתונאי וינאי. לפי הגרסה המקובלת, משפט דרייפוס בפריז (1894), שסיקר כעיתונאי, שכנע אותו שהפתרון לבעיית היהודים הוא מדינה.",["איזה כינוס היסטורי כינס בנימין זאב הרצל ב-1897?","הקונגרס הציוני הראשון, בבאזל"]],["איזה ספר כתב הרצל ב-1896?","מדינת היהודים","לפני המדינה","בגרמנית: Der Judenstaat. ספר מעשי, כמעט תוכנית עבודה: איך מקימים גוף שינהל את ההגירה ואת הקמת המדינה.",['מתי פרסם הרצל את "מדינת היהודים"?',"1896"]],["מהו הספר האוטופי שכתב הרצל ב-1902?","אלטנוילנד","לפני המדינה",'פירוש השם: "ארץ ישנה-חדשה". נחום סוקולוב תרגם אותו לעברית בשם "תל אביב" — ומשם נלקח שמה של העיר.',['מתי פרסם הרצל את הרומן האוטופי "אלטנוילנד"?',"1902"]],["מתי החל המנדט הבריטי בארץ ישראל?","1920","לפני המדינה","הוחלט עליו בוועידת סן רמו (1920) ואושר בחבר הלאומים ב-1922. הנציב העליון הראשון היה יהודי — הרברט סמואל.",["מה החל בארץ ישראל ב-1920, אחרי ועידת סן רמו?","המנדט הבריטי"]],["מתי פורסם הספר הלבן שהגביל את העלייה?","1939","לפני המדינה",'הגביל את העלייה ל-75 אלף איש בחמש שנים — ערב השואה. בן-גוריון הגיב: "נילחם בהיטלר כאילו אין ספר לבן, ונילחם בספר הלבן כאילו אין היטלר".',["איזה מסמך בריטי מ-1939 הגביל את העלייה לארץ ישראל?","הספר הלבן (של מקדונלד)"]],["מתי אישר האו״ם את תוכנית החלוקה?","29 בנובמבר 1947","הקמה ומלחמות","33 מדינות הצביעו בעד, 13 נגד ו-10 נמנעו. היישוב היהודי, שהאזין לשידור ברדיו, יצא לרקוד ברחובות — ולמחרת פרצה מלחמה.",["מה אישרה עצרת האו״ם ב-29 בנובמבר 1947?","את תוכנית החלוקה"]],["מתי הוכרזה מדינת ישראל?","14 במאי 1948 — ה׳ באייר תש״ח","הקמה ומלחמות","הטקס נקבע ליום שישי אחר הצהריים ונמשך כ-32 דקות — כדי להסתיים לפני כניסת השבת, ולפני סיום המנדט בחצות.",["מה הוכרז ב-14 במאי 1948?","הקמת מדינת ישראל"]],["היכן הוכרזה מדינת ישראל?","מוזיאון תל אביב, שדרות רוטשילד","הקמה ומלחמות","הבניין הוא בית דיזנגוף — ביתו של ראש העירייה הראשון של תל אביב, מאיר דיזנגוף, שתרם אותו למוזיאון. היום הוא נקרא היכל העצמאות.",["איזה אירוע היסטורי התקיים בבית דיזנגוף שבשדרות רוטשילד בתל אביב?","הכרזת המדינה"]],["מי הקריא את מגילת העצמאות?","דוד בן-גוריון","הקמה ומלחמות",'37 איש חתמו על המגילה. השם "ישראל" נבחר רק יומיים קודם; הוצעו גם שמות כמו "ציון" ו"יהודה".',["איזה מסמך הקריא דוד בן-גוריון ב-14 במאי 1948?","את מגילת העצמאות"]],["מה שמה של מלחמת 1948?","מלחמת העצמאות","הקמה ומלחמות",'המלחמה הקשה בתולדות ישראל: כ-6,000 הרוגים — כאחוז מהאוכלוסייה היהודית. היא נקראת גם "מלחמת הקוממיות" ו"מלחמת השחרור".',["מתי התחוללה מלחמת העצמאות?","מנובמבר 1947 ועד 1949"]],["מתי הצטרפה ישראל לאו״ם?","1949","הקמה ומלחמות","ישראל התקבלה ב-11 במאי 1949, כחברה ה-59 בארגון — שנה אחרי הקמתה.",["לאיזה ארגון בינלאומי התקבלה ישראל ב-1949?","לאו״ם"]],["מהו חוק השבות?","חוק המקנה לכל יהודי זכות לעלות לישראל — 1950","הקמה ומלחמות","נחקק ב-5 ביולי 1950, כ׳ בתמוז — יום פטירתו של הרצל לפי הלוח העברי. ב-1970 הורחב גם לילדים ולנכדים של יהודים.",["איזה חוק משנת 1950 מקנה לכל יהודי זכות לעלות לישראל?","חוק השבות"]],["מתי הועבר משפט אייכמן?","1961","הקמה ומלחמות","אייכמן נחטף בארגנטינה ב-1960 בידי המוסד. במשפט, ששודר ברדיו, סיפרו ניצולים רבים את סיפורם בפומבי לראשונה. הוא הוצא להורג ב-1962.",["איזה משפט היסטורי התנהל בירושלים ב-1961?","משפט אייכמן"]],["מתי התרחש מבצע קדש?","1956","הקמה ומלחמות","ישראל פעלה בתיאום עם בריטניה וצרפת, שרצו להחזיר לעצמן את תעלת סואץ. צה״ל כבש את סיני בתוך כשבוע — ונסוג בלחץ ארה״ב וברית המועצות.",["איזה מבצע צבאי ערכה ישראל בסיני ב-1956?","מבצע קדש"]],["כיצד נקראת מלחמת 1967?","מלחמת ששת הימים","הקמה ומלחמות",'המלחמה נפתחה ב-5 ביוני 1967 במבצע "מוקד", שבו השמיד חיל האוויר את רוב חיל האוויר המצרי על הקרקע, בתוך שעות.',["באיזו שנה הייתה מלחמת ששת הימים?","1967"]],["אילו שטחים נכבשו במלחמת ששת הימים?","סיני, רצועת עזה, יהודה ושומרון, מזרח ירושלים ורמת הגולן","הקמה ומלחמות","סיני לבדו גדול כמעט פי שלושה מישראל שלפני המלחמה. הוא הוחזר למצרים בהסכם השלום, ומרצועת עזה יצאה ישראל ב-2005.",["באיזו מלחמה כבשה ישראל את סיני, הגדה, מזרח ירושלים ורמת הגולן?","מלחמת ששת הימים"]],["מתי פרצה מלחמת יום הכיפורים?","6 באוקטובר 1973","הקמה ומלחמות","מצרים וסוריה תקפו יחד ביום הכיפורים בשעה 14:00, כשרוב המילואים עוד לא גויסו. כ-2,700 חיילים נהרגו.",["איזו מלחמה פרצה ב-6 באוקטובר 1973?","מלחמת יום הכיפורים"]],["מהי ועדת אגרנט?","ועדת החקירה על המחדל במלחמת יום הכיפורים","הקמה ומלחמות","בראשה עמד נשיא בית המשפט העליון, שמעון אגרנט. הדוח הביא להתפטרות הרמטכ״ל דדו אלעזר, ובעקבות המחאה גם להתפטרות גולדה מאיר.",["איך נקראה ועדת החקירה על המחדל במלחמת יום הכיפורים?","ועדת אגרנט"]],["מתי בוצע מבצע אנטבה?","4 ביולי 1976","הקמה ומלחמות",'102 בני ערובה חולצו מנמל התעופה באוגנדה, כ-4,000 קילומטר מישראל. השם הרשמי היה "כדור הרעם", ואחר כך שונה ל"מבצע יונתן".',["איזה מבצע חילוץ בוצע באוגנדה ביולי 1976?","מבצע אנטבה"]],["מי נהרג בפיקוד על מבצע אנטבה?","יונתן (יוני) נתניהו","הקמה ומלחמות","יוני, מפקד סיירת מטכ״ל, היה הלוחם היחיד שנהרג במבצע. אחיו הצעיר הוא בנימין נתניהו.",["באיזה מבצע נהרג יוני נתניהו, מפקד סיירת מטכ״ל?","מבצע אנטבה (1976)"]],["מהו המהפך של 1977?","עליית הליכוד לשלטון לראשונה","הסכמים ותהליכים","אחרי 29 שנות שלטון של מפא״י והעבודה. ברקע: מלחמת יום הכיפורים, פרשות שחיתות, ותחושת קיפוח של רבים מיוצאי ארצות המזרח.",["איך נקראה עליית הליכוד לשלטון לראשונה, ב-1977?","המהפך"]],["מתי ביקר סאדאת בישראל?","נובמבר 1977","הסכמים ותהליכים",'לראשונה מנהיג ערבי נחת בישראל ונאם בכנסת. עשרה ימים קודם הכריז בפרלמנט המצרי שהוא מוכן להגיע "עד קצה העולם" — אפילו לכנסת.',["איזה מנהיג ערבי ביקר בישראל בנובמבר 1977 ונאם בכנסת?","נשיא מצרים, אנואר סאדאת"]],["מתי נחתם הסכם השלום עם מצרים?","1979","הסכמים ותהליכים","ישראל החזירה את כל חצי האי סיני, כולל פינוי העיר ימית ב-1982. השלום הקר הזה מחזיק כבר יותר מארבעה עשורים.",["עם איזו מדינה חתמה ישראל על הסכם שלום ב-1979?","מצרים"]],["מי חתמו על הסכם השלום עם מצרים?","מנחם בגין ואנואר סאדאת","הסכמים ותהליכים","החתימה התקיימה על מדשאת הבית הלבן, עם הנשיא ג׳ימי קרטר. ב-1981 נרצח סאדאת בידי קיצונים איסלאמיסטים, בין השאר בגלל השלום.",["על איזה הסכם חתמו מנחם בגין ואנואר סאדאת ב-1979?","הסכם השלום בין ישראל למצרים"]],["מהם הסכמי קמפ דיוויד?","ההסכמים שקדמו לשלום עם מצרים, 1978","הסכמים ותהליכים","13 ימים של משא ומתן סגור באתר הנופש של נשיא ארה״ב, בספטמבר 1978. על ההישג הזה קיבלו בגין וסאדאת את פרס נובל לשלום.",["איך נקראים ההסכמים מ-1978 שקדמו לשלום עם מצרים?","הסכמי קמפ דיוויד"]],["מתי הופצץ הכור הגרעיני בעיראק?","1981 — מבצע אופרה","הסכמים ותהליכים","שמונה מטוסי F-16 טסו בגובה נמוך מעל ירדן וסעודיה והשמידו את הכור ליד בגדד. אחד הטייסים היה אילן רמון — לימים האסטרונאוט הישראלי הראשון.",["מה הפציץ חיל האוויר במבצע אופרה, ב-1981?","את הכור הגרעיני העיראקי"]],["מתי פרצה מלחמת לבנון הראשונה?","1982","הסכמים ותהליכים",'התחילה כמבצע "שלום הגליל", אחרי ניסיון ההתנקשות בשגריר ישראל בלונדון. צה״ל נשאר ברצועת הביטחון בדרום לבנון 18 שנה, עד 2000.',["איזו מלחמה פרצה ביוני 1982?","מלחמת לבנון הראשונה"]],["מתי פרצה האינתיפאדה הראשונה?","1987","הסכמים ותהליכים",'"אינתיפאדה" בערבית פירושה "התנערות". היא נמשכה עד 1993 — עד הסכמי אוסלו.',["איזו התקוממות פלסטינית פרצה בדצמבר 1987?","האינתיפאדה הראשונה"]],["מתי נחתמו הסכמי אוסלו?","1993","הסכמים ותהליכים","נקראים על שם בירת נורווגיה, שבה התנהל המשא ומתן החשאי. לחיצת היד בין רבין לערפאת בבית הלבן הפכה לאחת התמונות המפורסמות של המאה.",["אילו הסכמים בין ישראל לאש״ף נחתמו בבית הלבן ב-1993?","הסכמי אוסלו"]],["מי חתם על הסכם אוסלו הראשון מטעם ישראל?","שר החוץ שמעון פרס","הסכמים ותהליכים","בצד הפלסטיני חתם מחמוד עבאס (אבו מאזן). ראש הממשלה רבין ויו״ר אש״ף ערפאת עמדו לידם — ולחצו ידיים.",["על איזה הסכם היסטורי חתם שמעון פרס בבית הלבן ב-1993?","הסכם אוסלו הראשון (הצהרת העקרונות)"]],["מתי נחתם הסכם השלום עם ירדן?","1994","הסכמים ותהליכים","נחתם בערבה, על גבול שתי המדינות, בין רבין למלך חוסיין. ירדן הייתה המדינה הערבית השנייה, אחרי מצרים, שחתמה על שלום עם ישראל.",["עם איזו מדינה חתמה ישראל על הסכם שלום ב-1994?","ירדן"]],["מי קיבלו את פרס נובל לשלום ב-1994?","רבין, פרס וערפאת","הסכמים ותהליכים","הפרס ניתן על הסכמי אוסלו. ישראלי נוסף שזכה בנובל לשלום: מנחם בגין, ב-1978.",["באיזו שנה קיבלו רבין, פרס וערפאת את פרס נובל לשלום?","1994"]],["מתי נרצח יצחק רבין?","4 בנובמבר 1995","הסכמים ותהליכים",'הרצח קרה בסוף עצרת "כן לשלום, לא לאלימות". בכיסו של רבין נמצא דף מוכתם בדם עם "שיר לשלום", שאותו שר על הבמה דקות קודם.',["מה קרה ב-4 בנובמבר 1995?","רצח ראש הממשלה יצחק רבין"]],["מתי יצאה ישראל מדרום לבנון?","2000","הסכמים ותהליכים",'ראש הממשלה אהוד ברק הוציא את צה״ל במאי 2000, בתוך לילה אחד, אחרי 18 שנה. ברקע פעלה תנועת "ארבע אמהות", שדרשה לצאת.',["מה עשה צה״ל במאי 2000 בגבול הצפון?","יצא מרצועת הביטחון בדרום לבנון"]],["מתי פרצה האינתיפאדה השנייה?","2000","הסכמים ותהליכים",'נקראת גם "אינתיפאדת אל-אקצא": פרצה אחרי ביקור של אריאל שרון בהר הבית בספטמבר 2000, ובאו אחריה שנים של פיגועי התאבדות בערים.',["איזו התקוממות פלסטינית פרצה בספטמבר 2000?","האינתיפאדה השנייה"]],["מהו מבצע חומת מגן?","מבצע צה״ל ביהודה ושומרון, 2002","הסכמים ותהליכים","במרץ 2002 לבדו נהרגו בפיגועים יותר מ-130 ישראלים. במבצע נכנס צה״ל לערי הגדה, וביניהן לקרב הקשה במחנה הפליטים בג׳נין.",["איך נקרא המבצע הגדול של צה״ל ביהודה ושומרון ב-2002?","מבצע חומת מגן"]],["מתי בוצעה ההתנתקות מגוש קטיף?","2005","הסכמים ותהליכים","21 יישובים ברצועת עזה וארבעה בצפון השומרון פונו, ויותר מ-8,000 תושבים עזבו את בתיהם. הפינוי עצמו נמשך כשבוע.",["מה התרחש בגוש קטיף ובצפון השומרון באוגוסט 2005?","ההתנתקות — פינוי היישובים"]],["מתי התרחשה מלחמת לבנון השנייה?","2006","הסכמים ותהליכים","פרצה אחרי שחיזבאללה חטף את החיילים אהוד גולדווסר ואלדד רגב. במשך 34 ימים נורו על הצפון כ-4,000 רקטות.",["איזו מלחמה התחוללה בקיץ 2006 מול חיזבאללה?","מלחמת לבנון השנייה"]],["מהו מבצע עופרת יצוקה?","מבצע בעזה, 2008–2009","הסכמים ותהליכים",'המבצע יצא לדרך בחנוכה, ושמו לקוח משיר החנוכה של ביאליק: "סביבון לי, בן עופרת יציקה".',["איך נקרא המבצע של צה״ל בעזה בחורף 2008–2009?","מבצע עופרת יצוקה"]],["מהו מבצע צוק איתן?","מבצע בעזה, 2014","הסכמים ותהליכים","המבצע בא אחרי חטיפתם ורציחתם של שלושה נערים בגוש עציון. במהלכו השמיד צה״ל עשרות מנהרות תקיפה שחפר חמאס לתוך ישראל.",["איך נקרא המבצע של צה״ל בעזה בקיץ 2014?","מבצע צוק איתן"]],["מהם הסכמי אברהם?","הסכמי נורמליזציה עם איחוד האמירויות ובחריין, 2020","הסכמים ותהליכים","השם על שם אברהם אבינו — אבי היהודים וגם הערבים לפי המסורת. אחריהן הצטרפו גם מרוקו וסודן.",["איך נקראים הסכמי הנורמליזציה מ-2020 עם איחוד האמירויות ובחריין?","הסכמי אברהם"]],["מהי העלייה הראשונה?","גל העלייה בשנים 1882–1903","עליות, מחתרות ומוסדות","עולים ממזרח אירופה ומתימן, שייסדו את המושבות הראשונות — ראשון לציון, זכרון יעקב, ראש פינה. הברון רוטשילד מימן רבות מהן.",["איך נקרא גל העלייה של השנים 1882–1903?","העלייה הראשונה"]],["מהי העלייה השנייה?","גל העלייה בשנים 1904–1914","עליות, מחתרות ומוסדות","עלו בה צעירים סוציאליסטים, וביניהם בן-גוריון וברל כצנלסון. בתקופתה נוסדו תל אביב (1909) ודגניה, הקבוצה הראשונה (1910).",["איך נקרא גל העלייה של השנים 1904–1914?","העלייה השנייה"]],["מהי חומה ומגדל?","שיטת הקמת יישובים מהירה בשנים 1936–1939","עליות, מחתרות ומוסדות","יישוב שלם — גדר, צריפים ומגדל שמירה — הוקם ביום אחד, כדי להעמיד את השלטון הבריטי בפני עובדה מוגמרת. כך קמו כ-50 יישובים.",["איך נקראה שיטת הקמת היישובים המהירה בשנים 1936–1939?","חומה ומגדל"]],["מהו מבצע מרבד הקסמים?","העלאת יהודי תימן, 1949–1950","עליות, מחתרות ומוסדות",'כ-49 אלף יהודים הוטסו מעדן. רבים עלו לראשונה במטוס, וראו בו את "כנפי נשרים" שבספר שמות: "ואשא אתכם על כנפי נשרים".',["איך נקרא המבצע להעלאת יהודי תימן ב-1949–1950?","מבצע מרבד הקסמים"]],["מהו מבצע עזרא ונחמיה?","העלאת יהודי עיראק, 1951–1952","עליות, מחתרות ומוסדות","כ-120 אלף יהודים עזבו את עיראק — קהילה שחיה שם מאז גלות בבל, כ-2,500 שנה. עזרא ונחמיה הם שהובילו את השיבה מבבל.",["איך נקרא המבצע להעלאת יהודי עיראק ב-1951–1952?","מבצע עזרא ונחמיה"]],["מהו מבצע משה?","העלאת יהודי אתיופיה, 1984","עליות, מחתרות ומוסדות","העולים צעדו ברגל לסודן, ואלפים מהם — כ-4,000 לפי ההערכות — מתו בדרך ובמחנות. משם הוטסו בחשאי לישראל.",["איך נקרא המבצע החשאי מ-1984 להעלאת יהודי אתיופיה דרך סודן?","מבצע משה"]],["מהו מבצע שלמה?","העלאת יהודי אתיופיה, 1991","עליות, מחתרות ומוסדות","כ-14 אלף עולים הוטסו בתוך 36 שעות. מטוס ג׳מבו אחד של אל על נשא בטיסה אחת יותר מ-1,000 נוסעים — שיא עולמי.",["איך נקרא המבצע מ-1991 להעלאת יהודי אתיופיה ברכבת אווירית?","מבצע שלמה"]],["מהי ההגנה?","הארגון הצבאי המרכזי של היישוב היהודי","עליות, מחתרות ומוסדות",'נוסדה ב-1920, אחרי מאורעות תר״פ, כדי שהיישוב לא יהיה תלוי בבריטים להגנתו. אחרי קום המדינה הפכה לבסיס של צה״ל — "צבא ההגנה לישראל".',["איך נקרא הארגון הצבאי המרכזי של היישוב היהודי לפני קום המדינה?","ההגנה"]],["מהו האצ״ל?","הארגון הצבאי הלאומי, בפיקוד מנחם בגין","עליות, מחתרות ומוסדות","פרש מההגנה ב-1931 ופעל ברוח האידיאולוגיה של ז׳בוטינסקי. ב-1946 פוצץ את אגף משרדי השלטון הבריטי במלון המלך דוד בירושלים.",["על איזו מחתרת פיקד מנחם בגין?","האצ״ל — הארגון הצבאי הלאומי"]],["מהו הלח״י?","לוחמי חירות ישראל, מחתרת בתקופת המנדט","עליות, מחתרות ומוסדות",'הבריטים כינו אותה "כנופיית שטרן". המייסד פרש מהאצ״ל ב-1940 וסירב להפסיק את המאבק בבריטים גם בזמן המלחמה בנאצים. יצחק שמיר היה ממפקדיה.',["איזו מחתרת ייסד אברהם (יאיר) שטרן?","הלח״י — לוחמי חירות ישראל"]],["מהו הפלמ״ח?","פלוגות המחץ — הזרוע המגויסת של ההגנה","עליות, מחתרות ומוסדות","הוקם ב-1941 בעזרת הבריטים, מחשש לפלישה גרמנית. חבריו שילבו עבודה בקיבוצים עם אימונים, ומתוכם צמחו מפקדים כמו יצחק רבין.",["איך נקראה הזרוע המגויסת של ההגנה?","הפלמ״ח — פלוגות המחץ"]],["מהי פרשת אלטלנה?","הטבעת ספינת נשק של האצ״ל, יוני 1948","עליות, מחתרות ומוסדות",'בן-גוריון הורה להפגיז את הספינה כדי שלא יהיה במדינה צבא שני. 16 מאנשי האצ״ל ו-3 חיילי צה״ל נהרגו. "אלטלנה" היה שם העט של ז׳בוטינסקי.',["איך נקראה ספינת הנשק של האצ״ל שהופגזה מול חוף תל אביב ביוני 1948?","אלטלנה"]],["מהי הכנסת?","בית המחוקקים של ישראל, 120 חברים","עליות, מחתרות ומוסדות",'המספר 120 לקוח מ"הכנסת הגדולה" — המוסד שהנהיג את העם בראשית ימי בית שני, ולפי המסורת ישבו בו 120 חכמים.',["כמה חברים יש בכנסת?","120"]],["מהו אחוז החסימה בישראל?","3.25 אחוזים","עליות, מחתרות ומוסדות","הועלה ל-3.25% ב-2014; בבחירות הראשונות הוא היה אחוז אחד בלבד. מפלגה שעוברת אותו נכנסת לכנסת עם ארבעה מנדטים לפחות.",["איך נקרא הסף של 3.25% מהקולות שמפלגה צריכה לעבור כדי להיכנס לכנסת?","אחוז החסימה"]],["מהו בג״ץ?","בית המשפט העליון בשבתו כבית דין גבוה לצדק","עליות, מחתרות ומוסדות","כל אדם יכול לעתור לבג״ץ ישירות נגד רשות ממשלתית, בלי לעבור קודם בערכאה נמוכה. בניין בית המשפט העליון בירושלים נחנך ב-1992.",["איך נקרא בית המשפט העליון כשהוא דן בעתירות נגד רשויות המדינה?","בג״ץ — בית דין גבוה לצדק"]],["מהם חוקי היסוד?","חוקים בעלי מעמד חוקתי, במקום חוקה כתובה","עליות, מחתרות ומוסדות",'הפשרה נקראת "החלטת הררי" (1950): במקום חוקה אחת, הכנסת תחוקק אותה פרק אחר פרק. חוק היסוד הראשון, "הכנסת", נחקק ב-1958.',["איך נקראים החוקים בעלי המעמד החוקתי, שבאים במקום חוקה כתובה?","חוקי היסוד"]],["מדוע אין לישראל חוקה?","בשל אי-הסכמה על יחסי דת ומדינה בשנותיה הראשונות","עליות, מחתרות ומוסדות","מגילת העצמאות קבעה שחוקה תיכתב עד 1 באוקטובר 1948. החשש ממאבק על דת ומדינה, ומהגבלת כוחה של הכנסת, הוביל לפשרה של חוקי יסוד.",null],["מהי הצהרת העצמאות מבחינה משפטית?","מסמך מכונן, אך אינה חוקה","עליות, מחתרות ומוסדות","בשנים הראשונות קבע בית המשפט שאין לה תוקף מחייב. מאז שנות ה-90 היא מצוטטת הרבה, כי חוק יסוד: כבוד האדם וחירותו מפנה לעקרונותיה.",null],['מיהו מחבר ההמנון "התקווה"?',"נפתלי הרץ אימבר","עליות, מחתרות ומוסדות",'השיר נכתב בשם "תקוותנו", והלחן מבוסס על שיר עם רומני. "התקווה" הפכה להמנון הרשמי בחוק רק ב-2004.',["איזה שיר של נפתלי הרץ אימבר הפך להמנון הלאומי?",'"התקווה"']],["מי עיצב את דגל ישראל?","הדגל אומץ מדגל התנועה הציונית, שעיצב דוד וולפסון","עליות, מחתרות ומוסדות","ההשראה: הטלית — לבנה עם פסים כחולים. וולפסון, לימים יורשו של הרצל בראשות התנועה, הציג את הדגל בקונגרס הציוני הראשון.",["מה עיצב דוד וולפסון לתנועה הציונית?","את הדגל הציוני — לימים דגל ישראל"]],["מהו סמל המדינה?","מנורה בת שבעה קנים בין שני ענפי זית","עליות, מחתרות ומוסדות","המנורה מעוצבת לפי התבליט בשער טיטוס ברומא, שמתאר את ביזת בית המקדש. ענפי הזית לקוחים מחזון זכריה. את הסמל עיצבו האחים שמיר.",["מה מסמלת מנורה בת שבעה קנים בין שני ענפי זית?","את מדינת ישראל — זה סמל המדינה"]],["מתי הוקם צה״ל?","31 במאי 1948","עליות, מחתרות ומוסדות","פקודת הממשלה הזמנית קבעה שצה״ל יהיה הכוח המזוין היחיד במדינה, ואסרה על כל כוח אחר. כעבור שלושה שבועות באה פרשת אלטלנה.",["מה הוקם רשמית ב-31 במאי 1948?","צה״ל — צבא ההגנה לישראל"]],["מהי ירושלים מבחינת החוק הישראלי?","הבירה — לפי חוק יסוד: ירושלים, 1980","עליות, מחתרות ומוסדות",'"ירושלים השלמה והמאוחדת היא בירת ישראל". בעקבות החוק העבירו מדינות רבות את שגרירויותיהן מירושלים לתל אביב.',["איזה חוק יסוד משנת 1980 קובע את מעמדה של ירושלים?","חוק יסוד: ירושלים בירת ישראל"]],["מתי הועברה שגרירות ארה״ב לירושלים?","2018","עליות, מחתרות ומוסדות","ההעברה נקבעה ל-14 במאי 2018 — 70 שנה בדיוק להכרזת המדינה. הקונגרס האמריקאי החליט עליה כבר ב-1995, אבל הנשיאים דחו את הביצוע שוב ושוב.",["מה עשתה ארה״ב במאי 2018, ביום השנה ה-70 להקמת המדינה?","העבירה את שגרירותה לירושלים"]],["מהו קו הירוק?","קו שביתת הנשק מ-1949","עליות, מחתרות ומוסדות","הקו סומן בצבע ירוק על המפות בשיחות שביתת הנשק — ומכאן שמו.",["איך נקרא קו שביתת הנשק מ-1949?","הקו הירוק"]]]},c={id:"science",name:"מושגים במדע",description:"מושגי יסוד מפיזיקה, כימיה, ביולוגיה ואסטרונומיה. הדברים שכולם אמורים לדעת ורובנו שכחנו.",cards:[["מהו אטום?","היחידה הקטנה ביותר של יסוד כימי","כימיה וחומר",'מיוונית atomos — "שאי אפשר לחתוך". דמוקריטוס הגה את הרעיון כבר במאה ה-5 לפנה״ס. היום ידוע שגם האטום מתחלק — לפרוטונים, לנייטרונים ולאלקטרונים.',["איך נקראת היחידה הקטנה ביותר של יסוד כימי?","אטום"]],["ממה מורכב גרעין האטום?","פרוטונים ונייטרונים","כימיה וחומר","הגרעין קטן מהאטום פי כמאה אלף, אבל כמעט כל המסה נמצאת בו. אילו האטום היה בגודל אצטדיון, הגרעין היה בגודל זבוב באמצע המגרש.",["מה יוצרים יחד הפרוטונים והנייטרונים?","את גרעין האטום"]],["מה קובע את זהות היסוד הכימי?","מספר הפרוטונים","כימיה וחומר",'זה "המספר האטומי": למימן יש פרוטון אחד, לפחמן שישה, לזהב 79. שנה אותו — וקיבלת יסוד אחר. בדיוק החלום של האלכימאים.',["מה נקבע לפי מספר הפרוטונים בגרעין?","זהות היסוד הכימי — המספר האטומי שלו"]],["מהו איזוטופ?","אטום של אותו יסוד עם מספר שונה של נייטרונים","כימיה וחומר","מיוונית: iso (שווה) + topos (מקום) — אותו מקום בטבלה המחזורית. האיזוטופ הרדיואקטיבי פחמן-14 משמש לתיארוך ממצאים ארכיאולוגיים.",["איך נקרא אטום של אותו יסוד, עם מספר שונה של נייטרונים?","איזוטופ"]],["מהי מולקולה?","שני אטומים או יותר הקשורים יחד","כימיה וחומר",'מלטינית molecula — "מסה קטנה". מולקולת מים היא שלושה אטומים; מולקולת DNA יכולה להכיל מיליארדי אטומים.',["איך נקראים שני אטומים או יותר הקשורים יחד?","מולקולה"]],["מהו יון?","אטום שאיבד או קיבל אלקטרונים ולכן טעון","כימיה וחומר",'מיוונית ion — "הולך", כי יונים נעים לעבר קוטב חשמלי. את השם נתן מייקל פאראדיי. מלח בישול בנוי מיונים של נתרן ושל כלור.',["איך נקרא אטום טעון, שאיבד או קיבל אלקטרונים?","יון"]],["מהי הטבלה המחזורית?","סידור היסודות לפי מספר אטומי","כימיה וחומר",'"מחזורית" כי תכונות היסודות חוזרות במחזורים: כל עמודה היא משפחה של יסודות דומים, כמו הגזים האצילים בעמודה האחרונה. יש בה היום 118 יסודות.',["איך נקרא הסידור של היסודות לפי מספר אטומי?","הטבלה המחזורית"]],["מי פיתח את הטבלה המחזורית?","דמיטרי מנדלייב","כימיה וחומר","ב-1869 השאיר בטבלה משבצות ריקות, וחזה את תכונותיהם של יסודות שעוד לא התגלו — ושלושה מהם התגלו בשנים שאחר כך, כמעט בדיוק כמו שחזה.",["מה פיתח דמיטרי מנדלייב ב-1869?","את הטבלה המחזורית"]],["מהו היסוד הנפוץ ביותר ביקום?","מימן","כימיה וחומר","כשלושה רבעים מהחומר הרגיל ביקום הוא מימן. בליבת השמש מימן הופך להליום — ומהתהליך הזה מגיעים האור והחום.",["באיזה שיא מחזיק המימן בין היסודות?","היסוד הנפוץ ביותר ביקום"]],["מהו היסוד הנפוץ ביותר בקרום כדור הארץ?","חמצן","כימיה וחומר","כמעט חצי ממשקל הקרום הוא חמצן — לא כגז, אלא קשור בסלעים, בעיקר בתרכובות של צורן. הצורן הוא השני ברשימה.",["באיזה שיא מחזיק החמצן בקרום כדור הארץ?","היסוד הנפוץ ביותר בקרום"]],["מהי הנוסחה הכימית של מים?","H₂O","כימיה וחומר","שני אטומי מימן ואחד של חמצן. מים הם מהחומרים המעטים שמתפשטים כשהם קופאים — ולכן הקרח צף, ואגמים קופאים מלמעלה ולא מלמטה.",["איזה חומר נכתב בנוסחה H₂O?","מים"]],["מהו pH?","סולם המודד חומציות ובסיסיות, מ-0 עד 14","כימיה וחומר","הומצא ב-1909, במעבדה של מבשלת קרלסברג בדנמרק. כל דרגה בסולם היא פי עשרה: מיץ לימון (pH 2) חומצי פי מאה אלף ממים טהורים.",["איך נקרא הסולם המודד חומציות ובסיסיות, מ-0 עד 14?","pH"]],["מהו ערך ה-pH של מים טהורים?","7 — ניטרלי","כימיה וחומר","הדם שלנו בסיסי מעט — pH של כ-7.4 — והגוף שומר עליו בקפדנות: גם סטייה קטנה ממנו מסכנת חיים.",["לאיזה חומר טהור יש pH של 7 בדיוק — ניטרלי?","מים"]],["מהי תגובה אקסותרמית?","תגובה שמשחררת חום","כימיה וחומר","מיוונית: exo (החוצה) + thermos (חום). שריפה היא תגובה אקסותרמית; ההפך, תגובה אנדותרמית, קולטת חום — כמו בשקית הקירור המיידית שבתיק עזרה ראשונה.",["איך נקראת תגובה כימית שמשחררת חום?","תגובה אקסותרמית"]],["מהו קטליזטור?","חומר שמזרז תגובה כימית בלי להתכלות","כימיה וחומר",'בכל מכונית יש "ממיר קטליטי", שבו מתכות כמו פלטינה הופכות גזי פליטה רעילים לפחות מזיקים. בגוף, האנזימים הם הקטליזטורים.',["איך נקרא חומר שמזרז תגובה כימית בלי להתכלות בה?","קטליזטור (זרז)"]],["מהי אנטרופיה?","מידת אי-הסדר במערכת","פיזיקה","חדר מסודר נוטה להתבלגן, לא להפך; כוס שבורה לא מתאחה מעצמה. האנטרופיה היא הסיבה שלזמן יש כיוון.",["איך נקראת מידת אי-הסדר במערכת?","אנטרופיה"]],["מהו החוק הראשון של התרמודינמיקה?","אנרגיה אינה נוצרת ואינה נעלמת","פיזיקה",'זה חוק שימור האנרגיה: היא רק עוברת מצורה לצורה. לכן "מכונת תנועה נצחית", שמפיקה אנרגיה יש מאין, היא בלתי אפשרית.',["איזה חוק קובע שאנרגיה אינה נוצרת ואינה נעלמת?","החוק הראשון של התרמודינמיקה"]],["מהו החוק השני של התרמודינמיקה?","האנטרופיה של מערכת סגורה תמיד עולה","פיזיקה","ליתר דיוק: במערכת סגורה האנטרופיה לא יורדת לעולם. לכן חום זורם תמיד מהחם אל הקר, ושום מנוע לא ינצל את כל האנרגיה שלו.",["איזה חוק קובע שהאנטרופיה של מערכת סגורה רק עולה?","החוק השני של התרמודינמיקה"]],["מהו חוק הכבידה של ניוטון?","כל שני גופים נמשכים ביחס למכפלת מסותיהם","פיזיקה","והכוח נחלש עם ריבוע המרחק: פי שניים רחוק — פי ארבעה חלש. סיפור התפוח מוגזם כנראה, אבל ניוטון עצמו סיפר שתפוח נופל עורר בו את המחשבה.",["איזה חוק קובע שכל שני גופים נמשכים זה לזה ביחס למכפלת מסותיהם?","חוק הכבידה של ניוטון"]],["מהו החוק הראשון של ניוטון?","גוף נשאר במנוחה או בתנועה קבועה ללא כוח חיצוני","פיזיקה","חוק ההתמדה. בחלל, חללית שכיבתה מנועים ממשיכה לשוט; על כדור הארץ החיכוך והכבידה עוצרים הכול, ולכן החוק נראה לנו לא טבעי.",["איזה חוק של ניוטון קובע שגוף נשאר במנוחה או בתנועה קבועה כל עוד לא פועל עליו כוח?","החוק הראשון — חוק ההתמדה"]],["מהו החוק השני של ניוטון?","כוח שווה מסה כפול תאוצה","פיזיקה","F=ma. לכן קשה יותר לדחוף משאית מעגלת קניות: לאותה תאוצה צריך כוח גדול יותר ככל שהמסה גדולה. יחידת הכוח קרויה על שמו — ניוטון.",["איזה חוק של ניוטון מתבטא בנוסחה F=ma?","החוק השני של ניוטון"]],["מהו החוק השלישי של ניוטון?","לכל פעולה יש תגובה שווה ונגדית","פיזיקה",'כך טסה רקטה: היא דוחפת גזים לאחור, והגזים דוחפים אותה קדימה. ולכן גם רובה "בועט" בכתף של היורה.',["איזה חוק של ניוטון קובע שלכל פעולה יש תגובה שווה ונגדית?","החוק השלישי של ניוטון"]],["מהי המשוואה המפורסמת של איינשטיין?","E=mc²","פיזיקה","מסה היא אנרגיה ארוזה: מהירות האור בריבוע היא מספר עצום, ולכן מעט מסה שווה אנרגיה אדירה — הסוד של הכורים הגרעיניים ושל השמש.",["מה אומרת המשוואה E=mc²?","אנרגיה שווה מסה כפול מהירות האור בריבוע"]],["מהי תורת היחסות הפרטית?","תורה על תנועה במהירויות קרובות למהירות האור","פיזיקה",'פורסמה ב-1905, "שנת הנס" של איינשטיין. אחת המסקנות: שעון שנע מהר מתקתק לאט יותר — והשעונים בלווייני ה-GPS צריכים לכן תיקון קבוע.',["איזו תורה של איינשטיין מתארת תנועה במהירויות קרובות למהירות האור?","תורת היחסות הפרטית (1905)"]],["מהי תורת היחסות הכללית?","תורה המתארת כבידה כעיקום המרחב-זמן","פיזיקה","פורסמה ב-1915. ב-1919 אומתה בליקוי חמה: אור של כוכבים רחוקים התעקם ליד השמש בדיוק כמו שאיינשטיין חזה — והוא הפך בן לילה לכוכב עולמי.",["איזו תורה של איינשטיין מתארת כבידה כעיקום של המרחב-זמן?","תורת היחסות הכללית (1915)"]],["מהי מהירות האור?","כ-300,000 קילומטר בשנייה","פיזיקה","בדיוק 299,792,458 מטר בשנייה. אור השמש מגיע אלינו בתוך כשמונה דקות, ואור הירח — בתוך קצת יותר משנייה.",["מה נע במהירות של כ-300,000 קילומטר בשנייה?","האור"]],["מהי שנת אור?","המרחק שהאור עובר בשנה","פיזיקה","יחידה של מרחק, לא של זמן: כ-9.5 טריליון קילומטר. כשמסתכלים על כוכב שנמצא 100 שנות אור מאיתנו, רואים אותו כפי שהיה לפני מאה שנה.",["איך נקרא המרחק שהאור עובר בשנה?","שנת אור"]],["מהי אנרגיה קינטית?","אנרגיה של גוף בתנועה","פיזיקה","מיוונית kinesis — תנועה. היא גדלה עם ריבוע המהירות: מכונית במהירות 100 קמ״ש נושאת פי ארבעה אנרגיה מאשר ב-50 — ולכן תאונה מהירה הרסנית כל כך.",["איך נקראת האנרגיה של גוף בתנועה?","אנרגיה קינטית"]],["מהי אנרגיה פוטנציאלית?","אנרגיה אגורה בשל מיקום או מצב","פיזיקה","מים בראש סכר, קפיץ מתוח, ספר על מדף — כולם אוגרים אנרגיה בגלל המיקום או המצב שלהם. כשהמים נופלים היא הופכת לקינטית, ובתחנת הכוח — לחשמל.",["איך נקראת אנרגיה שאגורה בגוף בגלל המיקום או המצב שלו?","אנרגיה פוטנציאלית"]],["מהו תדר?","מספר המחזורים בשנייה, נמדד בהרץ","פיזיקה","היחידה קרויה על שם הפיזיקאי היינריך הרץ, שהוכיח את קיומם של גלי רדיו. רשת החשמל בישראל פועלת בתדר של 50 הרץ.",["איך נקרא מספר המחזורים בשנייה, שנמדד בהרץ?","תדר"]],["מהו אפקט דופלר?","שינוי בתדר גל בגלל תנועה יחסית","פיזיקה","הסירנה של אמבולנס נשמעת גבוהה כשהוא מתקרב ונמוכה כשהוא מתרחק. אותו אפקט, באור, הראה שהגלקסיות מתרחקות מאיתנו — היקום מתפשט.",["איך נקרא השינוי בתדר של גל בגלל תנועה יחסית?","אפקט דופלר"]],["מהי קרינה אלקטרומגנטית?","גלים של שדה חשמלי ומגנטי — מרדיו ועד גמא","פיזיקה","גלי רדיו, מיקרוגל, אור, קרני רנטגן וגמא — כולם אותו דבר בדיוק, רק באורכי גל שונים. וכולם נעים במהירות האור.",["איך נקראים גלים של שדה חשמלי ומגנטי, מגלי רדיו ועד קרני גמא?","קרינה אלקטרומגנטית"]],["מהו ספקטרום נראה?","טווח הגלים שהעין קולטת — אדום עד סגול","פיזיקה","רק פרוסה דקה מכל הקרינה האלקטרומגנטית. ניוטון פיצל אור לבן במנסרה וגילה שהוא מורכב מכל צבעי הקשת.",["איך נקרא טווח הגלים שהעין קולטת — מאדום ועד סגול?","הספקטרום הנראה"]],["מהו מוליך-על?","חומר שמוליך חשמל ללא התנגדות כלל","פיזיקה","ברוב החומרים זה קורה רק בקור קיצוני, קרוב לאפס המוחלט. מגנטים של מוליכי-על מפעילים מכשירי MRI ורכבות ריחוף מגנטי.",["איך נקרא חומר שמוליך חשמל בלי התנגדות כלל?","מוליך-על"]],["מהו חוק אוהם?","מתח שווה זרם כפול התנגדות","פיזיקה",'V=IR. ההתנגדות נמדדת ביחידה "אוהם", על שם הפיזיקאי הגרמני גאורג אוהם, והסימן שלה הוא האות היוונית אומגה: Ω.',["איזה חוק קובע שמתח שווה זרם כפול התנגדות?","חוק אוהם"]],["מהו תא?","יחידת החיים הבסיסית","ביולוגיה","את המונח טבע רוברט הוק ב-1665, כשהביט במיקרוסקופ בפיסת שעם: החללים הזכירו לו חדרים קטנים של נזירים. בגוף האדם יש עשרות טריליוני תאים.",["מהי יחידת החיים הבסיסית?","התא"]],["מהו DNA?","המולקולה הנושאת את המידע התורשתי","ביולוגיה","אם פורשים את ה-DNA של תא אנושי אחד, מתקבל חוט באורך של כשני מטרים — ארוז בתוך גרעין שאי אפשר לראות בעין.",["איך נקראת המולקולה הנושאת את המידע התורשתי?","DNA"]],["מי גילו את מבנה הסליל הכפול של ה-DNA?","ווטסון וקריק, 1953","ביולוגיה",'הם נשענו על צילום רנטגן של רוזלינד פרנקלין — "תמונה 51" — שהוצג להם בלי ידיעתה. פרנקלין מתה ב-1958, ולא הייתה בין זוכי הנובל של 1962.',["מה גילו ווטסון וקריק ב-1953?","את מבנה הסליל הכפול של ה-DNA"]],["מהו גן?","קטע DNA המקודד תכונה או חלבון","ביולוגיה","לאדם יש כ-20,000 גנים שמקודדים חלבונים — הרבה פחות ממה שחשבו פעם, ובערך כמו לעכבר.",["איך נקרא קטע DNA שמקודד תכונה או חלבון?","גן"]],["מהו כרומוזום?","מבנה של DNA ארוז, נושא גנים","ביולוגיה",'מיוונית: chroma (צבע) + soma (גוף) — "גוף צבוע", כי במיקרוסקופ הוא נצבע בצבענים. כרומוזומי המין, X ו-Y, קובעים אם נולד זכר או נקבה.',["איך נקרא מבנה של DNA ארוז שנושא גנים?","כרומוזום"]],["כמה כרומוזומים יש לאדם?","46 — 23 זוגות","ביולוגיה","לשימפנזה יש 48: אצל האדם שני כרומוזומים קדומים התאחדו לאחד — כרומוזום 2. תסמונת דאון נגרמת מעותק שלישי של כרומוזום 21.",null],["מהי מיטוזה?","חלוקת תא רגילה לשני תאים זהים","ביולוגיה","כך הגוף גדל ומתחדש: תאי העור, למשל, מתחלפים כל כמה שבועות. כשהחלוקה יוצאת משליטה — זה סרטן.",["איך נקראת חלוקת תא רגילה לשני תאים זהים?","מיטוזה"]],["מהי מיוזה?","חלוקה היוצרת תאי רבייה עם חצי מהכרומוזומים","ביולוגיה","תא זרע ותא ביצית נושאים כל אחד 23 כרומוזומים; באיחוד שלהם מתקבלים 46. בדרך הגנים מתערבבים — ולכן אחים אינם זהים.",["איך נקראת החלוקה שיוצרת תאי רבייה עם חצי מהכרומוזומים?","מיוזה"]],["מהי פוטוסינתזה?","תהליך שבו צמחים הופכים אור לסוכר","ביולוגיה","מיוונית: photos (אור) + synthesis (הרכבה). מפחמן דו-חמצני, ממים ומאור השמש הצמח בונה סוכר — וכמעט כל המזון על כדור הארץ מתחיל כאן.",["איך נקרא התהליך שבו צמחים הופכים אור לסוכר?","פוטוסינתזה"]],["מה נפלט בפוטוסינתזה?","חמצן","ביולוגיה","כמחצית מהחמצן בעולם מגיעה דווקא מהים — מאצות ומפלנקטון זעיר — ולא מהיערות.",["באיזה תהליך נפלט החמצן שאנחנו נושמים?","בפוטוסינתזה"]],["מהי נשימה תאית?","תהליך הפקת אנרגיה מסוכר בתאים","ביולוגיה","כמעט ההפך מפוטוסינתזה: סוכר וחמצן נכנסים, ויוצאים פחמן דו-חמצני, מים ואנרגיה. התהליך מתרחש במיטוכונדריה.",["איך נקרא התהליך שבו התאים מפיקים אנרגיה מסוכר?","נשימה תאית"]],["מהי מיטוכונדריה?","האברון שמייצר אנרגיה בתא","ביולוגיה","יש לה DNA משלה, שעובר רק מהאם. לפי התיאוריה המקובלת, היא הייתה פעם חיידק עצמאי שנבלע בתא אחר — ונשאר.",["איך נקרא האברון שמייצר אנרגיה בתא?","מיטוכונדריה"]],["מהו חלבון?","שרשרת חומצות אמינו הממלאת תפקיד בגוף","ביולוגיה","עשרים סוגים של חומצות אמינו מספיקים כדי לבנות את כל החלבונים בגוף — מהקרטין שבציפורניים ועד ההמוגלובין שבדם.",["איך נקראת שרשרת של חומצות אמינו שממלאת תפקיד בגוף?","חלבון"]],["מהו אנזים?","חלבון המזרז תגובה ביוכימית","ביולוגיה",'בלי אנזימים, תגובות רבות בגוף היו נמשכות שנים במקום שברירי שנייה. גם אבקות כביסה "ביולוגיות" מכילות אנזימים שמפרקים כתמים.',["איך נקרא חלבון שמזרז תגובה ביוכימית?","אנזים"]],["מהו נוגדן?","חלבון של מערכת החיסון המזהה גורם זר","ביולוגיה","כל נוגדן מזהה מטרה אחת בדיוק, כמו מפתח למנעול. חיסון מלמד את הגוף לייצר נוגדנים מראש — לפני שהמחלה האמיתית מגיעה.",["איך נקרא חלבון של מערכת החיסון שמזהה גורם זר?","נוגדן"]],["מהו חיידק?","יצור חד-תאי ללא גרעין מוגדר","ביולוגיה","בגוף האדם יש בערך כמה חיידקים כמו תאים אנושיים — עשרות טריליונים — ורובם מועילים, בעיקר אלה שבמעיים.",["איך נקרא יצור חד-תאי שאין לו גרעין מוגדר?","חיידק"]],["מהו נגיף?","גורם מחלה שאינו תא ומתרבה רק בתוך תא מארח","ביולוגיה",'מלטינית virus — "רעל". נגיף הוא בעצם חומר תורשתי עטוף בחלבון; מחוץ לתא הוא לא עושה דבר, ומדענים עדיין מתווכחים אם הוא בכלל "חי".',["איך נקרא גורם מחלה שאינו תא, ומתרבה רק בתוך תא מארח?","נגיף (וירוס)"]],["מדוע אנטיביוטיקה לא עוזרת נגד נגיף?","היא פוגעת במבנים של חיידקים, שאין לנגיפים","ביולוגיה","לכן אין טעם לקחת אנטיביוטיקה נגד שפעת. שימוש מיותר רק מגדל חיידקים עמידים — אחת הסכנות הגדולות ברפואה היום.",null],["מהי אבולוציה?","שינוי הדרגתי בתכונות אוכלוסייה לאורך דורות","ביולוגיה",'מלטינית evolvere — "לגלול החוצה". האבולוציה אינה שאיפה לשלמות: היא רק ממיינת את מה שמתאים יותר לסביבה של אותו רגע.',["איך נקרא השינוי ההדרגתי בתכונות של אוכלוסייה לאורך דורות?","אבולוציה"]],["מי ניסח את תורת האבולוציה?","צ׳רלס דרווין","ביולוגיה",'המסע שלו באוניית "ביגל" (1831–1836), ובעיקר החוחיות של איי גלפגוס, נתנו לו את הרעיון. אלפרד ראסל וולאס הגיע לאותה מסקנה בנפרד, באותן שנים.',["איזו תורה ניסח צ׳רלס דרווין?","את תורת האבולוציה בברירה טבעית"]],["מהי ברירה טבעית?","תהליך שבו תכונות מועילות נפוצות יותר בדורות הבאים","ביולוגיה","דוגמה קלאסית: באנגליה של המהפכה התעשייתית, כשהפיח השחיר את גזעי העצים, עשים כהים הוסוו טוב יותר — ותוך עשרות שנים הם שלטו באוכלוסייה.",["איך נקרא התהליך שבו תכונות מועילות נעשות נפוצות יותר בדורות הבאים?","ברירה טבעית"]],["מהו הספר שפרסם דרווין ב-1859?","מוצא המינים","ביולוגיה",'המהדורה הראשונה אזלה כבר ביום הראשון. הביטוי "הישרדות המתאים ביותר" אינו שלו — הוא של הרברט ספנסר, ונוסף רק במהדורות מאוחרות.',['מתי פרסם דרווין את "מוצא המינים"?',"1859"]],["מיהו אבי הגנטיקה?","גרגור מנדל","ביולוגיה","נזיר שגידל אפונה בגינת המנזר. עבודתו פורסמה ב-1866 ונשכחה, והתגלתה מחדש רק ב-1900 — אחרי מותו.",["איזה תואר יש לגרגור מנדל?","אבי הגנטיקה"]],["מהי מערכת אקולוגית?","קהילת יצורים והסביבה הדוממת שלהם","ביולוגיה",'"אקולוגיה" מיוונית oikos — בית. מאותה מילה בדיוק באה גם "אקונומיה", כלכלה: ניהול משק הבית.',["איך נקראת קהילת יצורים יחד עם הסביבה הדוממת שלהם?","מערכת אקולוגית"]],["מהו שרשרת מזון?","רצף של מי אוכל את מי במערכת אקולוגית","ביולוגיה","בכל חוליה הולכת לאיבוד רוב האנרגיה — רק כעשירית עוברת הלאה. לכן יש הרבה יותר צמחים מאוכלי צמחים, והרבה יותר אוכלי צמחים מטורפים.",['איך נקרא הרצף של "מי אוכל את מי" במערכת אקולוגית?',"שרשרת מזון"]],["מהי הכחדה?","היעלמות מוחלטת של מין","ביולוגיה","יותר מ-99% מכל המינים שחיו אי פעם על כדור הארץ נכחדו. הדינוזאורים נעלמו לפני 66 מיליון שנה, ככל הנראה אחרי פגיעת אסטרואיד.",["איך נקראת היעלמות מוחלטת של מין?","הכחדה"]],["מהו אפקט החממה?","לכידת חום באטמוספרה על ידי גזים","כדור הארץ והיקום","בלעדיו כדור הארץ היה קפוא — כמינוס 18 מעלות בממוצע. הבעיה היא לא האפקט עצמו אלא ההתגברות שלו, בגלל הפחמן הדו-חמצני שאנחנו מוסיפים.",["איך נקראת לכידת החום באטמוספרה על ידי גזים?","אפקט החממה"]],["מהו הגז העיקרי באטמוספרה?","חנקן — כ-78 אחוזים","כדור הארץ והיקום","החמצן הוא רק כ-21%. החנקן כמעט לא מגיב עם שום דבר, ולכן ממלאים בו גם שקיות חטיפים — כדי שיישארו רעננים.",["איזה חלק מהאטמוספרה הוא חנקן?","כ-78 אחוזים — הגז העיקרי בה"]],["מהי שכבת האוזון?","שכבה באטמוספרה החוסמת קרינה אולטרה-סגולה","כדור הארץ והיקום",'בשנות ה-80 התגלה בה "חור" מעל אנטארקטיקה, בגלל גזים מתרסיסים וממקררים. אמנת מונטריאול (1987) אסרה אותם — והחור הולך ונסגר.',["איך נקראת השכבה באטמוספרה שחוסמת קרינה אולטרה-סגולה?","שכבת האוזון"]],["מהי מערכת השמש?","השמש והגופים הסובבים אותה","כדור הארץ והיקום","השמש לבדה מחזיקה כ-99.8% מכל המסה במערכת. כל כוכבי הלכת יחד הם רק השארית.",["איך נקראים השמש וכל הגופים שסובבים אותה?","מערכת השמש"]],["כמה כוכבי לכת יש במערכת השמש?","שמונה","כדור הארץ והיקום","חמה, נוגה, ארץ, מאדים, צדק, שבתאי, אורנוס ונפטון. ארבעת הראשונים סלעיים; ארבעת האחרונים ענקי גז וקרח.",null],["מהו כוכב הלכת הגדול ביותר?","צדק","כדור הארץ והיקום",'גדול כל כך שכל שאר כוכבי הלכת היו נכנסים בתוכו יחד. "הכתם האדום הגדול" שלו הוא סערה שגדולה מכדור הארץ, ונצפית כבר יותר ממאה וחמישים שנה.',["באיזה שיא מחזיק צדק בין כוכבי הלכת?","הגדול ביותר במערכת השמש"]],["מהו כוכב הלכת הקרוב ביותר לשמש?","חמה","כדור הארץ והיקום","שנה על חמה נמשכת 88 ימים בלבד. בעברית הוא נקרא על שם השמש עצמה, ובלועזית — מרקורי, שליח האלים המהיר.",["איזה מקום יש לחמה (מרקורי) בסדר כוכבי הלכת?","הקרוב ביותר לשמש"]],["מהו כוכב הלכת החם ביותר?","נוגה","כדור הארץ והיקום","חם אפילו יותר מחמה, שקרובה ממנו לשמש — כי האטמוספרה הדחוסה שלו כולאת את החום: כ-460 מעלות. נוגה הוא גם הבהיר ביותר בשמיים אחרי הירח.",["באיזה שיא מחזיק נוגה בין כוכבי הלכת?","החם ביותר"]],["מדוע פלוטו אינו כוכב לכת?","הוגדר מחדש ב-2006 ככוכב לכת ננסי","כדור הארץ והיקום",'הוא קטן מהירח שלנו, והוא לא "ניקה" את המסלול שלו מגופים אחרים — אחד משלושת התנאים שנקבעו ב-2006. פלוטו התגלה ב-1930.',null],["מהי גלקסיה?","מערכת ענק של כוכבים, גז ואבק","כדור הארץ והיקום","מיוונית gala — חלב. ביקום הנצפה יש מאות מיליארדי גלקסיות, ובכל אחת מאות מיליארדי כוכבים.",["איך נקראת מערכת ענק של כוכבים, גז ואבק?","גלקסיה"]],["מה שם הגלקסיה שלנו?","שביל החלב","כדור הארץ והיקום","לפי המיתולוגיה היוונית זה חלב שנשפך מהאלה הרה. מערכת השמש נמצאת באחת מזרועות הגלקסיה, כ-26 אלף שנות אור ממרכזה.",["מהו שביל החלב?","הגלקסיה שלנו"]],["מהו המפץ הגדול?","התיאוריה על ראשית היקום מנקודה צפופה וחמה","כדור הארץ והיקום","השם נטבע בלעג: האסטרונום פרד הויל, שהתנגד לתיאוריה, כינה אותה כך בשידור רדיו ב-1949 — והכינוי נדבק.",["איך נקראת התיאוריה על ראשית היקום מנקודה צפופה וחמה?","המפץ הגדול"]],["בן כמה היקום?","כ-13.8 מיליארד שנה","כדור הארץ והיקום","כדור הארץ צעיר בהרבה — כ-4.5 מיליארד שנה. אילו כל ההיסטוריה של היקום הייתה שנה אחת, בני האדם היו מופיעים רק בדקות האחרונות של 31 בדצמבר.",null],["מהו חור שחור?","גוף שכוח הכבידה שלו כה חזק שאף אור לא נמלט","כדור הארץ והיקום",'ב-2019 פורסמה התמונה הראשונה של חור שחור, בגלקסיה M87. הגבול שממנו אין חזרה נקרא "אופק האירועים".',["איך נקרא גוף שכוח הכבידה שלו חזק כל כך שאפילו אור לא נמלט ממנו?","חור שחור"]],["מהו סופרנובה?","התפוצצות של כוכב בסוף חייו","כדור הארץ והיקום","בפיצוצים כאלה נוצרים יסודות כבדים — וחלק מהברזל שבדם שלך נוצר בכוכבים שהתפוצצו לפני מיליארדי שנים. ב-1054 נראתה סופרנובה מכדור הארץ גם ביום.",["איך נקראת התפוצצות של כוכב בסוף חייו?","סופרנובה"]],["מהו ליקוי חמה?","הירח עובר בין כדור הארץ לשמש","כדור הארץ והיקום","צירוף מקרים קוסמי: השמש גדולה מהירח פי 400 בערך, אבל גם רחוקה ממנו פי 400 — ולכן הירח מכסה אותה כמעט בדיוק.",["איך נקרא המצב שבו הירח עובר בין כדור הארץ לשמש?","ליקוי חמה"]],["מהו ליקוי לבנה?","כדור הארץ מסתיר את השמש מהירח","כדור הארץ והיקום",'בליקוי מלא הירח לא נעלם אלא מאדים — "ירח דם" — כי אור השמש שעובר דרך האטמוספרה של כדור הארץ מתעקם ומגיע אליו.',["איך נקרא המצב שבו כדור הארץ מסתיר את השמש מהירח?","ליקוי לבנה"]],["מדוע יש עונות שנה?","בגלל נטיית ציר כדור הארץ","כדור הארץ והיקום","הציר נטוי בכ-23.5 מעלות. זו לא שאלה של מרחק מהשמש: כדור הארץ דווקא הכי קרוב לשמש בתחילת ינואר — באמצע החורף שלנו.",null],["מהו גאות ושפל?","שינוי מפלס הים בשל כבידת הירח והשמש","כדור הארץ והיקום","בכל יום יש בדרך כלל שתי גאויות. בים התיכון ההפרש קטן, אבל במפרץ פאנדי שבקנדה הוא מגיע ל-16 מטר.",["איך נקרא השינוי במפלס הים בגלל כבידת הירח והשמש?","גאות ושפל"]]]},p={id:"politics",name:"מושגים בפוליטיקה וממשל",description:"מושגים מהחדשות — משטרים, מוסדות בינלאומיים, ומונחי ממשל שמשתמשים בהם בלי להסביר.",cards:[["מהי דמוקרטיה?","משטר שבו העם בוחר את נציגיו","משטרים וממשל","מיוונית: demos (עם) + kratos (שלטון). באתונה העתיקה הייתה דמוקרטיה ישירה — האזרחים הצביעו בעצמם באספה. אבל נשים, עבדים וזרים לא נחשבו אזרחים.",["איך נקרא משטר שבו העם בוחר את נציגיו?","דמוקרטיה"]],["מהי רפובליקה?","מדינה שראשה נבחר ואינו מלך","משטרים וממשל",'מלטינית res publica — "עניין ציבורי". גם ישראל היא רפובליקה: בראשה עומד נשיא נבחר, לא מלך.',["איך נקראת מדינה שבראשה עומד נבחר ולא מלך?","רפובליקה"]],["מהי מונרכיה חוקתית?","מלוכה שבה סמכות המלך מוגבלת בחוק","משטרים וממשל",'בבריטניה, למשל, המלך "מולך אבל לא שולט": הממשלה והפרלמנט מחליטים, והמלך חותם. גם שוודיה, יפן וספרד הן מונרכיות חוקתיות.',["איך נקראת מלוכה שבה סמכות המלך מוגבלת בחוק?","מונרכיה חוקתית"]],["מהי אוליגרכיה?","שלטון של קבוצה קטנה","משטרים וממשל",'מיוונית: oligos (מעטים) + arche (שלטון). במובן של היום — בעיקר ברוסיה שאחרי ברית המועצות — "אוליגרכים" הם בעלי הון עצום עם השפעה פוליטית.',["איך נקרא שלטון של קבוצה קטנה?","אוליגרכיה"]],["מהי אוטוקרטיה?","שלטון יחיד ללא הגבלה","משטרים וממשל",'מיוונית: autos (עצמי) + kratos (שלטון) — "שולט בכוח עצמו". הצאר הרוסי נשא רשמית את התואר "אוטוקרטור".',["איך נקרא שלטון יחיד ללא הגבלה?","אוטוקרטיה"]],["מהי טוטליטריות?","משטר השולט בכל תחומי חיי האזרח","משטרים וממשל",'המונח נולד באיטליה של מוסוליני, שאף אימץ אותו בגאווה: "הכול בתוך המדינה, שום דבר מחוצה לה". "1984" של אורוול הוא התיאור הספרותי המפורסם.',["איך נקרא משטר ששולט בכל תחומי החיים של האזרח?","משטר טוטליטרי"]],["מהי אנרכיה?","היעדר שלטון","משטרים וממשל","מיוונית: an (בלי) + arche (שלטון). כאידיאולוגיה, האנרכיזם לא דוגל בכאוס אלא בחברה שמתארגנת בלי מדינה ובלי כפייה.",["איך נקרא מצב של היעדר שלטון?","אנרכיה"]],["מהי פדרציה?","מדינה המורכבת ממדינות עם סמכויות עצמאיות","משטרים וממשל",'מלטינית foedus — "ברית". ארה״ב, גרמניה ושווייץ הן פדרציות: לכל מדינה או קנטון יש חוקים משלהם, ולצידם ממשלה מרכזית.',["איך נקראת מדינה המורכבת ממדינות בעלות סמכויות עצמאיות?","פדרציה"]],["מהי הפרדת רשויות?","חלוקת הכוח בין המחוקקת, המבצעת והשופטת","משטרים וממשל",'את הרעיון ניסח ההוגה הצרפתי מונטסקייה ב-1748, בספרו "רוח החוקים": כדי שלא יקום עריץ, כל רשות צריכה לבלום את האחרות.',["איך נקראת חלוקת הכוח בין הרשות המחוקקת, המבצעת והשופטת?","הפרדת רשויות"]],["מהי הרשות המחוקקת?","הגוף שמחוקק חוקים — הפרלמנט","משטרים וממשל",'בישראל — הכנסת. בארה״ב הקונגרס, ובבריטניה הפרלמנט. "פרלמנט" בא מצרפתית parler — לדבר.',["איזו רשות מחוקקת את החוקים?","הרשות המחוקקת — הפרלמנט"]],["מהי הרשות המבצעת?","הממשלה, המיישמת את החוקים","משטרים וממשל","בישראל — הממשלה, בראשות ראש הממשלה. בארה״ב היא מרוכזת בידי הנשיא, ולכן שם הוא גם ראש המדינה וגם ראש הממשלה.",["איזו רשות מיישמת את החוקים?","הרשות המבצעת — הממשלה"]],["מהי הרשות השופטת?","בתי המשפט, המפרשים את החוק","משטרים וממשל","בישראל עומד בראשה בית המשפט העליון. השופטים נבחרים בוועדה שיש בה שופטים, שרים, חברי כנסת ונציגים של לשכת עורכי הדין.",["איזו רשות מפרשת את החוק?","הרשות השופטת — בתי המשפט"]],["מהי שיטת בחירות יחסית?","מספר המושבים נקבע לפי אחוז הקולות","משטרים וממשל","ישראל משתמשת בה בצורה הטהורה ביותר: כל המדינה היא אזור בחירה אחד. היתרון — כל קול נספר; החיסרון — הרבה מפלגות קטנות וקואליציות שבירות.",["איך נקראת שיטת בחירות שבה מספר המושבים נקבע לפי אחוז הקולות?","שיטת בחירות יחסית"]],["מהי שיטת בחירות רובנית?","המנצח באזור לוקח את כל המושב","משטרים וממשל","נהוגה בבריטניה ובארה״ב. מפלגה יכולה לזכות בה ברוב בפרלמנט עם פחות ממחצית הקולות — ולכן השיטה נוטה לייצר שתי מפלגות גדולות.",["איך נקראת שיטת בחירות שבה המנצח באזור לוקח את כל המושב?","שיטת בחירות רובנית (אזורית)"]],["מהו אחוז חסימה?","מינימום קולות הנדרש כדי להיכנס לפרלמנט","משטרים וממשל","בישראל 3.25%, בגרמניה 5%, ובטורקיה הוא היה עד 2022 לא פחות מ-10%. ככל שהוא גבוה יותר, פחות מפלגות קטנות נכנסות.",["איך נקרא המינימום של קולות שמפלגה צריכה כדי להיכנס לפרלמנט?","אחוז חסימה"]],["מהי קואליציה?","שיתוף מפלגות המרכיב ממשלה","משטרים וממשל",'מלטינית coalescere — "לגדול יחד". בישראל אף מפלגה מעולם לא זכתה לבדה ברוב בכנסת, ולכן כל ממשלה הייתה ממשלת קואליציה.',["איך נקרא שיתוף של מפלגות שמרכיב ממשלה?","קואליציה"]],["מהי אופוזיציה?","המפלגות שאינן בממשלה","משטרים וממשל",'מלטינית opponere — "להציב מול". בבריטניה זה תואר רשמי: "האופוזיציה הנאמנה להוד מלכותו" — מתנגדים לממשלה, אבל לא למדינה.',["איך נקראות המפלגות שאינן בממשלה?","האופוזיציה"]],["מהו אי-אמון?","הצבעה שמטרתה להפיל את הממשלה","משטרים וממשל",'בישראל זו הצבעת אי-אמון "קונסטרוקטיבית": כדי להפיל ממשלה צריך רוב של 61 שתומך גם בממשלה חלופית. לכן כמעט אף ממשלה לא נפלה כך.',["איך נקראת הצבעה בפרלמנט שמטרתה להפיל את הממשלה?","הצבעת אי-אמון"]],["מהו ממשלת מעבר?","ממשלה המכהנת עד להקמת ממשלה חדשה","משטרים וממשל","ממשלת מעבר אמורה להימנע מהחלטות דרמטיות וממינויים בכירים, כי אין מאחוריה אמון מחודש של הכנסת. בין 2019 ל-2021, בין סבבי בחירות, ישראל נוהלה כך תקופות ארוכות.",["איך נקראת ממשלה שמכהנת עד להקמת ממשלה חדשה?","ממשלת מעבר"]],["מהו וטו?","סמכות לבטל החלטה באופן חד-צדדי","משטרים וממשל",'בלטינית: "אני אוסר". במועצת הביטחון לכל אחת מחמש החברות הקבועות יש וטו — ולכן החלטה נגד אחת מהן כמעט אינה עוברת.',["איך נקראת סמכות לבטל החלטה באופן חד-צדדי?","וטו"]],["מהו פיליבסטר?","עיכוב הצבעה על ידי נאום ארוך במכוון","משטרים וממשל","המילה באה מכינוי לשודדי ים. ב-1957 נאם הסנאטור האמריקאי סטרום ת׳רמונד יותר מ-24 שעות ברצף, כדי לעכב חוק לזכויות אזרח.",["איך נקרא עיכוב של הצבעה בנאום ארוך במכוון?","פיליבסטר"]],["מהו רפרנדום?","משאל עם — הכרעה ישירה של הציבור","משטרים וממשל","בשווייץ עורכים משאלי עם כמה פעמים בשנה, כמעט על כל נושא. בבריטניה, משאל העם של 2016 הוביל לברקזיט.",["איך נקרא משאל עם — הכרעה ישירה של הציבור?","רפרנדום"]],["מהי חנינה?","ביטול או הקלה של עונש על ידי רשות","משטרים וממשל","בישראל הסמכות לחון נתונה לנשיא המדינה. חנינה אינה מוחקת את ההרשעה עצמה — היא מוחלת על העונש.",["איך נקרא ביטול או הקלה של עונש על ידי רשות מוסמכת?","חנינה"]],["מהי חסינות פרלמנטרית?","הגנה מפני העמדה לדין בשל פעילות בתפקיד","משטרים וממשל","המטרה המקורית: שהשלטון לא יוכל להשתיק נבחרים מהאופוזיציה בתביעות. בישראל, מאז 2005 חבר כנסת צריך לבקש חסינות מפני העמדה לדין — היא כבר לא אוטומטית.",["איך נקראת ההגנה של נבחרים מפני העמדה לדין בשל פעילותם?","חסינות פרלמנטרית"]],["מהו לובי?","פעילות להשפעה על מקבלי החלטות","משטרים וממשל","המקור: המסדרון (lobby) של הפרלמנט הבריטי, שבו חיכו בעלי עניין לחברי הפרלמנט כדי לשכנע אותם.",["איך נקראת פעילות להשפעה על מקבלי החלטות?","לובי (שתדלנות)"]],["מהי ביורוקרטיה?","מנגנון המנהל הציבורי ונהליו","משטרים וממשל",'מצרפתית bureau (משרד, שולחן כתיבה) + kratos — "שלטון השולחנות". הסוציולוג מקס ובר ראה בה דווקא דבר חיובי: שלטון של כללים במקום של גחמות.',["איך נקרא מנגנון המנהל הציבורי ונהליו?","ביורוקרטיה"]],["מהו האו״ם?","ארגון האומות המאוחדות, נוסד 1945","ארגונים בינלאומיים","נוסד ב-24 באוקטובר 1945, אחרי מלחמת העולם השנייה, עם 51 מדינות. היום חברות בו 193.",["איזה ארגון בינלאומי נוסד ב-1945, אחרי מלחמת העולם השנייה?","האו״ם — ארגון האומות המאוחדות"]],["היכן מטה האו״ם?","ניו יורק","ארגונים בינלאומיים","השטח שעליו עומד המטה נחשב בינלאומי, לא אמריקאי. את הקרקע לבנייתו תרם ג׳ון ד. רוקפלר הבן.",["איזה ארגון בינלאומי יושב במטה בניו יורק, על גדת האיסט ריבר?","האו״ם"]],["מהי מועצת הביטחון?","הגוף באו״ם האחראי לשלום ולביטחון בינלאומי","ארגונים בינלאומיים","15 חברות: חמש קבועות, ועשר שנבחרות לשנתיים. בניגוד להחלטות העצרת הכללית, ההחלטות שלה מחייבות.",["איך נקרא הגוף באו״ם שאחראי לשלום ולביטחון הבינלאומי?","מועצת הביטחון"]],["כמה חברות קבועות יש במועצת הביטחון?","חמש","ארגונים בינלאומיים","חמש המעצמות שניצחו במלחמת העולם השנייה. לכל אחת מהן יש זכות וטו.",null],["מי החברות הקבועות במועצת הביטחון?","ארה״ב, רוסיה, סין, בריטניה וצרפת","ארגונים בינלאומיים","את המושב של סין החזיקה עד 1971 טייוואן, ואת זה של רוסיה — עד 1991 ברית המועצות.",null],["מהו נאט״ו?","ברית צבאית של מדינות המערב, נוסדה 1949","ארגונים בינלאומיים","ראשי התיבות: ארגון האמנה הצפון-אטלנטית. נוסד נגד האיום הסובייטי, ומאז רק התרחב — פינלנד ושוודיה הצטרפו אחרי הפלישה הרוסית לאוקראינה.",["איך נקראת הברית הצבאית של מדינות המערב, שנוסדה ב-1949?","נאט״ו"]],["מהו סעיף 5 של נאט״ו?","התקפה על חברה אחת נחשבת התקפה על כולן","ארגונים בינלאומיים","הסעיף הופעל פעם אחת בלבד בהיסטוריה — אחרי פיגועי 11 בספטמבר 2001, לטובת ארצות הברית.",["איזה סעיף באמנת נאט״ו קובע שהתקפה על חברה אחת היא התקפה על כולן?","סעיף 5"]],["מהו האיחוד האירופי?","איחוד כלכלי ופוליטי של מדינות אירופה","ארגונים בינלאומיים",'נולד מ"קהילת הפחם והפלדה" של 1951: הרעיון היה לקשור את כלכלות צרפת וגרמניה כך שמלחמה ביניהן תהיה בלתי אפשרית. ב-2012 קיבל פרס נובל לשלום.',["איך נקרא האיחוד הכלכלי והפוליטי של מדינות אירופה?","האיחוד האירופי"]],["היכן מוסדות האיחוד האירופי?","בריסל, בעיקר","ארגונים בינלאומיים","בריסל היא הבית של הנציבות ושל המועצה, אבל הפרלמנט האירופי מתכנס גם בשטרסבורג, ובית הדין יושב בלוקסמבורג.",["איזו עיר נחשבת לבירה של האיחוד האירופי?","בריסל"]],["מהו גוש האירו?","המדינות שאימצו את האירו כמטבע","ארגונים בינלאומיים","שטרות ומטבעות של אירו נכנסו לשימוש ב-2002. לא כל מדינות האיחוד אימצו אותו: דנמרק ושוודיה, למשל, שמרו על הכתר שלהן.",["איך נקראת קבוצת המדינות שאימצו את האירו כמטבע?","גוש האירו"]],["מהו הסכם שנגן?","הסכם המבטל ביקורת גבולות בין מדינות אירופה","ארגונים בינלאומיים","על שם כפר קטן בלוקסמבורג שבו נחתם ב-1985 — ליד הנקודה שבה נפגשים הגבולות של לוקסמבורג, צרפת וגרמניה.",["איך נקרא ההסכם שמבטל את ביקורת הגבולות בין מדינות אירופה?","הסכם שנגן"]],["מהו ברקזיט?","יציאת בריטניה מהאיחוד האירופי, 2020","ארגונים בינלאומיים","הלחם של Britain ו-exit. משאל העם נערך ב-2016 והסתיים ב-52% בעד; היציאה עצמה נכנסה לתוקף בינואר 2020.",["איך נקראה יציאת בריטניה מהאיחוד האירופי?","ברקזיט"]],["מהו בית הדין הבינלאומי בהאג?","הערכאה השיפוטית של האו״ם בין מדינות","ארגונים בינלאומיים",'באנגלית ICJ. הוא דן רק בסכסוכים בין מדינות, לא באנשים, ויושב ב"ארמון השלום" בהאג — שבנייתו מומנה בידי אנדרו קרנגי.',["איך נקראת הערכאה השיפוטית של האו״ם, שדנה בסכסוכים בין מדינות?","בית הדין הבינלאומי לצדק בהאג"]],["מהו בית הדין הפלילי הבינלאומי?","בית דין לשיפוט יחידים על פשעים חמורים","ארגונים בינלאומיים","באנגלית ICC. הוקם ב-2002 לפי אמנת רומא, ויושב גם הוא בהאג. ישראל וארה״ב אינן חברות בו.",["איך נקרא בית הדין ששופט יחידים על פשעי מלחמה ועל פשעים נגד האנושות?","בית הדין הפלילי הבינלאומי (ICC)"]],["מהי אמנת ז׳נבה?","אמנה הקובעת כללים בדיני מלחמה","ארגונים בינלאומיים","האמנה הראשונה נחתמה ב-1864, ביוזמת אנרי דינן, מייסד הצלב האדום. ארבע האמנות המוכרות היום נחתמו ב-1949.",["איך נקראות האמנות שקובעות כללים בדיני מלחמה?","אמנות ז׳נבה"]],["מהו הבנק העולמי?","ארגון המעניק מימון לפיתוח למדינות","ארגונים בינלאומיים","נוסד ב-1944 בוועידת ברטון וודס, יחד עם קרן המטבע. המשימה הראשונה שלו: לממן את שיקום אירופה אחרי המלחמה.",["איך נקרא הארגון שמעניק למדינות מימון לפרויקטים של פיתוח?","הבנק העולמי"]],["מהי קרן המטבע הבינלאומית?","ארגון המסייע ליציבות פיננסית עולמית","ארגונים בינלאומיים","באנגלית IMF. היא מלווה כסף למדינות במשבר — בדרך כלל בתנאי שיבצעו קיצוצים ורפורמות, ולכן היא שנויה במחלוקת.",["איך נקרא הארגון שמלווה למדינות במשבר כדי לשמור על יציבות פיננסית?","קרן המטבע הבינלאומית (IMF)"]],["מהו נאט״ו לעומת האיחוד האירופי?","נאט״ו הוא ברית צבאית, האיחוד הוא כלכלי-פוליטי","ארגונים בינלאומיים","יש מדינות שחברות רק באחד מהם: נורווגיה וטורקיה בנאט״ו ולא באיחוד, ואוסטריה ואירלנד באיחוד ולא בנאט״ו.",null],["מהי דיפלומטיה?","ניהול יחסים בין מדינות במשא ומתן","יחסים בינלאומיים",'מיוונית diploma — "מסמך מקופל", כמו כתבי האישור שנשאו שליחים. מאותה מילה בדיוק בא גם ה"דיפלומה".',["איך נקרא ניהול יחסים בין מדינות במשא ומתן?","דיפלומטיה"]],["מהו שגריר?","הנציג הבכיר של מדינה במדינה אחרת","יחסים בינלאומיים",'השגרירות מוגנת: המדינה המארחת לא נכנסת אליה בלי רשות. שגריר חדש מגיש "כתב האמנה" לראש המדינה המארחת, ורק אז מתחיל לכהן.',["איך נקרא הנציג הבכיר של מדינה במדינה אחרת?","שגריר"]],["מהי אקסטרדיציה?","הסגרת נאשם ממדינה אחת לאחרת","יחסים בינלאומיים","מלטינית: ex (מן) + traditio (מסירה). ישראל מסגירה גם אזרחים שלה — בתנאי שאם יורשעו, ירצו את עונשם בישראל.",["איך נקראת הסגרה של נאשם ממדינה אחת לאחרת?","אקסטרדיציה (הסגרה)"]],["מהי סנקציה?","צעד עונשי כלכלי או מדיני נגד מדינה","יחסים בינלאומיים",'מלטינית sanctio — "צו מחייב". היום סנקציות מכוונות יותר ויותר לאנשים: הקפאת נכסים ואיסור כניסה למנהיגים ולבעלי הון.',["איך נקרא צעד עונשי כלכלי או מדיני נגד מדינה?","סנקציה"]],["מהי אמברגו?","איסור סחר עם מדינה","יחסים בינלאומיים",'מספרדית embargar — "לעכב": במקור, צו לעכב ספינות בנמל. ארה״ב מטילה אמברגו על קובה מאז 1962 — מהארוכים בהיסטוריה.',["איך נקרא איסור סחר עם מדינה?","אמברגו"]],["מהי ריבונות?","סמכותה הבלעדית של מדינה בשטחה","יחסים בינלאומיים","העיקרון התגבש בשלום וסטפליה (1648), שסיים את מלחמת שלושים השנה: כל מדינה שולטת בשטחה, ואחרות לא מתערבות.",["איך נקראת הסמכות הבלעדית של מדינה בשטחה?","ריבונות"]],["מהו מקלט מדיני?","הגנה שמדינה מעניקה לנרדף פוליטי","יחסים בינלאומיים","אחד המקרים המפורסמים: ג׳וליאן אסאנג׳, מייסד ויקיליקס, חי שבע שנים בשגרירות אקוודור בלונדון תחת מקלט מדיני.",["איך נקראת ההגנה שמדינה מעניקה לנרדף פוליטי?","מקלט מדיני"]],["מהו פליט לפי המשפט הבינלאומי?","מי שנמלט ממדינתו מפחד רדיפה","יחסים בינלאומיים","ההגדרה נקבעה באמנת הפליטים של 1951. העיקרון המרכזי בה: אסור להחזיר פליט למקום שבו נשקפת סכנה לחייו.",["איך נקרא במשפט הבינלאומי מי שנמלט ממדינתו מפחד רדיפה?","פליט"]],["מהי אמנת האו״ם לזכויות האדם?","ההכרזה לכל באי עולם בדבר זכויות האדם, 1948","יחסים בינלאומיים","התקבלה ב-10 בדצמבר 1948, ולכן זה יום זכויות האדם הבינלאומי. אחד מכותביה העיקריים היה המשפטן היהודי-צרפתי רנה קאסן, חתן פרס נובל לשלום.",["איזה מסמך קיבלה עצרת האו״ם ב-10 בדצמבר 1948?","ההכרזה לכל באי עולם בדבר זכויות האדם"]],["מהי חברה אזרחית?","ארגונים לא-ממשלתיים הפועלים בציבור","יחסים בינלאומיים","עמותות, ארגוני זכויות, מתנדבים, איגודים — כל מה שבין המשפחה למדינה. בישראל פועלות אלפי עמותות.",["איך נקראים כלל הארגונים הלא-ממשלתיים שפועלים בציבור?","החברה האזרחית"]],["מהו פופוליזם?","סגנון פוליטי הפונה ל״עם״ מול ״האליטה״","יחסים בינלאומיים",'מלטינית populus — "העם". פופוליזם יכול להיות מימין או משמאל; המשותף הוא הטענה "אנחנו העם האמיתי" מול אליטה מושחתת.',['איך נקרא סגנון פוליטי שפונה ל"עם" מול "האליטה"?',"פופוליזם"]],["מהי אידיאולוגיה?","מערכת רעיונות המנחה עמדה פוליטית","יחסים בינלאומיים",'את המילה טבע הפילוסוף הצרפתי דסטוט דה טרסי ב-1796, במשמעות "מדע הרעיונות". נפוליאון הפך אותה לגנאי: "אידיאולוגים" היו בעיניו חולמים מנותקים.',["איך נקראת מערכת רעיונות שמנחה עמדה פוליטית?","אידיאולוגיה"]],["מהו ליברליזם?","תפיסה המדגישה חירות הפרט וזכויותיו","יחסים בינלאומיים",'מלטינית liber — "חופשי". במאה ה-17 ניסח ג׳ון לוק את הרעיון שלכל אדם יש זכויות טבעיות — חיים, חירות וקניין — שהמדינה צריכה להגן עליהן.',["איך נקראת תפיסה פוליטית שמדגישה את חירות הפרט וזכויותיו?","ליברליזם"]],["מהו שמרנות?","תפיסה המדגישה שמירה על מסורת ומוסדות קיימים","יחסים בינלאומיים","אבי השמרנות המודרנית, אדמונד ברק, כתב נגד המהפכה הצרפתית: מוסדות שהתפתחו לאט נושאים חוכמה של דורות, ולא כדאי להרוס אותם בבת אחת.",["איך נקראת תפיסה שמדגישה שמירה על מסורת ועל מוסדות קיימים?","שמרנות"]],["מהי סוציאל-דמוקרטיה?","שילוב של כלכלת שוק עם מדינת רווחה חזקה","יחסים בינלאומיים","הדוגמה המוכרת היא המודל הנורדי — שוודיה, נורווגיה ודנמרק: מסים גבוהים, וחינוך ובריאות במימון ציבורי לכולם.",["איך נקראת גישה שמשלבת כלכלת שוק עם מדינת רווחה חזקה?","סוציאל-דמוקרטיה"]],["מהי אינפלציה?","עלייה מתמשכת ברמת המחירים","יחסים בינלאומיים",'מלטינית inflare — "לנפח". בהונגריה של 1946 נרשמה האינפלציה הגבוהה בהיסטוריה: המחירים הוכפלו בערך כל 15 שעות.',["איך נקראת עלייה מתמשכת ברמת המחירים?","אינפלציה"]]]},d={id:"world-history",name:"היסטוריה עולמית",description:"אירועים ודמויות שמעצבים את העולם שאנחנו חיים בו. מהמהפכה הצרפתית ועד נפילת חומת ברלין.",cards:[["מתי פרצה המהפכה הצרפתית?","1789","מהפכות והמאה ה-19",'סיסמת המהפכה, "חירות, שוויון, אחווה", היא עד היום המוטו הרשמי של צרפת. המלך לואי ה-16 הוצא להורג בגיליוטינה ב-1793.',["איזו מהפכה פרצה ב-1789?","המהפכה הצרפתית"]],["מהו יום הבסטיליה?","14 ביולי 1789 — כיבוש מבצר הבסטיליה","מהפכות והמאה ה-19","בבסטיליה ישבו באותו יום רק שבעה אסירים — אבל המבצר היה סמל לשלטון המלך. 14 ביולי הוא היום הלאומי של צרפת.",["מה קרה בפריז ב-14 ביולי 1789?","כיבוש מבצר הבסטיליה"]],["מי היה נפוליאון בונפרטה?","מצביא וקיסר צרפת, 1804–1815","מהפכות והמאה ה-19",'ב-1804 לקח את הכתר מידי האפיפיור והניח אותו על ראשו בעצמו. "קוד נפוליאון" שלו הוא הבסיס למשפט האזרחי בחלקים גדולים של העולם.',["מי היה המצביא שהיה לקיסר צרפת ב-1804?","נפוליאון בונפרטה"]],["מתי הובס נפוליאון סופית?","קרב ווטרלו, 1815","מהפכות והמאה ה-19","ווטרלו נמצאת בבלגיה של היום. הניצחון היה של הדוכס מוולינגטון ושל הפרוסים, ונפוליאון הוגלה לאי סנט הלנה, שם מת ב-1821.",["מה קרה לנפוליאון בקרב ווטרלו ב-1815?","הוא הובס סופית"]],["מתי הוכרזה עצמאות ארצות הברית?","4 ביולי 1776","מהפכות והמאה ה-19","את ההכרזה ניסח תומאס ג׳פרסון. שניים מהחותמים, שהיו לימים נשיאים — ג׳פרסון וג׳ון אדמס — מתו באותו יום: 4 ביולי 1826, היובל ה-50.",["מה הוכרז ב-4 ביולי 1776?","עצמאות ארצות הברית"]],["מי היה הנשיא הראשון של ארה״ב?","ג׳ורג׳ וושינגטון","מהפכות והמאה ה-19","פיקד על הצבא במלחמת העצמאות, ואחרי שתי קדנציות סירב להמשיך — מסורת שהפכה לחוק רק ב-1951. הבירה קרויה על שמו.",["איזה תפקיד מילא ג׳ורג׳ וושינגטון ראשון בארה״ב?","הנשיא הראשון"]],["מתי התרחשה מלחמת האזרחים האמריקאית?","1861–1865","מהפכות והמאה ה-19","בין מדינות הצפון למדינות הדרום, שרצו לשמור על העבדות ופרשו מהאיחוד. זו המלחמה הקטלנית בתולדות ארה״ב — יותר מ-600 אלף הרוגים.",["איזו מלחמה התחוללה בארה״ב בשנים 1861–1865?","מלחמת האזרחים"]],["מי היה אברהם לינקולן?","נשיא ארה״ב שביטל את העבדות ונרצח ב-1865","מהפכות והמאה ה-19",'נרצח בתיאטרון בוושינגטון, ימים ספורים אחרי שהמלחמה הוכרעה. "נאום גטיסבורג" שלו נמשך פחות משלוש דקות — ונחשב לאחד הנאומים הגדולים בהיסטוריה.',["איזה נשיא ארה״ב ביטל את העבדות ונרצח ב-1865?","אברהם לינקולן"]],["מתי פרצה מלחמת העולם הראשונה?","1914","מלחמות העולם",'בזמנה קראו לה "המלחמה הגדולה", ואפילו "המלחמה שתסיים את כל המלחמות". רוב החיילים היו בטוחים שיחזרו הביתה עד חג המולד.',["איזו מלחמה פרצה ב-1914?","מלחמת העולם הראשונה"]],["מה היה הטריגר למלחמת העולם הראשונה?","רצח יורש העצר האוסטרי פרנץ פרדיננד","מלחמות העולם","פרנץ פרדיננד נרצח בסרייבו ב-28 ביוני 1914, בידי הסטודנט הסרבי גברילו פרינציפ. נהג השיירה טעה בדרך — ועצר בדיוק מול הרוצח.",["איזו מלחמה הצית רצח יורש העצר פרנץ פרדיננד?","מלחמת העולם הראשונה"]],["מתי הסתיימה מלחמת העולם הראשונה?","11 בנובמבר 1918","מלחמות העולם",'שביתת הנשק נכנסה לתוקף "בשעה ה-11 של היום ה-11 בחודש ה-11". כ-20 מיליון בני אדם נהרגו במלחמה.',["איזו מלחמה הסתיימה ב-11 בנובמבר 1918?","מלחמת העולם הראשונה"]],["מהו הסכם ורסאי?","הסכם השלום שסיים את מלחמת העולם הראשונה, 1919","מלחמות העולם","נחתם באולם המראות של ארמון ורסאי — אותו אולם שבו הוכרזה האימפריה הגרמנית ב-1871. התנאים הקשים שהוטלו על גרמניה סייעו לעליית הנאצים.",["איזה הסכם שלום סיים את מלחמת העולם הראשונה ב-1919?","הסכם ורסאי"]],["מתי התרחשה המהפכה הרוסית?","1917","מלחמות העולם",'בעצם שתי מהפכות: בפברואר הודח הצאר, ובאוקטובר תפסו הבולשביקים את השלטון. לפי הלוח הגרגוריאני, "מהפכת אוקטובר" קרתה דווקא בנובמבר.',["איזו מהפכה ב-1917 הפילה את הצאר?","המהפכה הרוסית"]],["מי הנהיג את המהפכה הבולשביקית?","ולדימיר לנין","מלחמות העולם","שמו האמיתי ולדימיר אוליאנוב. ב-1917 העבירו אותו הגרמנים מגלותו בשווייץ לרוסיה ברכבת חתומה, בתקווה שיוציא את רוסיה מהמלחמה — וכך היה.",["איזו מהפכה הנהיג ולדימיר לנין?","המהפכה הבולשביקית (אוקטובר 1917)"]],["מתי הוקמה ברית המועצות?","1922","מלחמות העולם",'שמה הרשמי: איחוד הרפובליקות הסוציאליסטיות הסובייטיות. "סובייט" ברוסית פירושו "מועצה". בשיאה היו בה 15 רפובליקות.',["איזו מדינה-על הוקמה ב-1922 על חורבות האימפריה הרוסית?","ברית המועצות"]],["מי היה יוסיף סטלין?","מנהיג ברית המועצות, 1924–1953","מלחמות העולם",'שמו המקורי יוסיף ג׳וגשווילי, מגאורגיה. "סטלין" פירושו "איש הפלדה". בטיהורים ובמחנות הגולאג בתקופתו מתו מיליונים.',["מי הנהיג את ברית המועצות בשנים 1924–1953?","יוסיף סטלין"]],["מתי עלה היטלר לשלטון?","1933","מלחמות העולם",'הוא מונה לקנצלר בדרך חוקית, בינואר 1933. בתוך חודשים פירק את הדמוקרטיה, ובשנה שאחרי כבר היה "הפיהרר".',["מה קרה בגרמניה בינואר 1933?","היטלר עלה לשלטון — מונה לקנצלר"]],["מתי פרצה מלחמת העולם השנייה?","1 בספטמבר 1939","מלחמות העולם","בריטניה וצרפת הכריזו מלחמה על גרמניה יומיים אחר כך. במלחמה נהרגו יותר מ-70 מיליון בני אדם — המלחמה הקטלנית בהיסטוריה.",["איזו מלחמה פרצה ב-1 בספטמבר 1939?","מלחמת העולם השנייה"]],["מה פתח את מלחמת העולם השנייה?","פלישת גרמניה לפולין","מלחמות העולם","כעבור שבועיים פלשה לפולין גם ברית המועצות, מהמזרח — לפי פרוטוקול סודי בהסכם ריבנטרופ-מולוטוב. פולין חולקה בין שתיהן.",["לאיזו מדינה פלשה גרמניה ב-1 בספטמבר 1939?","פולין"]],["מהו ליל הבדולח?","פוגרום נגד יהודי גרמניה, נובמבר 1938","מלחמות העולם","השם — על שם רסיסי הזכוכית מחלונות הראווה ששברו. נשרפו כ-1,400 בתי כנסת, וכ-30 אלף גברים יהודים נשלחו למחנות ריכוז.",["איך נקרא הפוגרום נגד יהודי גרמניה בנובמבר 1938?","ליל הבדולח"]],["מהי ועידת ואנזה?",'הוועידה שבה תוכנן "הפתרון הסופי", 1942',"מלחמות העולם","ישיבה של כשעה וחצי, בווילה על שפת אגם בברלין, ב-20 בינואר 1942. הפרוטוקול שנמצא אחרי המלחמה הוא אחת הראיות החשובות לתכנון השואה.",['באיזו ועידה ב-1942 תואם "הפתרון הסופי"?',"ועידת ואנזה"]],["מהו יום הפלישה לנורמנדי?","D-Day, 6 ביוני 1944","מלחמות העולם",'הנחיתה הימית הגדולה בהיסטוריה: כ-156 אלף חיילים נחתו ביום אחד בחופי נורמנדי שבצרפת. ה-D ב-D-Day פשוט מסמן "היום".',["מה התרחש ב-6 ביוני 1944?","הפלישה לנורמנדי — D-Day"]],["מתי הסתיימה המלחמה באירופה?","8 במאי 1945","מלחמות העולם",'"יום הניצחון באירופה". ברוסיה חוגגים אותו ב-9 במאי, כי הכניעה נכנסה לתוקף אחרי חצות לפי שעון מוסקבה.',["מה הסתיים ב-8 במאי 1945?","מלחמת העולם השנייה באירופה"]],["מתי הוטלה פצצת האטום על הירושימה?","6 באוגוסט 1945","מלחמות העולם","שלושה ימים אחר כך הוטלה פצצה שנייה, על נגסאקי. אלה שתי הפעמים היחידות שבהן נעשה שימוש בנשק גרעיני במלחמה.",["על איזו עיר הוטלה פצצת האטום הראשונה, ב-6 באוגוסט 1945?","הירושימה"]],["מתי נכנעה יפן?","ספטמבר 1945","מלחמות העולם",'הקיסר הירוהיטו הודיע על הכניעה ברדיו ב-15 באוגוסט — הפעם הראשונה שהעם שמע את קולו. המסמך נחתם ב-2 בספטמבר, על סיפון אוניית המלחמה "מיזורי".',["מה עשתה יפן בספטמבר 1945?","נכנעה — ומלחמת העולם השנייה הסתיימה"]],["כמה יהודים נרצחו בשואה?","כשישה מיליון","מלחמות העולם","כשני שלישים מיהדות אירופה. יד ושם אסף עד היום את שמותיהם של כ-4.8 מיליון מהנרצחים.",null],["מהם משפטי נירנברג?","משפטי פושעי המלחמה הנאצים, 1945–1946","מלחמות העולם",'לראשונה הועמדו מנהיגים לדין על "פשעים נגד האנושות". נירנברג נבחרה גם בגלל הסמליות: שם התקיימו העצרות הגדולות של המפלגה הנאצית.',["איך נקראים משפטי פושעי המלחמה הנאצים בשנים 1945–1946?","משפטי נירנברג"]],["מהי המלחמה הקרה?","העימות בין ארה״ב לברית המועצות, 1947–1991","המלחמה הקרה ואילך",'"קרה" כי שתי המעצמות לא נלחמו ישירות זו בזו — רק במלחמות בשליחות, במרוץ חימוש ובמרוץ לחלל.',["איך נקרא העימות בין ארה״ב לברית המועצות בשנים 1947–1991?","המלחמה הקרה"]],["מהי תוכנית מרשל?","סיוע אמריקאי לשיקום אירופה אחרי המלחמה","המלחמה הקרה ואילך","על שם שר החוץ האמריקאי ג׳ורג׳ מרשל, שקיבל עליה פרס נובל לשלום. ארה״ב העבירה כ-13 מיליארד דולר — סכום עצום באותם ימים.",["איך נקראה תוכנית הסיוע האמריקאית לשיקום אירופה אחרי מלחמת העולם השנייה?","תוכנית מרשל"]],["מתי נבנתה חומת ברלין?","1961","המלחמה הקרה ואילך","הגדר הראשונה הוקמה בלילה אחד, באוגוסט 1961, כדי לעצור את הבריחה ממזרח גרמניה למערב. לפחות 140 איש נהרגו בניסיון לחצות אותה.",["מה נבנה בברלין ב-1961?","חומת ברלין"]],["מתי נפלה חומת ברלין?","9 בנובמבר 1989","המלחמה הקרה ואילך",'הנפילה התחילה מטעות: דובר השלטון המזרח-גרמני הודיע במסיבת עיתונאים שהמעברים נפתחים "מיד" — ורבבות נהרו אל החומה באותו לילה.',["מה קרה בברלין ב-9 בנובמבר 1989?","החומה נפלה"]],["מתי התפרקה ברית המועצות?","1991","המלחמה הקרה ואילך","בחג המולד 1991 התפטר גורבצ׳וב, והדגל האדום הורד מהקרמלין בפעם האחרונה. 15 הרפובליקות הפכו למדינות עצמאיות.",["מה התפרק ב-1991?","ברית המועצות"]],["מהו משבר הטילים בקובה?","עימות גרעיני בין ארה״ב לברה״מ, 1962","המלחמה הקרה ואילך","13 ימים באוקטובר 1962, שבהם העולם היה הכי קרוב למלחמה גרעינית. ברה״מ פירקה את הטילים בקובה, וארה״ב — בשקט — את הטילים שלה בטורקיה.",["איך נקרא העימות הגרעיני בין ארה״ב לברית המועצות ב-1962?","משבר הטילים בקובה"]],["מתי נחת האדם הראשון על הירח?","20 ביולי 1969","המלחמה הקרה ואילך","אפולו 11. מאות מיליוני אנשים צפו בשידור החי. בסך הכול הלכו על הירח 12 אסטרונאוטים, כולם בשנים 1969–1972.",["מה קרה ב-20 ביולי 1969?","האדם הראשון נחת על הירח"]],["מי היה האדם הראשון על הירח?","ניל ארמסטרונג","המלחמה הקרה ואילך",'המשפט שלו: "צעד קטן לאדם, צעד גדול לאנושות". השני שירד, באז אולדרין, יצא אחריו כעבור כ-20 דקות.',["במה התפרסם ניל ארמסטרונג?","האדם הראשון שהלך על הירח"]],["מי היה האדם הראשון בחלל?","יורי גגארין, 1961","המלחמה הקרה ואילך","ב-12 באפריל 1961 הקיף את כדור הארץ פעם אחת, בטיסה של 108 דקות. הוא נהרג ב-1968 בתאונת מטוס אימונים, בגיל 34.",["במה התפרסם יורי גגארין?","האדם הראשון בחלל (1961)"]],["מתי הסתיימה מלחמת וייטנאם?","1975","המלחמה הקרה ואילך","המלחמה הסתיימה בנפילת סייגון לידי צפון וייטנאם. היא הייתה המלחמה הראשונה ששודרה בטלוויזיה כמעט מדי ערב — והמראות הפכו את דעת הקהל בארה״ב נגדה.",["איזו מלחמה הסתיימה ב-1975 בנפילת סייגון?","מלחמת וייטנאם"]],["מי היה מהטמה גנדי?","מנהיג המאבק הלא-אלים לעצמאות הודו","המלחמה הקרה ואילך",'"מהטמה" הוא תואר: "נשמה גדולה". מצעד המלח שלו ב-1930 — כ-390 ק״מ ברגל אל הים, בניגוד לחוק הבריטי — הפך לסמל המאבק הלא-אלים. הוא נרצח ב-1948.',["מי הנהיג את המאבק הלא-אלים לעצמאות הודו?","מהטמה גנדי"]],["מתי קיבלה הודו עצמאות?","1947","המלחמה הקרה ואילך","העצמאות באה יחד עם החלוקה להודו ולפקיסטן — ועם הגירה המונית ואלימה של מיליוני בני אדם בין שתי המדינות החדשות.",["איזו מדינה קיבלה עצמאות מבריטניה ב-1947, יחד עם פקיסטן?","הודו"]],["מי היה נלסון מנדלה?","מנהיג המאבק באפרטהייד ונשיא דרום אפריקה","המלחמה הקרה ואילך","ישב בכלא 27 שנה, רובן באי רובן. השתחרר ב-1990, קיבל את פרס נובל לשלום, וב-1994 נבחר לנשיא השחור הראשון של דרום אפריקה.",["מי היה הנשיא השחור הראשון של דרום אפריקה, אחרי 27 שנה בכלא?","נלסון מנדלה"]],["מהו אפרטהייד?","משטר הפרדה גזעית בדרום אפריקה","המלחמה הקרה ואילך",'באפריקאנס: "נפרדות". החוקים קבעו היכן מותר לכל קבוצה לגור, ללמוד ולהתחתן — מ-1948 ועד תחילת שנות ה-90.',["איך נקרא משטר ההפרדה הגזעית בדרום אפריקה?","אפרטהייד"]],["מתי בוטל האפרטהייד?","תחילת שנות התשעים","המלחמה הקרה ואילך","ב-1990 שוחרר מנדלה, ב-1991 בוטלו חוקי היסוד של המשטר, וב-1994 התקיימו הבחירות הראשונות שבהן הצביעו כל אזרחי המדינה.",["מה בוטל בדרום אפריקה בתחילת שנות התשעים?","האפרטהייד"]],["מי היה מרטין לותר קינג?","מנהיג המאבק לזכויות אזרח בארה״ב","המלחמה הקרה ואילך",'נאום "יש לי חלום" שלו נישא ב-1963 מול רבע מיליון איש בוושינגטון. ב-1964 קיבל את פרס נובל לשלום, וב-1968 נרצח.',['מי נשא את הנאום "יש לי חלום" ב-1963?',"מרטין לותר קינג"]],["מתי נרצח ג׳ון קנדי?","22 בנובמבר 1963","המלחמה הקרה ואילך","נורה בדאלאס שבטקסס, בשיירה פתוחה. החשוד, לי הארווי אוסוולד, נרצח בעצמו יומיים אחר כך — ולכן השאלות על הרצח לא נסגרו עד היום.",["איזה נשיא ארה״ב נרצח ב-22 בנובמבר 1963?","ג׳ון קנדי"]],["מהי פרשת ווטרגייט?","שערורייה שהובילה להתפטרות ניקסון, 1974","המלחמה הקרה ואילך",'התחילה בפריצה למטה המפלגה הדמוקרטית במתחם ווטרגייט ב-1972. מאז כל שערורייה מקבלת את הסיומת "-גייט". ניקסון הוא הנשיא האמריקאי היחיד שהתפטר.',["איזו שערורייה הובילה להתפטרות הנשיא ניקסון ב-1974?","פרשת ווטרגייט"]],["מתי התרחשו פיגועי 11 בספטמבר?","2001","המלחמה הקרה ואילך","19 מחבלי אל-קאעידה חטפו ארבעה מטוסים. כמעט 3,000 בני אדם נהרגו, ובעקבות הפיגועים יצאה ארה״ב למלחמה באפגניסטן.",["מה קרה בארה״ב ב-11 בספטמבר 2001?","פיגועי הטרור של אל-קאעידה — במגדלי התאומים ובפנטגון"]],["מהו האביב הערבי?","גל מהפכות במזרח התיכון, 2010–2012","המלחמה הקרה ואילך","התחיל בתוניסיה, כשרוכל צעיר בשם מוחמד בועזיזי הצית את עצמו במחאה. הגל הפיל שליטים בתוניסיה, במצרים, בלוב ובתימן — ובסוריה הוביל למלחמת אזרחים.",["איך נקרא גל המהפכות במזרח התיכון בשנים 2010–2012?","האביב הערבי"]],["מתי פלשה רוסיה לאוקראינה?","פברואר 2022","המלחמה הקרה ואילך","ב-24 בפברואר 2022: המתקפה הגדולה ביותר באירופה מאז מלחמת העולם השנייה. קדם לה סיפוח חצי האי קרים ב-2014.",["מה קרה ב-24 בפברואר 2022?","רוסיה פלשה לאוקראינה"]],["מהי המהפכה התעשייתית?","מעבר לייצור ממוכן, מהמאה ה-18","עידנים קודמים","מנוע הקיטור המשופר של ג׳יימס ואט, משנות ה-70 של המאה ה-18, היה המנוע שלה — פשוטו כמשמעו. בתוך פחות ממאה שנה, רוב הבריטים כבר גרו בערים.",["איך נקרא המעבר לייצור ממוכן, שהתחיל במאה ה-18?","המהפכה התעשייתית"]],["היכן החלה המהפכה התעשייתית?","בריטניה","עידנים קודמים","היו לה פחם וברזל, מושבות, הון, וחוקי פטנטים שעודדו המצאות. מנצ׳סטר הפכה לבירת הטקסטיל של העולם.",["איזו מהפכה התחילה בבריטניה במאה ה-18?","המהפכה התעשייתית"]],["מי המציא את מכונת הדפוס?","יוהאן גוטנברג, המאה ה-15","עידנים קודמים",'הספר המפורסם שהדפיס הוא "תנ״ך גוטנברג", בסביבות 1455. בתוך חמישים שנה הודפסו באירופה מיליוני ספרים — והידע הפסיק להיות נחלת מעטים.',["מה המציא יוהאן גוטנברג במאה ה-15?","את מכונת הדפוס"]],["מהי הרנסנס?","תקופת פריחה תרבותית באירופה, המאות 14–17","עידנים קודמים",'בצרפתית: "לידה מחדש" — של התרבות היוונית-רומית. התחיל בפירנצה, והדמויות המזוהות איתו: לאונרדו דה וינצ׳י, מיכלאנג׳לו ורפאל.',["איך נקראת תקופת הפריחה התרבותית באירופה במאות ה-14 עד ה-17?","הרנסנס"]],["מהי הרפורמציה?","הפילוג בנצרות שהחל עם מרטין לותר, 1517","עידנים קודמים",'לפי המסורת, לותר מסמר 95 טענות על דלת כנסייה בוויטנברג, נגד מכירת "כתבי מחילה". מכאן נולדה הנצרות הפרוטסטנטית.',["איך נקרא הפילוג בנצרות שהחל עם מרטין לותר ב-1517?","הרפורמציה"]],["מהו הנאורות?","זרם רעיוני במאה ה-18 שהדגיש תבונה וזכויות","עידנים קודמים",'המוטו, לפי הפילוסוף עמנואל קאנט: "העז להשתמש בתבונתך!". רעיונות הנאורות עמדו מאחורי המהפכה האמריקאית והמהפכה הצרפתית.',["איך נקרא הזרם הרעיוני של המאה ה-18 שהדגיש תבונה וזכויות?","הנאורות"]],["מתי נפלה האימפריה הרומית המערבית?","476 לספירה","עידנים קודמים","באותה שנה הודח הקיסר האחרון במערב — נער בשם רומולוס אוגוסטולוס, ששמו מזכיר גם את מייסד רומא וגם את הקיסר הראשון.",["מה נפל ב-476 לספירה?","האימפריה הרומית המערבית"]],["מהי האימפריה הביזנטית?","המשך האימפריה הרומית המזרחית","עידנים קודמים",'את השם "ביזנטית" נתנו לה רק היסטוריונים מאוחרים; בני התקופה קראו לעצמם "רומאים". היא שרדה כאלף שנה אחרי נפילת רומא.',["איך נקראת האימפריה הרומית המזרחית, ששרדה עוד אלף שנה?","האימפריה הביזנטית"]],["מתי נכבשה קונסטנטינופול?","1453, בידי העות׳מאנים","עידנים קודמים","הסולטן מהמט השני הפך אותה לבירה העות׳מאנית — איסטנבול. היסטוריונים רבים רואים בכיבוש את סוף ימי הביניים.",["איזו עיר כבשו העות׳מאנים ב-1453?","קונסטנטינופול — היום איסטנבול"]],["מהן מסעי הצלב?","מסעות צבאיים נוצריים לארץ הקודש, המאות 11–13","עידנים קודמים",'בדרכם פגעו הצלבנים קשות בקהילות היהודיות בגרמניה — "גזירות תתנ״ו" (1096). בירושלים הקימו ממלכה, עד שצלאח א-דין כבש אותה ב-1187.',["איך נקראים המסעות הצבאיים הנוצריים לארץ הקודש במאות ה-11 עד ה-13?","מסעי הצלב"]],["מהו המוות השחור?","מגפת הדבר שהרגה שליש מאירופה, המאה ה-14","עידנים קודמים","הדבר עבר בעיקר דרך פרעושים של חולדות. ביהודים האשימו בהרעלת בארות, ובמקומות רבים נטבחו קהילות שלמות.",["איך נקראת מגפת הדבר של המאה ה-14 באירופה?","המוות השחור"]],["מתי גילה קולומבוס את אמריקה?","1492","עידנים קודמים",'הוא היה בטוח שהגיע להודו — ולכן ילידי אמריקה נקראו "אינדיאנים". היבשת נקראה על שם יורד ים אחר, אמריגו וספוצ׳י.',["מה גילה קולומבוס ב-1492?","את אמריקה"]],["מי הקיף ראשון את העולם?","משלחת מגלן, 1519–1522","עידנים קודמים","מגלן עצמו נהרג בדרך, בפיליפינים. מתוך כ-270 אנשי המשלחת, רק 18 חזרו לספרד — בספינה אחת.",["במה התפרסמה משלחת מגלן (1519–1522)?","ההקפה הראשונה של כדור הארץ"]],["מהי האימפריה העות׳מאנית?","אימפריה מוסלמית ששלטה 600 שנה עד 1922","עידנים קודמים","ארץ ישראל הייתה בשליטתה 400 שנה, מ-1517 ועד הכיבוש הבריטי ב-1917. את חומות העיר העתיקה בירושלים בנה הסולטן סולימאן המפואר.",["איזו אימפריה מוסלמית שלטה כ-600 שנה, עד 1922?","האימפריה העות׳מאנית"]],["מתי התפרקה האימפריה העות׳מאנית?","אחרי מלחמת העולם הראשונה","עידנים קודמים","על חורבותיה קמו מדינות המזרח התיכון החדשות, ואתאטורק הקים ב-1923 את הרפובליקה הטורקית.",["איזו אימפריה התפרקה אחרי מלחמת העולם הראשונה?","האימפריה העות׳מאנית"]],["מהו הסכם סייקס-פיקו?","חלוקת המזרח התיכון בין בריטניה לצרפת, 1916","עידנים קודמים","הסכם סודי בין הדיפלומט הבריטי מארק סייקס לצרפתי פרנסואה ז׳ורז׳-פיקו. רבים מהגבולות הישרים במזרח התיכון של היום נולדו ממנו.",["איך נקרא ההסכם הסודי מ-1916 לחלוקת המזרח התיכון בין בריטניה לצרפת?","הסכם סייקס-פיקו"]],["מי היה צ׳רצ׳יל?","ראש ממשלת בריטניה במלחמת העולם השנייה","מנהיגים",'"אין לי מה להציע מלבד דם, עמל, דמעות וזיעה" — מנאום הבכורה שלו כראש ממשלה, במאי 1940. ב-1953 קיבל פרס נובל — לספרות.',["מי היה ראש ממשלת בריטניה במלחמת העולם השנייה?","וינסטון צ׳רצ׳יל"]],["מי היה פרנקלין רוזוולט?","נשיא ארה״ב, 1933–1945","מנהיגים","הנשיא היחיד שנבחר ארבע פעמים. הוביל את ארה״ב במשבר הכלכלי הגדול ובמלחמת העולם השנייה — כשהוא משותק ברגליו.",["מי היה נשיא ארה״ב בשנים 1933–1945?","פרנקלין דלאנו רוזוולט"]],["מי היה שארל דה גול?","מנהיג צרפת החופשית ונשיא צרפת","מנהיגים",'ב-1940, כשצרפת נכנעה, קרא מלונדון ברדיו להמשיך להילחם — "הקריאה של 18 ביוני". נמל התעופה הגדול של פריז קרוי על שמו.',['מי הנהיג את "צרפת החופשית" במלחמת העולם השנייה?',"שארל דה גול"]],["מי היה מאו דזה-דונג?","מייסד סין הקומוניסטית","מנהיגים",'הכריז על הקמת הרפובליקה העממית של סין ב-1949. מדיניות "הקפיצה הגדולה קדימה" שלו גרמה לרעב שבו מתו עשרות מיליונים.',["מי ייסד את סין הקומוניסטית ב-1949?","מאו דזה-דונג"]],["מהי מהפכת התרבות בסין?","טלטלה פוליטית וחברתית, 1966–1976","מנהיגים",'מאו גייס את "המשמרות האדומים" — צעירים שרדפו מורים, אינטלקטואלים ו"בורגנים". בתי ספר ואוניברסיטאות נסגרו לשנים.',["איך נקראת הטלטלה הפוליטית שעברה על סין בשנים 1966–1976?","מהפכת התרבות"]],["מי היה מיכאיל גורבצ׳וב?","מנהיג ברה״מ האחרון, יזם רפורמות","מנהיגים","קיבל ב-1990 את פרס נובל לשלום על סיום המלחמה הקרה. ברוסיה רבים מאשימים אותו בהתפרקות ברית המועצות.",["מי היה המנהיג האחרון של ברית המועצות?","מיכאיל גורבצ׳וב"]],["מהי פרסטרויקה?","רפורמה כלכלית בברית המועצות","מנהיגים",'ברוסית: "בנייה מחדש". הניסיון של גורבצ׳וב, בשנות ה-80, להכניס רכיבים של שוק חופשי למשק הסובייטי.',["איך נקראה הרפורמה הכלכלית של גורבצ׳וב בברית המועצות?","פרסטרויקה"]],["מהי גלאסנוסט?","מדיניות שקיפות ופתיחות בברית המועצות","מנהיגים",'ברוסית: "פומביות". לראשונה אפשר היה לבקר את השלטון בגלוי — ובתוך שנים ספורות הביקורת הפילה את המשטר כולו.',["איך נקראה מדיניות השקיפות והפתיחות של גורבצ׳וב?","גלאסנוסט"]],["איזו מדינה הייתה הראשונה שהעניקה לנשים זכות בחירה?","ניו זילנד, 1893","מנהיגים","ניו זילנד הייתה אז מושבה בריטית עם שלטון עצמי. בשווייץ, לעומת זאת, נשים קיבלו זכות בחירה ארצית רק ב-1971.",["מתי העניקה ניו זילנד לנשים זכות בחירה — ראשונה בעולם?","1893"]],["מהי חבר הלאומים?","ארגון בינלאומי שקדם לאו״ם","מנהיגים","נוסד ב-1920 ביוזמת נשיא ארה״ב וודרו וילסון — אבל הסנאט האמריקאי סירב להצטרף. חבר הלאומים הוא שנתן לבריטניה את המנדט על ארץ ישראל.",["איך נקרא הארגון הבינלאומי שקדם לאו״ם?","חבר הלאומים"]],["מדוע נכשלה חבר הלאומים?","חוסר סמכות אכיפה, וארה״ב לא הצטרפה","מנהיגים","הוא לא הצליח לעצור את יפן במנצ׳וריה (1931), את איטליה באתיופיה (1935), ואת גרמניה. מלחמת העולם השנייה הייתה ההוכחה הסופית.",null],["מהי המהפכה האיראנית?","הפיכת איראן לרפובליקה איסלאמית, 1979","מנהיגים","השאה הודח, והאייתוללה ח׳ומייני חזר מהגלות בפריז והקים רפובליקה איסלאמית. עד אז איראן הייתה בעלת ברית קרובה של ישראל.",["איזו מהפכה הפכה את איראן לרפובליקה איסלאמית ב-1979?","המהפכה האיראנית"]],["מהי מלחמת המפרץ הראשונה?","שחרור כווית מעיראק, 1991","מנהיגים",'עיראק של סדאם חוסיין פלשה לכווית באוגוסט 1990. קואליציה רחבה בהנהגת ארה״ב שחררה אותה במבצע "סערה במדבר".',["איזו מלחמה התחוללה ב-1991 לשחרור כווית מעיראק?","מלחמת המפרץ"]],["מהי האינקוויזיציה הספרדית?",'רדיפת "כופרים" ואנוסים, מ-1478',"מנהיגים","בראשה עמד תומאס דה טורקמדה. היא רדפה בעיקר אנוסים — יהודים שהתנצרו ונחשדו שהם ממשיכים לקיים מצוות בסתר.",['איך נקרא המוסד הספרדי שרדף "כופרים" ואנוסים מ-1478?',"האינקוויזיציה הספרדית"]],["מתי גורשו יהודי ספרד?","1492","מנהיגים","צו הגירוש של פרדיננד ואיזבלה נתן ליהודים ארבעה חודשים: להתנצר או לעזוב. באותה שנה בדיוק יצא קולומבוס למסעו.",["מה קרה ליהודי ספרד ב-1492?","הם גורשו"]],["מהי מגילת המגנה כרטא?","מסמך אנגלי מ-1215 שהגביל את כוח המלך","מנהיגים",'בלטינית: "המגילה הגדולה". המלך ג׳ון נאלץ לחתום עליה מול אצילים מורדים, ומכאן נולד העיקרון שגם המלך כפוף לחוק.',["איזה מסמך אנגלי מ-1215 הגביל לראשונה את כוח המלך?","מגנה כרטא"]]]},m={id:"crosswords",name:"מילים לתשבצים",description:"ההגדרות שחוזרות בתשבצים שוב ושוב. בדיוק הפורמט של התשבץ: הגדרה בצד אחד, המילה בשני.",cards:[["נהר גדול בדרום אמריקה","אמזונס","טבע וגאוגרפיה","הנהר הגדול בעולם בנפח המים — יותר משבעת הנהרות שאחריו יחד. את שמו קיבל מהלוחמות האמזונות של המיתולוגיה היוונית.",["מהו האמזונס?","נהר גדול בדרום אמריקה"]],["הנהר הארוך באפריקה","נילוס","טבע וגאוגרפיה","כ-6,650 ק״מ, ונחשב לנהר הארוך בעולם (יש שטוענים שהאמזונס ארוך ממנו). הציוויליזציה המצרית כולה נבנתה לאורך גדותיו.",["מהו הנילוס?","הנהר הארוך באפריקה"]],["המדבר הגדול באפריקה","סהרה","טבע וגאוגרפיה",'המדבר החם הגדול בעולם — כמעט בגודל של ארצות הברית. "צחרא" בערבית פירושו פשוט "מדבר", כך ש"מדבר סהרה" הוא בעצם "מדבר מדבר".',["מהי סהרה?","המדבר הגדול באפריקה"]],["הים המלוח בעולם","ים המלח","טבע וגאוגרפיה","מליחותו כ-34%, פי עשרה מהאוקיינוס, וחופיו הם המקום הנמוך ביותר ביבשה. (יש אגמים קטנים מלוחים ממנו — אבל זו ההגדרה שבתשבץ.)",["במה ים המלח מפורסם, לפי ההגדרה בתשבץ?","הים המלוח בעולם"]],["רכס הרים בדרום אמריקה","האנדים","טבע וגאוגרפיה","רכס ההרים הארוך בעולם — כ-7,000 ק״מ לאורך החוף המערבי של היבשת. הפסגה, אקונקגואה (6,961 מ׳), היא הגבוהה ביותר מחוץ לאסיה.",["מהם האנדים?","רכס הרים בדרום אמריקה"]],["רכס הרים באסיה, הגבוה בעולם","הימלאיה","טבע וגאוגרפיה",'בסנסקריט: "משכן השלג". ברכס נמצא האוורסט (8,849 מ׳), והוא עדיין מתרומם בכמה מילימטרים בשנה — הודו נדחקת לתוך אסיה.',["מהי הימלאיה?","רכס ההרים הגבוה בעולם, באסיה"]],["רכס הרים באירופה, בין צרפת לאיטליה","האלפים","טבע וגאוגרפיה","הפסגה, מון בלאן (כ-4,808 מ׳), יושבת על הגבול בין צרפת לאיטליה. חניבעל חצה את האלפים עם פילים בדרכו לתקוף את רומא, ב-218 לפנה״ס.",["מהם האלפים?","רכס הרים באירופה, בין צרפת לאיטליה"]],["אי גדול בים התיכון, איטלקי","סיציליה","טבע וגאוגרפיה","האי הגדול בים התיכון. במזרחו הר הגעש אתנה — מהפעילים ביותר בעולם, והגבוה באירופה שאינו כבוי.",["מהי סיציליה?","אי גדול בים התיכון, השייך לאיטליה"]],["האי הגדול בעולם","גרינלנד","טבע וגאוגרפיה",'רוב שטחה מכוסה בקרח, ובכל זאת שמה "הארץ הירוקה". לפי הסאגות, אריק האדום בחר בשם הזה כדי לפתות מתיישבים.',["במה גרינלנד מחזיקה בשיא עולמי?","האי הגדול בעולם"]],["הר הגעש המפורסם ליד נאפולי","וזוב","טבע וגאוגרפיה","בהתפרצות של שנת 79 לספירה קבר את פומפיי מתחת לאפר. בזכות זה העיר נשמרה כמעט כמו שהייתה — תמונת מצב של חיי היום-יום ברומא.",["מהו הוזוב?","הר הגעש המפורסם ליד נאפולי"]],["שמה הנוסף של הכינרת","ים טבריה","טבע וגאוגרפיה",'על שם העיר טבריה, שהקים הורדוס אנטיפס לכבוד הקיסר טיבריוס. ו"כינרת" — לפי פירוש עממי, כי צורתה מזכירה כינור.',["מהו ים טבריה?","שמה הנוסף של הכינרת"]],["הנחל העובר במזרח ירושלים","קדרון","טבע וגאוגרפיה",'עובר בין העיר העתיקה להר הזיתים, ויורד עד ים המלח. לפי המסורת זה "עמק יהושפט", שבו יתקיים יום הדין.',["מהו הקדרון?","הנחל העובר במזרח ירושלים"]],["הרוח החמה והיבשה בישראל","שרב","טבע וגאוגרפיה",'מילה מקראית: "לא ירעבו ולא יצמאו, ולא יכם שרב ושמש" (ישעיהו מט). בערבית אומרים חמסין — מ"חמישים", לפי האמונה שהוא נושב חמישים יום בשנה.',["מהו שרב?","הרוח החמה והיבשה בישראל"]],["משקע קפוא הנופל כגרגרים","ברד","טבע וגאוגרפיה","נוצר בענני סערה גבוהים, שבהם טיפות קופאות ונישאות למעלה ולמטה שוב ושוב — וכל סיבוב מוסיף שכבת קרח. הברד היה אחת מעשר המכות.",["מהו ברד?","משקע קפוא הנופל כגרגרים"]],["אבק מים באוויר, מפחית ראות","ערפל","טבע וגאוגרפיה",'ערפל הוא בעצם ענן שנוצר צמוד לקרקע. במקרא הוא סמל לנוכחות האל: "ומשה ניגש אל הערפל אשר שם האלוהים".',["מהו ערפל?","אבק מים באוויר, שמפחית ראות"]],["שקע עמוק בקרקעית הים","תהום","טבע וגאוגרפיה",'מילה מבריאת העולם: "וחושך על פני תהום" (בראשית א). הנקודה העמוקה בעולם, מעמקי צ׳לנג׳ר, נמצאת כ-11 ק״מ מתחת לפני הים.',["מהי תהום?","שקע עמוק בקרקעית הים"]],["זרם מים קטן","פלג","טבע וגאוגרפיה",'מקראית: "כעץ שתול על פלגי מים" (תהילים א). מאותו שורש באים "פילוג" ו"מפלגה" — מים שמתפצלים לזרמים.',["מהו פלג?","זרם מים קטן"]],["מקום שבו נהר נשפך לים","שפך","טבע וגאוגרפיה","יש שני סוגים עיקריים: שפך פתוח, כמו של נהר התמזה, ודלתא — שפך מסועף שנוצר מסחף, כמו של הנילוס.",["מהו שפך?","המקום שבו נהר נשפך לים"]],["אבן חן אדומה","אודם","טבע וגאוגרפיה",'האבן הראשונה בחושן של הכהן הגדול: "אודם, פטדה וברקת" (שמות כח). השם מ"אדום". אודם הוא מינרל הקורונדום — אותו מינרל של הספיר הכחול.',["מהו אודם?","אבן חן אדומה"]],["אבן חן ירוקה","ברקת","טבע וגאוגרפיה",'גם היא מאבני החושן. בעברית של היום ברקת היא האמרלד (אזמרגד), ושמה ככל הנראה מ"ברק" — על שם הנצנוץ.',["מהי ברקת?","אבן חן ירוקה"]],["המתכת היקרה הצהובה","זהב","טבע וגאוגרפיה","הסמל הכימי Au — מלטינית aurum. כל הזהב שנכרה אי פעם היה נכנס לקובייה שצלעה כ-22 מטר.",["מהו זהב?","המתכת היקרה הצהובה"]],["מתכת נוזלית בטמפרטורת החדר","כספית","טבע וגאוגרפיה",'המתכת היחידה שנוזלית בטמפרטורת החדר. הסמל Hg בא מיוונית — "כסף מים" — וגם השם העברי ממשיך את אותה תמונה.',["מהי כספית?","מתכת נוזלית בטמפרטורת החדר"]],["עוף דורס גדול, סמל של גובה","נשר","בעלי חיים",'בעברית "נשר" הוא הנשר המקראי — עוף אוכל נבלות (באנגלית griffon vulture), ולא העיט. מוטת הכנפיים שלו מגיעה כמעט לשלושה מטרים.',["מהו נשר?","עוף דורס גדול, סמל של גובה"]],["מלך החיות","אריה","בעלי חיים",'האריה חי בארץ ישראל עד ימי הביניים, ומופיע בתנ״ך שוב ושוב — משמשון שקרע אריה ועד "גור אריה יהודה".',["איזה כינוי יש לאריה?","מלך החיות"]],["החיה הגבוהה בעולם","ג׳ירפה","בעלי חיים","גובהה עד כ-5.5 מטר. בצוואר שלה יש שבע חוליות בלבד — בדיוק כמו לאדם; כל חוליה פשוט ארוכה מאוד.",["במה הג׳ירפה מחזיקה בשיא?","החיה הגבוהה בעולם"]],["היונק הגדול בעולם","לווייתן כחול","בעלי חיים","החיה הגדולה ביותר שחיה אי פעם — גדולה גם מכל דינוזאור. אורכו עד כ-30 מטר, והלשון שלו לבדה שוקלת כמו פיל.",["במה הלווייתן הכחול מחזיק בשיא?","היונק — והחיה — הגדול בעולם"]],["החיה המהירה ביבשה","ברדלס","בעלי חיים",'מגיע ל-100 קמ״ש ויותר, אבל רק לריצות קצרות של כמה מאות מטרים. באנגלית cheetah — מהינדי: "המנומר".',["במה הברדלס מחזיק בשיא?","החיה המהירה ביבשה"]],["ציפור שאינה מסוגלת לעוף, בקוטב הדרומי","פינגווין","בעלי חיים",'פינגווינים לא עפים באוויר — הם "עפים" במים, וחלקם צוללים לעומק של יותר מ-500 מטר. כמעט כולם חיים בחצי הכדור הדרומי.',["מהו פינגווין?","ציפור שאינה מסוגלת לעוף, שחיה בדרום הרחוק"]],["ציפור הידועה ביכולת חיקוי דיבור","תוכי","בעלי חיים",'תוכי אפור בשם אלכס למד יותר ממאה מילים באנגלית, וזיהה צבעים וצורות. השם לקוח מ"קופים ותוכיים" שהגיעו לשלמה — אף שלא ברור שהכוונה שם לתוכי.',["במה התוכי מפורסם?","ביכולת לחקות דיבור"]],["חרק המייצר דבש","דבורה","בעלי חיים",'דבורים מתקשרות בריקוד: "ריקוד הכשכוש" מספר לכוורת באיזה כיוון ובאיזה מרחק נמצאים הפרחים. על הגילוי הזה ניתן פרס נובל.',["מה מייצרת הדבורה?","דבש"]],["בעל חיים הטווה רשת","עכביש","בעלי חיים","חוט המשי של העכביש חזק, ביחס למשקלו, יותר מפלדה. ולא כל העכבישים טווים רשתות: חלקם צדים בארב או בקפיצה.",["מה טווה העכביש?","רשת"]],["בעל חיים קוצני המתגלגל לכדור","קיפוד","בעלי חיים","על גבו אלפי קוצים — 5,000 עד 7,000 — שהם בעצם שערות שהתקשו. במקומות קרים הוא שוקע בחורף בתרדמה.",["מהו קיפוד?","בעל חיים קוצני המתגלגל לכדור"]],["ספינת המדבר","גמל","בעלי חיים","הדבשת אוגרת שומן, לא מים. גמל צמא יכול לשתות יותר מ-100 ליטר בתוך כעשר דקות.",["איזה כינוי יש לגמל?","ספינת המדבר"]],["סוס פסים","זברה","בעלי חיים","דפוס הפסים של כל זברה ייחודי, כמו טביעת אצבע. לפי מחקרים, הפסים עוזרים להרחיק זבובים עוקצים.",["מהי זברה?","סוס פסים"]],["חיית כיס אוסטרלית","קנגורו","בעלי חיים","הגור נולד בגודל של שעועית וזוחל לבד אל הכיס. הקנגורו לא מסוגל ללכת אחורה — ולפי הסבר נפוץ, לכן הוא מופיע על סמל אוסטרליה.",["מהו קנגורו?","חיית כיס אוסטרלית"]],["הדג הגדול בעולם","כריש לווייתן","בעלי חיים","אורכו יותר מעשרה מטרים, אבל הוא ניזון בעיקר מפלנקטון — ענק עדין שאינו מסוכן לאדם. והוא דג, בניגוד ללווייתן, שהוא יונק.",["במה כריש הלווייתן מחזיק בשיא?","הדג הגדול בעולם"]],["בעל חיים המשנה את צבעו","זיקית","בעלי חיים","הצבע משתנה בעיקר כדי לתקשר ולווסת חום, ולא רק כדי להסוות. העיניים זזות כל אחת לחוד, והלשון ארוכה לפעמים יותר מהגוף.",["במה הזיקית מפורסמת?","ביכולת לשנות את צבעה"]],["החי היחיד שיודע לעוף מבין היונקים","עטלף","בעלי חיים",'רוב העטלפים "רואים" בעזרת קול: משמיעים צלילים גבוהים ומאזינים להד — אקולוקציה. כמעט רבע ממיני היונקים בעולם הם עטלפים.',["במה ייחודי העטלף בין היונקים?","הוא היונק היחיד שיודע לעוף"]],["חיה לילית, סמל החוכמה","ינשוף","בעלי חיים","סמל החוכמה בזכות אתנה, אלת החוכמה היוונית, שהינשוף היה הציפור שלה. הוא מסובב את הראש עד 270 מעלות.",["מה מסמל הינשוף?","חוכמה"]],["הציפור הלאומית של ישראל","דוכיפת","בעלי חיים","נבחרה בסקר ציבורי ב-2008, לכבוד שנת ה-60 למדינה. לפי האגדה, שלמה המלך העניק לה את הכרבולת שלה ככתר.",["מה מעמדה של הדוכיפת בישראל?","הציפור הלאומית"]],["מקום שבו שומרים ספרים","ספרייה","מושגים","הספרייה הלאומית בירושלים שומרת עותק מכל ספר שיוצא לאור בישראל — זו חובה בחוק. בעולם העתיק התפרסמה במיוחד ספריית אלכסנדריה.",null],["אוסף מפות","אטלס","מושגים","גרהרד מרקטור קרא כך לאוסף המפות שלו (1595), על שם אטלס — מלך אגדי שנחשב לחכם ולאסטרונום. רוב האנשים מקשרים את השם לטיטאן שנושא את השמיים.",["מהו אטלס?","אוסף מפות"]],["ספר ובו פירושי מילים","מילון","מושגים",'"מילון הלשון העברית" של אליעזר בן-יהודה, בן 17 כרכים, הושלם רק ב-1959 — 37 שנה אחרי מותו.',null],["אוסף של מילים נרדפות","תזאורוס","מושגים",'מיוונית thesauros — "אוצר". ובעברית אכן קוראים לזה "אוצר מילים", או מילון נרדפות.',["מהו תזאורוס?","אוסף של מילים נרדפות"]],["סיפור קצר עם מוסר השכל","משל","מושגים",'במקרא: משל יותם על העצים שבחרו להם מלך, ומשל כבשת הרש של נתן הנביא לדוד. לכל משל יש "נמשל" — מה שהוא בא ללמד באמת.',["מהו משל?","סיפור קצר עם מוסר השכל"]],["נאום לזכר המת","הספד","מושגים",'מקראית: "ויבוא אברהם לספוד לשרה ולבכותה" (בראשית כג) — ההספד הראשון שמוזכר בתורה.',["מהו הספד?","נאום לזכר המת"]],["אמירה קצרה וחכמה","פתגם","מושגים",'המילה מפרסית — "הודעה, דבר" — והגיעה לעברית דרך המקרא: "ונשמע פתגם המלך" במגילת אסתר.',["מהו פתגם?","אמירה קצרה וחכמה"]],["חזרה על צליל בתחילת מילים","אליטרציה","מושגים",'מלטינית: "אל האות". משוררים ופרסומאים אוהבים אותה כי היא נדבקת לאוזן: Coca-Cola, Mickey Mouse.',["מהי אליטרציה?","חזרה על צליל בתחילת מילים"]],["הגזמה ספרותית מכוונת","הפרזה","מושגים",'בלועזית: היפרבולה — מיוונית, "זריקה אל מעבר". "אמרתי לך את זה מיליון פעם" היא הפרזה; אף אחד לא ספר.',["מהי הפרזה?","הגזמה ספרותית מכוונת"]],['השוואה באמצעות "כמו"',"דימוי","מושגים",'"לבן כשלג" הוא דימוי: יש בו מילת השוואה (כ־, כמו). בלעדיה זו כבר מטאפורה.',["מהו דימוי?",'השוואה באמצעות "כמו"']],["השוואה בלי מילת השוואה","מטאפורה","מושגים",'מיוונית metaphora — "העברה": משמעות שעוברת מתחום לתחום. "הזמן הוא כסף" היא מטאפורה; "הזמן יקר כמו כסף" הוא דימוי.',["מהי מטאפורה?","השוואה בלי מילת השוואה"]],["אמירה הפוכה לכוונה, בלעג","אירוניה","מושגים",'מיוונית eironeia — "העמדת פנים". סוקרטס היה מתחזה לבור כדי לחשוף את הבורות של בני שיחו: "האירוניה הסוקרטית".',["מהי אירוניה?","אמירה הפוכה לכוונה, בלעג"]],["מילה הנקראת אותו דבר משני הכיוונים","פלינדרום","מושגים",'מיוונית: "רץ בחזרה". דוגמאות בעברית: "אבא", וגם המשפט "ילד כותב בתוך דלי".',["מהו פלינדרום?","מילה הנקראת אותו דבר משני הכיוונים"]],["ראשי תיבות שנהגים כמילה","נוטריקון","מושגים","מלטינית notarius — לבלר שכתב בקיצורים. בדרשות חז״ל נוטריקון הוא קריאה של מילה כראשי תיבות של משפט שלם.",["מהו נוטריקון?","ראשי תיבות שנהגים כמילה"]],["חילופי אותיות ליצירת מילה חדשה","אנגרמה","מושגים",'מיוונית: "אות מחדש". דוגמה עברית: "לחם" ו"מלח" — אותן שלוש אותיות, בסדר אחר.',["מהי אנגרמה?","חילופי אותיות ליצירת מילה חדשה"]],["התחלה של דבר","ראשית","מושגים",'המילה הראשונה בתורה: "בראשית ברא אלוהים" — ומכאן שמו של הספר כולו.',["מהי ראשית?","התחלה של דבר"]],["סוף, קץ","אחרית","מושגים",'"אחרית הימים" — הביטוי המקראי לעתיד הרחוק, לימי הגאולה: "והיה באחרית הימים" (ישעיהו ב).',["מהי אחרית?","סוף, קץ"]],["ריק מתוכן, הבל","תוהו","מושגים",'לבדו, "תוהו" מופיע במקרא במובן של אפס והבל: "כל הגויים כאין נגדו, מאפס ותוהו נחשבו לו" (ישעיהו מ).',["מהו תוהו?","ריק מתוכן, הבל"]],["מהומה, ערבוביה","תוהו ובוהו","מושגים",'מתיאור הבריאה: "והארץ הייתה תוהו ובוהו, וחושך על פני תהום". "בוהו" אף פעם לא מופיע במקרא בלי "תוהו" לצידו.',["מהו תוהו ובוהו?","מהומה, ערבוביה"]],["ויתור על זכות","מחילה","מושגים",'בהלכה, יום הכיפורים לא מכפר על עבירות שבין אדם לחברו — עד שהחבר מוחל. לכן לפני החג מבקשים "סליחה ומחילה".',["מהי מחילה?","ויתור על זכות — על חוב או על עלבון"]],['מחבר "האודיסאה"',"הומרוס","אנשים ומקומות",'המשורר העיוור, לפי המסורת. "האודיסאה" מספרת על המסע של אודיסאוס הביתה אחרי מלחמת טרויה — עשר שנות נדודים.',["אילו שתי יצירות מפורסמות מיוחסות להומרוס?",'"האיליאדה" ו"האודיסאה"']],["הפילוסוף שלימד את אפלטון","סוקרטס","אנשים ומקומות","לא כתב אף מילה — את תורתו אנחנו מכירים מאפלטון. ב-399 לפנה״ס נידון למוות באתונה, והוצא להורג בשתיית רעל.",["מי היה תלמידו המפורסם של סוקרטס?","אפלטון"]],["הפילוסוף שלימד את אלכסנדר הגדול","אריסטו","אנשים ומקומות","תלמידו של אפלטון ומורו של אלכסנדר — שרשרת של שלושה דורות שעיצבה את המחשבה המערבית. הוא כתב על כמעט הכול, מביולוגיה ועד שירה.",["את מי לימד אריסטו, לפני שיצא לכבוש את העולם?","את אלכסנדר הגדול"]],["אבי הרפואה","היפוקרטס","אנשים ומקומות","רופא יווני מהמאה ה-5 לפנה״ס. השבועה הקדומה של הרופאים נקראת על שמו, ועקרונותיה — כמו לא להזיק לחולה — מלווים את הרפואה עד היום.",["איזה תואר יש להיפוקרטס?","אבי הרפואה"]],["ממציא הטלפון","אלכסנדר גרהם בל","אנשים ומקומות",'רשם את הפטנט ב-1876 — באותו יום שבו הגיש מתחרה בשם אלישע גריי בקשה דומה. המשפט הראשון בטלפון: "מר ווטסון, בוא הנה, אני צריך אותך".',["מה המציא אלכסנדר גרהם בל?","את הטלפון"]],["ממציא הנורה החשמלית","תומאס אדיסון","אנשים ומקומות","הוא לא המציא את הנורה הראשונה, אבל הפך אותה למעשית ועמידה. לזכותו יותר מ-1,000 פטנטים, ובהם הפונוגרף.",["איזו המצאה מפורסמת מיוחסת לתומאס אדיסון?","הנורה החשמלית"]],["מגלה הרדיום","מארי קירי","אנשים ומקומות","האדם הראשון שזכה בשני פרסי נובל, ובשני מדעים שונים — פיזיקה (1903) וכימיה (1911). את הפולוניום קראה על שם מולדתה, פולין.",["איזה יסוד רדיואקטיבי גילתה מארי קירי, יחד עם בעלה?","רדיום (וגם פולוניום)"]],["מגלה הפניצילין","אלכסנדר פלמינג","אנשים ומקומות","ב-1928 חזר מחופשה ומצא עובש שהשמיד חיידקים בצלחת שנשכחה במעבדה. התגלית המקרית הזאת הצילה מאז מאות מיליוני חיים.",["מה גילה אלכסנדר פלמינג ב-1928?","את הפניצילין"]],["אבי הפסיכואנליזה","זיגמונד פרויד","אנשים ומקומות",'רופא וינאי. "פליטה פרוידיאנית" — פליטת פה שחושפת מחשבה מודחקת — קרויה על שמו. ב-1938 נמלט מהנאצים ללונדון.',["איזה תואר יש לזיגמונד פרויד?","אבי הפסיכואנליזה"]],["המשורר הלאומי של ישראל","חיים נחמן ביאליק","אנשים ומקומות",'נולד באוקראינה ועלה לתל אביב ב-1924. ביתו ברחוב ביאליק הוא היום מוזיאון, ושיריו — "הכניסיני תחת כנפך", "אל הציפור" — נלמדים בכל בית ספר.',["איזה תואר יש לחיים נחמן ביאליק?","המשורר הלאומי"]],['מחבר "אלטנוילנד"',"הרצל","אנשים ומקומות",'הספר מתאר את ארץ ישראל של 1923 כחברה מודרנית ומתקדמת. ממנו לקוח המוטו "אם תרצו, אין זו אגדה".',["איזה רומן אוטופי כתב הרצל?","אלטנוילנד"]],["הסופר הישראלי, חתן נובל לספרות","ש״י עגנון","אנשים ומקומות",'זכה ב-1966, יחד עם המשוררת היהודייה-גרמנייה נלי זקס. השם "עגנון" לקוח מאחד הסיפורים הראשונים שלו — "עגונות".',["באיזה פרס זכה ש״י עגנון ב-1966?","פרס נובל לספרות"]],["העיר הנצחית","רומא","אנשים ומקומות","הכינוי מופיע כבר אצל המשורר הרומי טיבולוס, במאה הראשונה לפני הספירה. לפי האגדה, רומא נוסדה ב-753 לפנה״ס בידי רומולוס.",["איזה כינוי יש לרומא?","העיר הנצחית"]],["עיר האורות","פריז","אנשים ומקומות","פריז הייתה מהערים הראשונות שהאירו את רחובותיה, וגם מרכז של תנועת הנאורות במאה ה-18 — ושני ההסברים נותנים את הכינוי.",["איזה כינוי יש לפריז?","עיר האורות"]],["התפוח הגדול","ניו יורק","אנשים ומקומות",'הכינוי התפרסם בשנות ה-20 בזכות כתב מרוצי סוסים, ואומץ בשנות ה-70 בקמפיין תיירות. במקור היא נקראה "ניו אמסטרדם", עד שהבריטים כבשו אותה ב-1664.',["איזה כינוי יש לניו יורק?","התפוח הגדול"]],["העיר שלא נחה לרגע","תל אביב","אנשים ומקומות",'נוסדה ב-1909 כשכונה ליד יפו בשם "אחוזת בית". ב-2003 הוכרזה "העיר הלבנה", עם אלפי מבני הבאוהאוס שלה, כאתר מורשת עולמית.',["איזה כינוי יש לתל אביב?","העיר שלא נחה לרגע"]],["הבירה הצפונית בעולם","רייקיאוויק","אנשים ומקומות",'באיסלנדית: "מפרץ העשן" — על שם האדים של המעיינות החמים. כמעט כל הבתים בעיר מחוממים בחום גאותרמי מהאדמה.',["במה רייקיאוויק מחזיקה בשיא בין ערי הבירה?","הבירה הצפונית בעולם"]],["מדינת האגמים והפיורדים","נורווגיה","אנשים ומקומות",'פיורד הוא מפרץ צר ועמוק שחצב קרחון, ובנורווגיה יש יותר מאלף כאלה. (את "ארץ אלף האגמים" שומרים בדרך כלל לפינלנד.)',["איזה כינוי יש לנורווגיה?","מדינת האגמים והפיורדים"]],["ארץ השמש העולה","יפן","אנשים ומקומות",'השם היפני, ניהון או ניפון, פירושו "מקור השמש": מנקודת המבט של סין, יפן נמצאת בכיוון הזריחה. מכאן גם העיגול האדום בדגל.',["איזה כינוי יש ליפן?","ארץ השמש העולה"]],["היבשת השחורה","אפריקה","אנשים ומקומות",'הכינוי התפרסם בזכות ספרו של החוקר הנרי מורטון סטנלי (1878): "שחורה" במובן של לא ידועה לאירופאים. היום הוא נחשב מיושן ופוגעני.',["איזה כינוי ישן יש לאפריקה?","היבשת השחורה"]]]},h={id:"hebrew",name:"העשרת עברית",description:"מילים ומושגים שנתקלים בהם בעיתון ובשיחה ולא תמיד יודעים להסביר. הרבה מהם מופיעים גם בתשבצים.",cards:[["מהי אמפתיה?","יכולת להזדהות עם רגשותיו של אחר","מילים לועזיות",'מיוונית: en (בתוך) + pathos (רגש) — "להרגיש מבפנים". המילה נטבעה רק ב-1909, כתרגום למונח הגרמני Einfühlung.',["איך נקראת היכולת להזדהות עם רגשותיו של אחר?","אמפתיה"]],["מהו פרדוקס?","אמירה שנראית סותרת את עצמה ובכל זאת נכונה","מילים לועזיות",'מיוונית: para (נגד) + doxa (דעה) — "נגד הדעה המקובלת". דוגמה מפורסמת: "אני יודע שאינני יודע דבר", המיוחס לסוקרטס.',["איך נקראת אמירה שנראית סותרת את עצמה, ובכל זאת נכונה?","פרדוקס"]],["מהו ציניזם?","זלזול בכנות ובמניעים של אחרים","מילים לועזיות",'מיוונית kynikos — "כמו כלב". כך כינו את הפילוסופים הציניקנים, כמו דיוגנס שגר בחבית ובז לכל מוסכמה. משמעות הזלזול באה רק מאוחר יותר.',["איך נקרא זלזול בכנות ובמניעים של אחרים?","ציניזם"]],["מהו סרקזם?","לעג עוקצני, לרוב באמירת ההפך מהכוונה","מילים לועזיות",'מיוונית sarkazein — "לקרוע בשר". עקיצה סרקסטית אמורה לכאוב, וזה מה שמבדיל אותה מאירוניה סתם.',["איך נקרא לעג עוקצני, לרוב באמירת ההפך מהכוונה?","סרקזם"]],["מהי דמגוגיה?","שכנוע ברגשות ובהטעיה במקום בטיעון","מילים לועזיות",'מיוונית: demos (עם) + agogos (מוביל) — "מנהיג העם". באתונה העתיקה זה היה תואר ניטרלי, ורק אחר כך הפך לגנאי למי שמסית את ההמון.',["איך נקרא שכנוע ברגשות ובהטעיה במקום בטיעון?","דמגוגיה"]],["מהי רטוריקה?","אמנות הנאום והשכנוע","מילים לועזיות","מיוונית rhetor — נואם. אריסטו כתב עליה ספר שלם, ומיין את דרכי השכנוע לשלוש: אתוס (אמינות הדובר), פאתוס (רגש) ולוגוס (היגיון).",["איך נקראת אמנות הנאום והשכנוע?","רטוריקה"]],["מהי אוטופיה?","חברה מושלמת ודמיונית","מילים לועזיות",'נטבעה ב-1516 בידי תומאס מור, בספר בשם הזה: ou-topos ביוונית הוא "אין-מקום". משחק מילים מכוון — eu-topos הוא "מקום טוב".',["איך נקראת חברה מושלמת ודמיונית?","אוטופיה"]],["מהי דיסטופיה?","חברה עתידית מדכאת — ההפך מאוטופיה","מילים לועזיות",'dys ביוונית הוא "רע": "מקום רע". הדוגמאות הקלאסיות: "1984" של ג׳ורג׳ אורוול ו"עולם חדש מופלא" של אלדוס הקסלי.',["איך נקראת חברה עתידית מדכאת — ההפך מאוטופיה?","דיסטופיה"]],["מהי נוסטלגיה?","געגוע לעבר","מילים לועזיות","נטבעה ב-1688 בידי סטודנט לרפואה משווייץ: nostos (שיבה הביתה) + algos (כאב). במקור זו הייתה אבחנה רפואית לחיילים שווייצרים שחלו מגעגועים.",["מה המילה הלועזית לגעגוע לעבר?","נוסטלגיה"]],["מהי אמביציה?","שאפתנות","מילים לועזיות",'מלטינית ambire — "להסתובב מסביב". ברומא העתיקה מועמדים למשרה הסתובבו בין הבוחרים כדי לגייס קולות, וכך "הסתובבות" הפכה לשאפתנות.',["מה המילה הלועזית לשאפתנות?","אמביציה"]],["מהי אמביוולנטיות?","רגשות סותרים כלפי אותו דבר","מילים לועזיות","מלטינית: ambi (שניהם) + valentia (עוצמה) — שני כוחות בבת אחת. את המונח טבע ב-1910 הפסיכיאטר השווייצרי אויגן בלוילר.",["איך נקראים רגשות סותרים כלפי אותו דבר?","אמביוולנטיות"]],["מהי אפתיה?","אדישות, חוסר עניין","מילים לועזיות","מיוונית: a (בלי) + pathos (רגש). אצל הפילוסופים הסטואים זו הייתה מעלה — שלוות נפש שאינה מתרגשת מכלום. היום זה בעיקר גנאי.",["מה המילה הלועזית לאדישות וחוסר עניין?","אפתיה"]],["מהי אנטיתזה?","הניגוד הגמור לרעיון","מילים לועזיות","מיוונית: anti (נגד) + thesis (הנחה). בדיאלקטיקה המפורסמת, תזה פוגשת אנטיתזה, ומההתנגשות נולדת סינתזה.",["איך נקרא הניגוד הגמור לרעיון?","אנטיתזה"]],["מהי אנומליה?","חריגה מהרגיל","מילים לועזיות","מיוונית: an (לא) + homalos (אחיד). מדענים אוהבים אנומליות: חריגה שלא מסתדרת עם התיאוריה היא לא פעם הרמז לתגלית הבאה.",["מה המילה הלועזית לחריגה מהרגיל?","אנומליה"]],["מהי אנלוגיה?","הקבלה בין שני דברים שונים","מילים לועזיות",'מיוונית analogia — "יחס, פרופורציה". במקור זה היה מונח מתמטי: 2 הוא ל-4 כמו 3 ל-6.',["איך נקראת הקבלה בין שני דברים שונים?","אנלוגיה"]],["מהי אקסיומה?","הנחת יסוד שמקבלים בלי הוכחה","מילים לועזיות",'מיוונית axioma — "מה שראוי (להתקבל)". הגאומטריה של אוקלידס כולה נבנתה על חמש הנחות יסוד כאלה.',["איך נקראת הנחת יסוד שמקבלים בלי הוכחה?","אקסיומה"]],["מהי היפותזה?","השערה שצריך לבדוק","מילים לועזיות","מיוונית: hypo (מתחת) + thesis (הנחה) — מה שמניחים מתחת, כבסיס. בשיטה המדעית, היפותזה טובה היא כזו שאפשר להפריך בניסוי.",["איך נקראת השערה שצריך לבדוק?","היפותזה"]],["מהי אמפירי?","מבוסס על תצפית וניסיון, לא על תיאוריה","מילים לועזיות",'מיוונית empeiria — "ניסיון". מכאן אמפיריציזם: הגישה הפילוסופית שלפיה כל ידיעה באה מהחושים, ולא מהשכל לבדו.',["איך מתארים ידע שמבוסס על תצפית וניסיון, ולא על תיאוריה?","אמפירי"]],["מהו קונצנזוס?","הסכמה רחבה","מילים לועזיות",'מלטינית: con (יחד) + sentire (להרגיש) — "מרגישים אותו דבר". בפוליטיקה, "נושא בקונצנזוס" הוא נושא שכמעט אין עליו ויכוח.',["מה המילה הלועזית להסכמה רחבה?","קונצנזוס"]],["מהו פרוטוקול?","רישום רשמי של דיון, או נוהל מוסכם","מילים לועזיות","מיוונית: protos (ראשון) + kolla (דבק) — הדף הראשון שהודבק למגילת פפירוס, ועליו פירוט התוכן. משם: רישום רשמי, ומשם: נוהל.",["איך נקרא רישום רשמי של דיון?","פרוטוקול"]],["מהו פרוגנוזה?","תחזית, בעיקר במובן רפואי","מילים לועזיות",'מיוונית: pro (לפני) + gnosis (ידיעה) — "ידיעה מראש". הרופא קובע קודם דיאגנוזה (מה יש), ואחריה פרוגנוזה (מה צפוי).',["איך נקראת תחזית רפואית למהלך המחלה?","פרוגנוזה"]],["מהי דיאגנוזה?","אבחנה","מילים לועזיות",'מיוונית: dia (דרך, לגמרי) + gnosis (ידיעה) — "להכיר עד הסוף". ובעברית: אבחנה, מאותו שורש של "הבחין".',["מה המילה הלועזית לאבחנה?","דיאגנוזה"]],["מהי סטגנציה?","קיפאון, היעדר התקדמות","מילים לועזיות","מלטינית stagnum — בריכה של מים עומדים. ובכלכלה: סטגפלציה — סטגנציה ואינפלציה בבת אחת, הצירוף שכלכלנים הכי חוששים ממנו.",["מה המילה הלועזית לקיפאון, להיעדר התקדמות?","סטגנציה"]],["מהי אינרציה?","התמדה — נטייה להמשיך במצב הקיים","מילים לועזיות",'מלטינית iners — "בטל, חסר פעולה". בפיזיקה זה החוק הראשון של ניוטון: גוף נשאר במנוחה או בתנועה, עד שכוח משנה את מצבו.',["מה המילה הלועזית להתמדה — הנטייה להמשיך במצב הקיים?","אינרציה"]],["מהי אאוטרקיה?","עצמאות כלכלית מוחלטת","מילים לועזיות",'מיוונית: autos (עצמי) + arkein (להספיק) — "מספיק לעצמו". לא לבלבל עם אוטוקרטיה (שלטון יחיד): הבדל של אות, ומשמעות אחרת לגמרי.',["איך נקראת עצמאות כלכלית מוחלטת?","אאוטרקיה"]],["מהו מונופול?","שליטה בלעדית בשוק","מילים לועזיות",'מיוונית: monos (אחד) + polein (למכור) — "מוכר יחיד". משחק הקופסה המפורסם נולד ממשחק שנועד להמחיש את הנזק של מונופולים.',["מה המילה הלועזית לשליטה בלעדית בשוק?","מונופול"]],["מהו נפוטיזם?","העדפת קרובי משפחה במינויים","מילים לועזיות",'מאיטלקית nipote — "אחיין". אפיפיורים מינו את "אחייניהם" לחשמנים — ולא פעם אלה היו בעצם בניהם.',["איך נקראת העדפת קרובי משפחה במינויים?","נפוטיזם"]],["מהו פרוטקציה?","העדפה בשל קשרים אישיים","מילים לועזיות",'מלטינית protectio — "הגנה, מחסה". בעברית המדוברת יש לה כינוי חיבה משלה: "ויטמין פ׳".',["איך נקראת העדפה בשל קשרים אישיים?","פרוטקציה"]],["מהו אולטימטום?","דרישה אחרונה, עם איום אם לא תתקבל","מילים לועזיות",'מלטינית ultimus — "אחרון". האולטימטום המפורסם בהיסטוריה: אוסטרו-הונגריה לסרביה ביולי 1914, אחרי רצח פרנץ פרדיננד — וכך החלה מלחמת העולם הראשונה.',["איך נקראת דרישה אחרונה, עם איום אם לא תתקבל?","אולטימטום"]],["מהו מורטוריום?","הקפאה זמנית של פעילות","מילים לועזיות",'מלטינית morari — "לעכב". משתמשים בה בעיקר להקפאות רשמיות: מורטוריום על החזר חובות, על ניסויים גרעיניים או על בנייה.',["מה המילה הלועזית להקפאה זמנית של פעילות?","מורטוריום"]],["מהו סטטוס קוו?","המצב הקיים, שמסכימים לא לשנות","מילים לועזיות",'מלטינית: "המצב שבו". בישראל זה גם מונח היסטורי: מכתב הסטטוס קוו של בן-גוריון לאגודת ישראל (1947) — שבת, כשרות, נישואין וחינוך.',["איך נקרא המצב הקיים, שמסכימים לא לשנות?","סטטוס קוו"]],["מהי אוטונומיה?","עצמאות בניהול ענייניך","מילים לועזיות",'מיוונית: autos (עצמי) + nomos (חוק) — "מחוקק לעצמו". בהסכמי קמפ דיוויד (1978) הוצעה לפלסטינים אוטונומיה — שלטון עצמי בלי מדינה.',["איך נקראת עצמאות בניהול ענייניך?","אוטונומיה"]],["מהי הגמוניה?","שליטה או השפעה מכרעת","מילים לועזיות",'מיוונית hegemon — "מנהיג". ביוון העתיקה: עיר-מדינה שהובילה ברית של ערים אחרות, כמו אתונה או ספרטה.',["איך נקראת שליטה או השפעה מכרעת של צד אחד?","הגמוניה"]],["מהי אנתרופולוגיה?","חקר האדם והתרבות","מילים לועזיות",'מיוונית: anthropos (אדם) + logos (חקר). שיטת העבודה הקלאסית בתחום: לחיות חודשים ושנים בתוך הקהילה הנחקרת — "תצפית משתתפת".',["איך נקרא חקר האדם והתרבות?","אנתרופולוגיה"]],["מהי ארכיאולוגיה?","חקר העבר דרך שרידים חומריים","מילים לועזיות",'מיוונית: archaios (עתיק) + logos (חקר). "ארכיון" היא קרובת משפחה — שתיהן מהשורש היווני arche, "התחלה" וגם "שלטון".',["איך נקרא חקר העבר דרך שרידים חומריים?","ארכיאולוגיה"]],["מהי אטימולוגיה?","חקר מקור המילים","מילים לועזיות",'מיוונית etymon — "המשמעות האמיתית" של מילה. וזה בדיוק מה שההעשרות בחבילה הזאת עושות: אטימולוגיה.',["איך נקרא חקר מקור המילים?","אטימולוגיה"]],["מהי סמנטיקה?","חקר המשמעות בשפה","מילים לועזיות",'מיוונית sema — "סימן". כשמישהו אומר "זו רק סמנטיקה", הוא טוען שהוויכוח הוא על מילים ולא על מהות.',["איך נקרא חקר המשמעות בשפה?","סמנטיקה"]],['מה פירוש "חוכמה שלאחר מעשה"?',"תובנה שמגיעה מאוחר מדי","ביטויים",'באנגלית: hindsight. ההפך שלה מופיע בתלמוד: "איזהו חכם? הרואה את הנולד" — מי שרואה את התוצאה עוד לפני שהיא באה.',["איך נקראת תובנה שמגיעה מאוחר מדי, רק אחרי שהכול קרה?","חוכמה שלאחר מעשה"]],['מה פירוש "יצא שכרו בהפסדו"?',"הרווח קטן מהנזק","ביטויים",'מקורו במשנה, בפרקי אבות, בדיון על אופיים של אנשים: הרווח ש"יצא" — כלומר נמחק — בגלל ההפסד שבא איתו.',["באיזה ביטוי אומרים שהרווח קטן מהנזק?","יצא שכרו בהפסדו"]],['מה פירוש "טמן ידו בצלחת"?',"התעצל, נמנע מעשייה","ביטויים",'ממשלי: "טמן עצל ידו בצלחת, גם אל פיהו לא ישיבנה" — העצל לא טורח אפילו להרים את היד אל הפה. היום אומרים בעיקר "לא טמן ידו בצלחת": פעל.',["באיזה ביטוי מקראי אומרים שמישהו התעצל ונמנע מעשייה?","טמן ידו בצלחת"]],['מה פירוש "מצא חן בעיניו"?',"נראה לו טוב, זכה לאהדתו","ביטויים",'המקור הראשון: "ונח מצא חן בעיני ה׳" (בראשית ו) — רגע לפני המבול.',["באיזה ביטוי מקראי אומרים שמשהו נראה למישהו טוב, או שזכה לאהדתו?","מצא חן בעיניו"]],['מה פירוש "יצא מגדרו"?',"התאמץ מאוד, או התרגז מאוד","ביטויים",'"גדר" היא גבול: מי שיוצא מגדרו חורג מההתנהגות הרגילה שלו — לטוב (מאמץ) או לרע (כעס). מההקשר מבינים איזה מהשניים.',["באיזה ביטוי אומרים שמישהו חרג מהרגיל שלו — התאמץ מאוד, או התרגז מאוד?","יצא מגדרו"]],['מה פירוש "אין נביא בעירו"?',"קשה לזכות בהערכה בקרב המכרים","ביטויים","המקור בברית החדשה: ישו אמר זאת כשבני עירו, נצרת, לא האמינו בו. מי שהכירו אותך כילד מתקשים לראות בך מומחה.",["איזה ביטוי אומר שקשה לזכות בהערכה דווקא בקרב המכרים?","אין נביא בעירו"]],['מה פירוש "עשה לילות כימים"?',"עבד ללא הפסקה","ביטויים","הלילה נעשה כמו היום — לא הולכים לישון וממשיכים לעבוד. אומרים אותו בדרך כלל על מאמץ ממושך לקראת יעד: מבחן, הקמת עסק, הצלה.",["באיזה ביטוי אומרים שמישהו עבד בלי הפסקה, גם בלילות?","עשה לילות כימים"]],['מה פירוש "כחוט השני"?',"מוטיב שחוזר לאורך כל הדבר","ביטויים",'"שני" כאן הוא לא "שני במספר" אלא צבע אדום, שהופק מתולעת השני. המקור בשיר השירים: "כחוט השני שפתותייך" — חוט אדום שבולט לאורך כל האריג.',["איך אומרים בביטוי על מוטיב שחוזר לאורך כל הדבר?","עובר כחוט השני"]],['מה פירוש "על קצה המזלג"?',"בקצרה, בתמצית","ביטויים",'כמו טעימה מהאוכל בקצה המזלג — לא ארוחה שלמה. מה שמוצג "על קצה המזלג" הוא תקציר, לא כל הסיפור.',['איך אומרים בביטוי "בקצרה, בתמצית"?',"על קצה המזלג"]],['מה פירוש "מלח הארץ"?',"האנשים הטובים והחשובים בחברה","ביטויים",'המקור בדרשת ההר של ישו, בבשורה על פי מתי: "אתם מלח הארץ". בישראל הביטוי נקשר לחלוצים ולאנשי ההתיישבות.',["איך מכנים בביטוי את האנשים הטובים והחשובים בחברה?","מלח הארץ"]],['מה פירוש "בית יוצר"?',"מקום שבו נוצר או מעוצב דבר","ביטויים",'"יוצר" במקרא הוא קדר — אומן כלי חרס. הנביא ירמיהו ירד אל "בית היוצר" וראה איך הכלי מתעצב בידיו (ירמיהו יח).',["איך מכנים בביטוי מקום שבו נוצר ומתעצב דבר?","בית יוצר"]],['מה פירוש "אבן שואבת"?',"דבר המושך אליו רבים","ביטויים",'"אבן שואבת" היא השם העברי הישן למגנט — אבן שמושכת אליה ברזל. מכאן ההשאלה: מקום או אדם שמושך אליו אנשים.',["איך מכנים בביטוי דבר שמושך אליו רבים?","אבן שואבת"]],['מה פירוש "חרב פיפיות"?',"דבר שיכול להזיק לשני הצדדים","ביטויים",'"פיפיות" — שני "פיות", כלומר שני להבים: חרב שחותכת לשני הכיוונים. בתהילים זה דווקא נשק טוב; ההשאלה של היום מדגישה את הסכנה לבעליה.',["איך מכנים בביטוי דבר שיכול להזיק לשני הצדדים?","חרב פיפיות"]],['מה פירוש "קרן זווית"?',"מקום נידח ונשכח","ביטויים",'"קרן" היא פינה, כמו "קרן רחוב". בתלמוד נאמר על כתר התורה שהוא מונח בקרן זווית — "כל הרוצה ליטול יבוא ויטול".',["איך מכנים בביטוי מקום נידח ונשכח?","קרן זווית"]],['מה פירוש "יצא ידי חובה"?',"עשה את המינימום הנדרש","ביטויים",'מונח הלכתי: מי שקיים מצווה "יצא ידי חובתו" — למשל ששמע תקיעת שופר. בעברית של היום הדגש עבר ל"רק": עשה את המינימום, בלי לב.',["באיזה ביטוי אומרים שמישהו עשה רק את המינימום הנדרש?","יצא ידי חובה"]],['מה פירוש "אליה וקוץ בה"?',"יש בזה גם צד טוב וגם רע","ביטויים",'"אליה" היא זנב הכבש השמן — מעדן נחשב. אבל אם יש בו קוץ, אי אפשר ליהנות ממנו בלי להיפגע.',["באיזה ביטוי אומרים שיש בדבר גם צד טוב וגם צד רע?","אליה וקוץ בה"]],['מה פירוש "מן הפח אל הפחת"?',"ברח מצרה אחת ונפל בגרועה ממנה","ביטויים",'מישעיהו: "פחד ופחת ופח עליך". "פח" הוא מלכודת ו"פחת" הוא בור עמוק — מי שנמלט מהמלכודת נופל לבור.',["באיזה ביטוי אומרים שמישהו ברח מצרה אחת ונפל לגרועה ממנה?","מן הפח אל הפחת"]],['מה פירוש "טובל ושרץ בידו"?',"מתחרט למראית עין בלבד","ביטויים","מהתלמוד: מי שמתוודה על חטא ולא עוזב אותו דומה למי שטובל במקווה כשהשרץ — חיה טמאה — עדיין בידו. הטבילה לא תטהר אותו.",["איך מתארים בביטוי מישהו שמתחרט למראית עין בלבד?","טובל ושרץ בידו"]],['מה פירוש "נפל בפח"?',"נלכד במלכודת או בהטעיה","ביטויים",'"פח" במקרא הוא מלכודת לציפורים, לא כלי אשפה: "התיפול ציפור על פח הארץ ומוקש אין לה?" (עמוס ג).',["באיזה ביטוי אומרים שמישהו נלכד במלכודת או בהטעיה?","נפל בפח"]],['מה פירוש "הטמין ראשו בחול"?',"התעלם מבעיה במקום להתמודד","ביטויים","לפי האגדה, יען שמפחד טומן את ראשו בחול. בפועל היענים לא עושים זאת: הם מורידים את הראש לקרקע כדי לטפל בביצים, ומרחוק זה נראה כאילו הראש נעלם.",["באיזה ביטוי אומרים שמישהו מתעלם מבעיה במקום להתמודד איתה?","הטמין ראשו בחול"]],['מהי "אכסניה"?',"מקום לינה","מילים עבריות","מיוונית xenia — הכנסת אורחים (xenos הוא זר, אורח). המילה נכנסה לעברית כבר בימי חז״ל. מאותו מקור: קסנופוביה — פחד מזרים.",["איך נקרא בעברית מקום לינה לאורחים ולמטיילים?","אכסניה"]],['מהי "אסופה"?',"קובץ של יצירות","מילים עבריות",'משורש א-ס-ף. "בעלי אסופות" בקהלת הם חכמים שאספו אמרות. ו"אסופי" — תינוק שנמצא ונאסף מהרחוב — מאותו שורש.',["איך נקרא בעברית קובץ של יצירות שנאספו יחד?","אסופה"]],['מהי "בדולח"?',"זכוכית צלולה ויקרה","מילים עבריות",'מקראית: על המן נאמר "ועינו כעין הבדולח" (במדבר יא). במקרא זו כנראה הייתה אבן או שרף יקר; המשמעות "זכוכית קריסטל" היא של העברית החדשה.',["מה המילה העברית לזכוכית צלולה ויקרה — קריסטל?","בדולח"]],['מהי "גחמה"?',"קפריזה, שרירות לב","מילים עבריות",'קרובה של "שרירותי": החלטה שנולדת מגחמה לא נשענת על שום כלל — רק על מצב רוח רגעי.',["מה המילה העברית לקפריזה — רצון פתאומי, בלי סיבה?","גחמה"]],['מהי "דחליל"?',"בובה בשדה להברחת ציפורים","מילים עבריות",'מארמית: ד-ח-ל פירושו פחד, כמו בצירוף "בדחילו ורחימו" — ביראה ובאהבה. דחליל הוא, פשוטו כמשמעו, "מפחיד".',["איך נקראת בובה שמציבים בשדה כדי להבריח ציפורים?","דחליל"]],['מהי "זוטה"?',"דבר קטן וחסר חשיבות","מילים עבריות",'מארמית: זוטא — קטן. מכאן גם "זוטר" (בדרגה נמוכה) ו"זוטות" — דברים של מה בכך.',["מה המילה העברית, שבאה מארמית, לדבר קטן וחסר חשיבות?","זוטה"]],['מהי "חזיז"?',"ברק","מילים עבריות",'מקראית: "ה׳ עושה חזיזים" (זכריה י) — ברקי סערה. בעברית של היום חזיז הוא גם זיקוק קטן שמתפוצץ ברעש.',["מה המילה המקראית לברק?","חזיז"]],['מהי "טרוניה"?',"תלונה","מילים עבריות",'מהתלמוד: "אין הקב״ה בא בטרוניה עם בריותיו" — אינו דורש מהן יותר ממה שהן יכולות. ככל הנראה מיוונית tyrannia, עריצות.',["מה המילה הגבוהה בעברית לתלונה?","טרוניה"]],['מהי "יהירות"?',"גאווה מופרזת","מילים עבריות",'מקראית: "זד יהיר לץ שמו" (משלי כא) — היהיר מוצג שם בחברה רעה, לצד הזד והלץ.',["איך נקראת גאווה מופרזת?","יהירות"]],['מהי "כמיהה"?',"געגוע עז","מילים עבריות",'מתהילים: "צמאה לך נפשי, כמה לך בשרי" (תהילים סג). השורש מופיע במקרא פעם אחת בלבד — ושם הוא כמעט צמא.',["מה המילה העברית לגעגוע עז?","כמיהה"]],['מהי "לזות שפתיים"?',"רכילות ודברי גנאי","מילים עבריות",'ממשלי: "הסר ממך עקשות פה, ולזות שפתיים הרחק ממך" (משלי ד). באותו פסוק מופיעה גם "עקשות פה" — עוד כרטיסייה בחבילה הזאת.',["איך נקראים בעברית גבוהה רכילות ודברי גנאי?","לזות שפתיים"]],['מהי "מלתעות"?',"שיניים חדות של טורף","מילים עבריות",'מקראית, בשתי צורות: "מלתעות כפירים" בתהילים, ו"מתלעות עוול" באיוב — אותה מילה עם שתי אותיות שהתחלפו.',["איך נקראות שיניו החדות של טורף?","מלתעות"]],['מהי "נכאים"?',"עצבות, דיכאון","מילים עבריות",'ממשלי: "לב שמח ייטיב גהה, ורוח נכאה תייבש גרם" (משלי יז) — כבר במקרא העצבות נקשרת לבריאות הגוף.',["מה המילה העברית הגבוהה לעצבות עמוקה?","נכאים"]],['מהי "סחי"?',"לכלוך","מילים עבריות",'מאיכה: "סחי ומאוס תשימנו בקרב העמים" (איכה ג). היום שומעים אותה בעיקר בצירוף "סחי ומאוס" — לכלוך ותיעוב.',['מה המילה המקראית ללכלוך, בצירוף "___ ומאוס"?',"סחי"]],['מה פירוש "עקשות פה"?',"דיבור מסולף ועקום","מילים עבריות",'ממשלי: "הסר ממך עקשות פה" (משלי ד). "עקש" במקרא הוא עקום ומעוות — ומאותו שורש באו "עקשן" ו"התעקש": מי שלא מתיישר.',["איך נקרא במשלי דיבור מסולף ועקום?","עקשות פה"]],['מהי "פזמון"?',"שיר, או חלק חוזר בשיר","מילים עבריות","בפיוטים של ימי הביניים, הפזמון היה החלק שהקהל חוזר עליו אחרי החזן. מכאן המשמעות הכפולה: גם שיר שלם וגם הבית החוזר.",["איך נקרא החלק החוזר בשיר — הרפרן?","פזמון"]],['מהי "צמרמורת"?',"רעד מקור או מפחד","מילים עבריות","הרעד הוא דרך של הגוף לייצר חום: השרירים מתכווצים ומשתחררים במהירות. והשיער הסומר הוא שארית מאבות קדומים שהייתה להם פרווה.",["איך נקרא הרעד שעובר בגוף מקור או מפחד?","צמרמורת"]],['מהי "קורת רוח"?',"שביעות רצון","מילים עבריות",'"קורת" מאותו שורש של "קר": רוח שמתקררת ונרגעת. מפרקי אבות: "יפה שעה אחת של קורת רוח בעולם הבא מכל חיי העולם הזה".',["מה הביטוי העברי לשביעות רצון?","קורת רוח"]],['מהי "רהיטות"?',"שטף דיבור","מילים עבריות",'מארמית: ר-ה-ט פירושו לרוץ. דיבור רהוט הוא דיבור "רץ" — זורם בלי עצירות.',["מה המילה העברית לשטף דיבור?","רהיטות"]],['מהי "שרירותי"?',"נעשה לפי גחמה, בלי כלל","מילים עבריות",'מהמקרא: "בשרירות לבי אלך" (דברים כט) — ללכת אחרי מה שהלב רוצה, בלי לשאול אף אחד. החלטה שרירותית היא החלטה כזו.',["איך מתארים החלטה שנעשית לפי גחמה, בלי שום כלל?","שרירותית"]],['מהי "תואנה"?',"תירוץ","מילים עבריות",'מסיפור שמשון: "כי תואנה הוא מבקש מפלשתים" (שופטים יד) — שמשון חיפש עילה לריב. תואנה היא תירוץ שמחפשים כדי להצדיק את מה שכבר הוחלט.',["מה המילה המקראית לתירוץ — עילה שמחפשים כדי להצדיק משהו?","תואנה"]],['מהי "תרעומת"?',"טינה, כעס מוצדק","מילים עבריות",'מלשון חז״ל: "אין לו עליו אלא תרעומת" — יש לו טענה מוצדקת נגדו, אבל לא כזו שאפשר לתבוע עליה בבית דין.',["מה המילה העברית לטינה — כעס מוצדק על מישהו?","תרעומת"]]]},D={"מהי אמפתיה?":"האחות הקשיבה לו בסבלנות וב**אמפתיה**, והוא הרגיש שסוף-סוף מבינים אותו.","מהו פרדוקס?":"זה **פרדוקס**: דווקא כשיש לי הכי הרבה זמן פנוי, אני מספיק הכי מעט.","מהו ציניזם?":"אחרי חמש מערכות בחירות בארבע שנים, ה**ציניזם** שלו כלפי פוליטיקאים רק העמיק.","מהו סרקזם?":'"איזה כיף, שוב פקק", אמרה ב**סרקזם** כשהכביש נעצר בפעם השלישית.',"מהי דמגוגיה?":"הנאום היה **דמגוגיה** טהורה — הרבה פחדים, ואף לא נתון אחד.","מהי רטוריקה?":"יש לו **רטוריקה** מרשימה, אבל כשבודקים את התוכנית שלו לא נשאר בה הרבה.","מהי אוטופיה?":"עיר בלי פקקים, בלי זיהום ובלי שכר דירה מטורף נשמעת כמו **אוטופיה**.","מהי דיסטופיה?":'"1984" של אורוול מתאר **דיסטופיה** שבה המדינה עוקבת אחרי כל מילה של כל אזרח.',"מהי נוסטלגיה?":"השירים מהטיול השנתי מעוררים בי **נוסטלגיה** לימים ההם בתיכון.","מהי אמביציה?":"יש לה **אמביציה** גדולה — היא רוצה לנהל את המחלקה עוד לפני גיל שלושים.","מהי אמביוולנטיות?":"יש בי **אמביוולנטיות** לגבי המעבר: שמח על הדירה החדשה, ועצוב לעזוב את השכונה.","מהי אפתיה?":"השיעור היה כל כך משעמם, שבסופו שררה בכיתה **אפתיה** מוחלטת.","מהי אנטיתזה?":"הבן השקט והמופנם הוא ה**אנטיתזה** של אביו, שתמיד צועק ומספר בדיחות.","מהי אנומליה?":"חום של 35 מעלות בינואר הוא **אנומליה** שהחזאים לא זוכרים כמותה.","מהי אנלוגיה?":"המורה השתמשה ב**אנלוגיה**: הלב עובד כמו משאבה שדוחפת מים בצינורות.","מהי אקסיומה?":"בגאומטריה מתחילים מ**אקסיומה**: דרך שתי נקודות עובר קו ישר אחד בלבד.","מהי היפותזה?":"ה**היפותזה** של החוקרים הייתה ששינה טובה משפרת את הזיכרון — והניסוי אישר אותה.","מהי אמפירי?":"בלי נתונים **אמפיריים** מהשטח, הטענה שלך היא בסך הכול השערה.","מהו קונצנזוס?":"בוועד הבית יש **קונצנזוס** שהלובי צריך שיפוץ — חסר רק תקציב.","מהו פרוטוקול?":"המזכירה רשמה את דברי כל המשתתפים ב**פרוטוקול** הישיבה.","מהו פרוגנוזה?":"הרופא מסר **פרוגנוזה** טובה: תוך חודש היא תחזור ללכת בלי קביים.","מהי דיאגנוזה?":"רק אחרי בדיקת דם הרופאה הצליחה לתת **דיאגנוזה** מדויקת.","מהי סטגנציה?":"אחרי שנתיים בלי קידום ובלי אתגר חדש, הוא הרגיש **סטגנציה** בעבודה.","מהי אינרציה?":"החברה המשיכה במדיניות הישנה מתוך **אינרציה**, ולא כי מישהו עוד האמין בה.","מהי אאוטרקיה?":"צפון קוריאה שואפת ל**אאוטרקיה**, וכמעט אינה סוחרת עם העולם.","מהו מונופול?":"כשלחברה אחת יש **מונופול** על השוק, היא יכולה לקבוע כמעט כל מחיר.","מהו נפוטיזם?":"מינוי האחיין של המנכ״ל לסגן נראה כמו **נפוטיזם** במיטבו.","מהו פרוטקציה?":"הוא קיבל את המשרה ב**פרוטקציה** — אבא שלו משחק טניס עם המנהל.","מהו אולטימטום?":"בעל הבית הציב **אולטימטום**: או שמשלמים עד סוף החודש, או שמפנים את הדירה.","מהו מורטוריום?":"העירייה הכריזה על **מורטוריום** על בנייה חדשה עד שתאושר תוכנית המתאר.","מהו סטטוס קוו?":"במקומות הקדושים נשמר **סטטוס קוו** עדין, וכל שינוי קטן בו מעורר סערה.","מהי אוטונומיה?":"המנהלת נותנת לצוות **אוטונומיה** מלאה לבחור איך לעבוד.","מהי הגמוניה?":"במשך עשורים הייתה לארה״ב **הגמוניה** כמעט מוחלטת בכלכלה העולמית.","מהי אנתרופולוגיה?":"היא למדה **אנתרופולוגיה**, וחיה שנה בכפר בגואטמלה כדי לחקור את מנהגיו.","מהי ארכיאולוגיה?":"חובבי **ארכיאולוגיה** התנדבו בחפירות בעיר דוד ומצאו שם מטבע עתיק.","מהי אטימולוגיה?":'ה**אטימולוגיה** של המילה "מחשב" פשוטה: היא באה מהשורש ח-ש-ב.',"מהי סמנטיקה?":"הוויכוח ביניהם היה על **סמנטיקה** — שניהם התכוונו לאותו דבר, רק במילים אחרות.",'מה פירוש "חוכמה שלאחר מעשה"?':"קל להגיד עכשיו שהיה צריך למכור את המניות בשיא — זו **חוכמה שלאחר מעשה**.",'מה פירוש "יצא שכרו בהפסדו"?':"הוא נסע עד הקניון כדי לחסוך עשרים שקל, ושילם חמישים על חניה — **יצא שכרו בהפסדו**.",'מה פירוש "טמן ידו בצלחת"?':"כל השכנים עזרו לפנות את המקלט, ורק הוא **טמן ידו בצלחת** וצפה מהמרפסת.",'מה פירוש "מצא חן בעיניו"?':"הדירה **מצאה חן בעיניו** כבר מהרגע שנכנס בדלת.",'מה פירוש "יצא מגדרו"?':"המלצר **יצא מגדרו** כדי שהערב יהיה מושלם, והביא לנו עוגה עם נר בלי שביקשנו.",'מה פירוש "אין נביא בעירו"?':"בחו״ל מזמינים אותו להרצאות, אבל בעיר שלו כמעט לא שמעו עליו — **אין נביא בעירו**.",'מה פירוש "עשה לילות כימים"?':"לפני ההגשה היא **עשתה לילות כימים** כדי לסיים את העבודה בזמן.",'מה פירוש "כחוט השני"?':"הגעגוע הביתה עובר **כחוט השני** בכל השירים באלבום.",'מה פירוש "על קצה המזלג"?':"אספר לכם **על קצה המזלג** מה הוחלט בפגישה, ואת הפרטים תקראו בסיכום.",'מה פירוש "מלח הארץ"?':"המתנדבים שמחלקים סלי מזון בכל יום שישי הם **מלח הארץ**.",'מה פירוש "בית יוצר"?':"מגמת התיאטרון בתיכון הייתה **בית יוצר** לכמה מהשחקנים הבולטים בארץ.",'מה פירוש "אבן שואבת"?':"שוק הכרמל הוא **אבן שואבת** לתיירים מכל העולם.",'מה פירוש "חרב פיפיות"?':"הרשתות החברתיות הן **חרב פיפיות**: הן מחברות בין אנשים, וגם מפיצות שקרים.",'מה פירוש "קרן זווית"?':"את אלבום התמונות הישן מצאתי ב**קרן זווית** של המחסן, מתחת לערימת קרטונים.",'מה פירוש "יצא ידי חובה"?':"הוא כתב בכרטיס הברכה שתי מילים, רק כדי **לצאת ידי חובה**.",'מה פירוש "אליה וקוץ בה"?':"המשרה החדשה משלמת יותר, אבל **אליה וקוץ בה** — שעתיים נסיעה לכל כיוון.",'מה פירוש "מן הפח אל הפחת"?':"הוא עזב בוס צעקן ועבר למנהל שמפטר בלי התראה — **מן הפח אל הפחת**.",'מה פירוש "טובל ושרץ בידו"?':"הוא מתנצל על האיחורים ומאחר שוב למחרת — **טובל ושרץ בידו**.",'מה פירוש "נפל בפח"?':'סבתא כמעט **נפלה בפח** כשהתקשרו אליה "מהבנק" וביקשו את הסיסמה.','מה פירוש "הטמין ראשו בחול"?':"במקום לטפל בחובות, הוא **הטמין את ראשו בחול** והפסיק לפתוח מכתבים מהבנק.",'מהי "אכסניה"?':"בטיול לגליל ישנו ב**אכסניה** קטנה על שפת הכנרת.",'מהי "אסופה"?':"יצאה **אסופה** חדשה של סיפורים קצרים מאת סופרים צעירים.",'מהי "בדולח"?':"על השולחן עמדו כוסות **בדולח** שסבתא קיבלה לחתונתה.",'מהי "גחמה"?':"הוא צבע את הסלון בכתום מתוך **גחמה** של רגע, ועכשיו הוא מתחרט.",'מהי "דחליל"?':"האיכר הציב **דחליל** באמצע השדה, אבל העורבים כבר מזמן לא מפחדים ממנו.",'מהי "זוטה"?':"אל תתווכחו על **זוטות** — תתמקדו בעיקר.",'מהי "חזיז"?':"**חזיז** האיר את השמיים, ומיד אחריו התגלגל רעם אדיר.",'מהי "טרוניה"?':"השכנים העלו **טרוניות** על הרעש מהמסיבה, והיא נגמרה לפני חצות.",'מהי "יהירות"?':"ה**יהירות** שלו הרחיקה ממנו חברים — הוא תמיד בטוח שהוא יודע הכי טוב.",'מהי "כמיהה"?':"אחרי חודש בחו״ל התעוררה בו **כמיהה** לאוכל של אמא.",'מהי "לזות שפתיים"?':"הוא נמנע מ**לזות שפתיים**, ואף פעם לא דיבר רעה על אנשים מאחורי גבם.",'מהי "מלתעות"?':"התנין סגר את **מלתעותיו** על הדג בתוך שנייה.",'מהי "נכאים"?':"אחרי ההפסד בגמר שקעו האוהדים ב**נכאים**, ואיש לא דיבר כל הדרך הביתה.",'מהי "סחי"?':"אחרי ההפגנה היה הרחוב מלא **סחי** — בקבוקים, ניירות ושאריות אוכל.",'מה פירוש "עקשות פה"?':"בראיון התחמק השר מכל שאלה ב**עקשות פה**, ואיש לא קיבל תשובה ישירה.",'מהי "פזמון"?':"כל הקהל הצטרף ב**פזמון** ושר בקול רם.",'מהי "צמרמורת"?':"כשהזמרת הגיעה לצליל הגבוה, עברה בי **צמרמורת**.",'מהי "קורת רוח"?':"המורה הביטה ב**קורת רוח** בתלמידים שהופיעו על הבמה.",'מהי "רהיטות"?':"היא נאמה ב**רהיטות** מרשימה, בלי להציץ בדף ולו פעם אחת.",'מהי "שרירותי"?':"ההחלטה לפטר דווקא אותו נראתה **שרירותית** — אף אחד לא הסביר למה.",'מהי "תואנה"?':"הוא חיפש **תואנה** כדי לא לבוא לאירוע, ובסוף אמר שהוא חולה.",'מהי "תרעומת"?':"הקיצוץ בבונוסים עורר **תרעומת** רבה בקרב העובדים.","מקום שבו שומרים ספרים":"בכל יום שלישי אני מחזיר ספרים ל**ספרייה** העירונית ולוקח חדשים.","אוסף מפות":"לפני הטיול פתחנו את ה**אטלס** וחיפשנו את הדרך מרומא לנאפולי.","ספר ובו פירושי מילים":"כשנתקלתי במילה לא מוכרת, חיפשתי אותה ב**מילון**.","אוסף של מילים נרדפות":"כדי לא לחזור על אותה מילה, הכותבת חיפשה חלופה ב**תזאורוס**.","סיפור קצר עם מוסר השכל":"המורה סיפרה את ה**משל** על הנמלה והצרצר, כדי להסביר למה כדאי לחסוך.","נאום לזכר המת":"בלוויה נשא הבן **הספד** מרגש על אביו.","אמירה קצרה וחכמה":'סבא אהב לצטט את ה**פתגם** "אל תדחה למחר את מה שתוכל לעשות היום".',"חזרה על צליל בתחילת מילים":'בשורה "פרפר פלא פרש פתאום כנפיים" יש **אליטרציה** — הצליל פ׳ חוזר שוב ושוב.',"הגזמה ספרותית מכוונת":'"אמרתי לך את זה מיליון פעם" היא **הפרזה** — ברור שלא באמת מיליון.','השוואה באמצעות "כמו"':'בשורה "עיניה כמו שני כוכבים" יש **דימוי**: השוואה בעזרת המילה "כמו".',"השוואה בלי מילת השוואה":'"הוא אריה בקרב" היא **מטאפורה** — הוא לא באמת אריה, אבל אמיץ כמו אחד.',"אמירה הפוכה לכוונה, בלעג":"יש **אירוניה** בכך שמכבי האש איחרו לשריפה בגלל שריפה בתחנה שלהם.","מילה הנקראת אותו דבר משני הכיוונים":'המילה "אבא" היא **פלינדרום** — היא נקראת אותו דבר מימין לשמאל ומשמאל לימין.',"ראשי תיבות שנהגים כמילה":'"צה״ל" — צבא הגנה לישראל — הוא **נוטריקון** שכולם הוגים כמילה אחת.',"חילופי אותיות ליצירת מילה חדשה":'"שלום" ו"משול" הן **אנגרמה** זו של זו — אותן אותיות, בסדר אחר.',"התחלה של דבר":"**ראשית** כול, תודה לכל מי שבא הערב.","סוף, קץ":"בסוף הספר צירף המחבר **אחרית** דבר, ובה סיפר איך נולד הרעיון.","ריק מתוכן, הבל":"כל המאמצים לשכנע אותו עלו ב**תוהו**.","מהומה, ערבוביה":"אחרי מסיבת יום ההולדת, הסלון היה **תוהו ובוהו** של בלונים, צלחות וקונפטי.","ויתור על זכות":"הבנק הסכים ל**מחילה** על חלק מהחוב, והוא החזיר רק את השאר."},g={"מי היה ראש הממשלה בשנים 1948–1954?":"14 במאי 1948 – 26 בינואר 1954. התפטר ב-7 בדצמבר 1953 ופרש לשדה בוקר, והמשיך עד שמשה שרת נכנס לתפקיד.","מי היה ראש הממשלה בשנים 1954–1955?":"26 בינואר 1954 – 3 בנובמבר 1955.","מי היה ראש הממשלה בשנים 1955–1963?":"3 בנובמבר 1955 – 26 ביוני 1963.","מי היה ראש הממשלה בשנים 1963–1969?":"26 ביוני 1963 – 26 בפברואר 1969 (נפטר בתפקידו).","מי היה ראש הממשלה בשנים 1969–1974?":"17 במרץ 1969 – 3 ביוני 1974. בין מות אשכול לכניסתה כיהן יגאל אלון כראש ממשלה בפועל (26 בפברואר – 17 במרץ 1969).","מי היה ראש הממשלה בשנים 1974–1977?":"3 ביוני 1974 – 20 ביוני 1977.","מי היה ראש הממשלה בשנים 1977–1983?":"20 ביוני 1977 – 10 באוקטובר 1983.","מי היה ראש הממשלה בשנים 1983–1984?":"10 באוקטובר 1983 – 13 בספטמבר 1984.","מי היה ראש הממשלה בשנים 1984–1986?":"13 בספטמבר 1984 – 20 באוקטובר 1986 — ממשלת אחדות עם רוטציה: שנתיים פרס, ואז שמיר.","מי היה ראש הממשלה בשנים 1986–1992?":"20 באוקטובר 1986 – 13 ביולי 1992.","מי היה ראש הממשלה בשנים 1992–1995?":"13 ביולי 1992 – 4 בנובמבר 1995 (נרצח בתפקידו).","מי היה ראש הממשלה בשנים 1995–1996?":"4 בנובמבר 1995 – 18 ביוני 1996. עד 22 בנובמבר 1995 כראש ממשלה בפועל, ואז בכהונה מלאה.","מי היה ראש הממשלה בשנים 1996–1999?":"18 ביוני 1996 – 6 ביולי 1999.","מי היה ראש הממשלה בשנים 1999–2001?":"6 ביולי 1999 – 7 במרץ 2001.","מי היה ראש הממשלה בשנים 2001–2006?":"7 במרץ 2001 – 14 באפריל 2006. לקה בשבץ ב-4 בינואר 2006, ומאז אולמרט מילא את מקומו.","מי היה ראש הממשלה בשנים 2006–2009?":"4 בינואר 2006 (ממלא מקום) · ראש ממשלה בפועל מ-14 באפריל 2006 · בכהונה מלאה 4 במאי 2006 – 31 במרץ 2009.","מי היה ראש הממשלה בשנים 2009–2021?":"31 במרץ 2009 – 13 ביוני 2021.","מי היה ראש הממשלה בשנים 2021–2022?":"13 ביוני 2021 – 30 ביוני 2022.","מי היה ראש הממשלה ב-2022, לפני נתניהו?":"1 ביולי 2022 – 29 בדצמבר 2022.","איזה ראש ממשלה נרצח בתפקידו?":"4 בנובמבר 1995 (י״ב בחשוון תשנ״ו), בכיכר מלכי ישראל בתל אביב.","איזה ראש ממשלה מת בתפקידו?":"26 בפברואר 1969.","מי היה ראש הממשלה הראשון שלא ממפא״י/העבודה?":"הבחירות: 17 במאי 1977 · ממשלת בגין הושבעה: 20 ביוני 1977.","מי היה נשיא ישראל בשנים 1952–1963?":"16 בדצמבר 1952 – 23 באפריל 1963 (נפטר בתפקידו).","מי היה נשיא ישראל בשנים 1963–1973?":"21 במאי 1963 – 24 במאי 1973.","מי היה נשיא ישראל בשנים 1973–1978?":"24 במאי 1973 – 29 במאי 1978.","מי היה נשיא ישראל בשנים 1978–1983?":"29 במאי 1978 – 5 במאי 1983.","מי היה נשיא ישראל בשנים 1983–1993?":"5 במאי 1983 – 13 במאי 1993.","מי היה נשיא ישראל בשנים 1993–2000?":"13 במאי 1993 – 13 ביולי 2000 (התפטר).","מי היה נשיא ישראל בשנים 2000–2007?":"1 באוגוסט 2000 – 1 ביולי 2007 (התפטר).","מי היה נשיא ישראל בשנים 2007–2014?":"15 ביולי 2007 – 24 ביולי 2014.","מי היה נשיא ישראל בשנים 2014–2021?":"24 ביולי 2014 – 7 ביולי 2021.","מי נשיא ישראל מ-2021?":"מכהן מ-7 ביולי 2021.","מי היה הרמטכ״ל במבצע קדש (1956)?":"המבצע: 29 באוקטובר – 5 בנובמבר 1956 · דיין היה רמטכ״ל 6 בדצמבר 1953 – 29 בינואר 1958.","מי היה הרמטכ״ל במלחמת המפרץ (1991)?":"המלחמה: 17 בינואר – 28 בפברואר 1991 · שומרון היה רמטכ״ל 19 באפריל 1987 – 1 באפריל 1991.","מי היה הרמטכ״ל בשנים 1995–1998?":"1 בינואר 1995 – 9 ביולי 1998.","מי היה הרמטכ״ל בשנים 2002–2005?":"9 ביולי 2002 – 1 ביוני 2005.","מי היה הרמטכ״ל בשנים 2015–2019?":"16 בפברואר 2015 – 15 בינואר 2019.","מי היה הרמטכ״ל בשנים 2019–2023?":"15 בינואר 2019 – 16 בינואר 2023.","מי הרמטכ״ל שנכנס לתפקיד בינואר 2023?":"16 בינואר 2023 – 5 במרץ 2025.","מתי פורסמה הצהרת בלפור?":"2 בנובמבר 1917 — מכתב מלורד בלפור ללורד רוטשילד.","מתי התקיים הקונגרס הציוני הראשון?":"29–31 באוגוסט 1897, באולם הקזינו העירוני בבאזל.","איזה ספר כתב הרצל ב-1896?":"יצא לאור ב-14 בפברואר 1896, בווינה.","מהו הספר האוטופי שכתב הרצל ב-1902?":"יצא לאור באוקטובר 1902.","מתי החל המנדט הבריטי בארץ ישראל?":"ועידת סן רמו: 25 באפריל 1920 · שלטון אזרחי: 1 ביולי 1920 · אישור חבר הלאומים: 24 ביולי 1922 · הסתיים: 15 במאי 1948.","מתי פורסם הספר הלבן שהגביל את העלייה?":'17 במאי 1939 — "הספר הלבן של מקדונלד".',"מתי אישר האו״ם את תוכנית החלוקה?":"29 בנובמבר 1947 — החלטה 181 של העצרת הכללית: 33 בעד, 13 נגד, 10 נמנעו.","מתי הוכרזה מדינת ישראל?":"יום שישי, 14 במאי 1948 (ה׳ באייר תש״ח), בשעה 16:00, בבית דיזנגוף בתל אביב.","מה שמה של מלחמת 1948?":"30 בנובמבר 1947 – 20 ביולי 1949. פלישת צבאות ערב: 15 במאי 1948 · הסכם שביתת הנשק האחרון (עם סוריה): 20 ביולי 1949.","מתי הצטרפה ישראל לאו״ם?":"11 במאי 1949 — החברה ה-59 בארגון.","מהו חוק השבות?":"נחקק ב-5 ביולי 1950 (כ׳ בתמוז תש״י) — ביום השנה למות הרצל.","מתי הועבר משפט אייכמן?":"נפתח ב-11 באפריל 1961 · גזר הדין: 15 בדצמבר 1961 · הוצא להורג בלילה שבין 31 במאי ל-1 ביוני 1962.","מתי התרחש מבצע קדש?":"29 באוקטובר – 5 בנובמבר 1956.","כיצד נקראת מלחמת 1967?":"5–10 ביוני 1967.","מתי פרצה מלחמת יום הכיפורים?":"6 באוקטובר 1973 (י׳ בתשרי תשל״ד), בשעה 14:00 · הפסקת האש: 24 באוקטובר 1973.","מתי בוצע מבצע אנטבה?":"בלילה שבין 3 ל-4 ביולי 1976. המטוס נחטף ב-27 ביוני 1976.","מהו המהפך של 1977?":"הבחירות לכנסת התשיעית: 17 במאי 1977 · ממשלת בגין הושבעה: 20 ביוני 1977.","מתי ביקר סאדאת בישראל?":"19–21 בנובמבר 1977. נאם בכנסת ב-20 בנובמבר.","מתי נחתם הסכם השלום עם מצרים?":"26 במרץ 1979, על מדשאת הבית הלבן בוושינגטון.","מהם הסכמי קמפ דיוויד?":"השיחות: 5–17 בספטמבר 1978 · ההסכמים נחתמו ב-17 בספטמבר 1978.","מתי הופצץ הכור הגרעיני בעיראק?":"7 ביוני 1981.","מתי פרצה מלחמת לבנון הראשונה?":"6 ביוני 1982 · נסיגה לרצועת הביטחון: יוני 1985 · יציאה מלאה מלבנון: 24 במאי 2000.","מתי פרצה האינתיפאדה הראשונה?":"9 בדצמבר 1987 · דעכה עם הסכמי אוסלו, 1993.","מתי נחתמו הסכמי אוסלו?":"אוסלו א׳: 13 בספטמבר 1993, על מדשאת הבית הלבן · אוסלו ב׳: 28 בספטמבר 1995.","מתי נחתם הסכם השלום עם ירדן?":"26 באוקטובר 1994, במעבר ערבה · הצהרת וושינגטון, שקדמה לו: 25 ביולי 1994.","מי קיבלו את פרס נובל לשלום ב-1994?":"הוכרז ב-14 באוקטובר 1994 · הוענק ב-10 בדצמבר 1994, באוסלו.","מתי נרצח יצחק רבין?":"4 בנובמבר 1995 (י״ב בחשוון תשנ״ו), בכיכר מלכי ישראל בתל אביב.","מתי יצאה ישראל מדרום לבנון?":"24 במאי 2000.","מתי פרצה האינתיפאדה השנייה?":"28–29 בספטמבר 2000, למחרת ביקור שרון בהר הבית · נחשבת כמסתיימת בוועידת שארם א-שייח, 8 בפברואר 2005.","מהו מבצע חומת מגן?":"29 במרץ – 10 במאי 2002.","מתי בוצעה ההתנתקות מגוש קטיף?":"הפינוי החל ב-15 באוגוסט 2005 · החייל האחרון יצא מרצועת עזה ב-12 בספטמבר 2005.","מתי התרחשה מלחמת לבנון השנייה?":"12 ביולי – 14 באוגוסט 2006.","מהו מבצע עופרת יצוקה?":"27 בדצמבר 2008 – 18 בינואר 2009.","מהו מבצע צוק איתן?":"8 ביולי – 26 באוגוסט 2014.","מהם הסכמי אברהם?":"ההודעה על ההסכם עם איחוד האמירויות: 13 באוגוסט 2020 · נחתמו ב-15 בספטמבר 2020, בבית הלבן.","מהי העלייה הראשונה?":"אחרי פוגרומי 1881–1882 ברוסיה · ראשון לציון נוסדה ב-31 ביולי 1882 · הסתיימה ב-1903.","מהי העלייה השנייה?":"החלה אחרי פוגרום קישינב (6–7 באפריל 1903) · הסתיימה עם פרוץ מלחמת העולם הראשונה, 28 ביולי 1914.","מהי חומה ומגדל?":"היישוב הראשון, תל עמל (ניר דוד), עלה על הקרקע ב-10 בדצמבר 1936 · כ-57 יישובים עד 1939.","מהו מבצע מרבד הקסמים?":"הטיסה הראשונה: 15 בדצמבר 1948 · השלב העיקרי: יוני 1949 – ספטמבר 1950 · כ-50,000 עולים.","מהו מבצע עזרא ונחמיה?":"הטיסות הראשונות: 19 במאי 1950 · עד ינואר 1952 · כ-120,000 עולים.","מהו מבצע משה?":"21 בנובמבר 1984 – 5 בינואר 1985 · כ-8,000 עולים.","מהו מבצע שלמה?":"24–25 במאי 1991 — 14,325 עולים ב-36 שעות.","מהי פרשת אלטלנה?":"הספינה הגיעה לכפר ויתקין ב-20 ביוני 1948 · הופגזה מול חוף תל אביב ב-22 ביוני 1948.","מתי הוקם צה״ל?":"פקודת צבא הגנה לישראל נחתמה ב-26 במאי 1948 · פורסמה ב-31 במאי 1948, ומאז זה היום הרשמי.","מהי ירושלים מבחינת החוק הישראלי?":"חוק יסוד: ירושלים בירת ישראל — התקבל ב-30 ביולי 1980.","מתי הועברה שגרירות ארה״ב לירושלים?":"ההכרזה של טראמפ: 6 בדצמבר 2017 · השגרירות נפתחה ב-14 במאי 2018.","מהו קו הירוק?":"הסכמי שביתת הנשק, 1949: מצרים — 24 בפברואר · לבנון — 23 במרץ · ירדן — 3 באפריל · סוריה — 20 ביולי.","מי גילו את מבנה הסליל הכפול של ה-DNA?":"המאמר שלהם פורסם ב-Nature ב-25 באפריל 1953 · פרס נובל לרפואה: 1962.","מהו הספר שפרסם דרווין ב-1859?":"יצא לאור ב-24 בנובמבר 1859, בלונדון.","מדוע פלוטו אינו כוכב לכת?":"ההחלטה: 24 באוגוסט 2006, באיגוד האסטרונומי הבינלאומי בפראג · פלוטו התגלה ב-18 בפברואר 1930.","מהו האו״ם?":'אמנת האו״ם נחתמה ב-26 ביוני 1945 בסן פרנסיסקו · נכנסה לתוקף ב-24 באוקטובר 1945 — "יום האו״ם".',"מהו נאט״ו?":"אמנת וושינגטון נחתמה ב-4 באפריל 1949.","מהו ברקזיט?":"משאל העם: 23 ביוני 2016 · היציאה: 31 בינואר 2020 · תקופת המעבר הסתיימה ב-31 בדצמבר 2020.","מהי אמנת האו״ם לזכויות האדם?":'אושרה ב-10 בדצמבר 1948 בעצרת הכללית בפריז — מאז "יום זכויות האדם".',"מתי פרצה המהפכה הצרפתית?":"אספת המעמדות: 5 במאי 1789 · כיבוש הבסטיליה: 14 ביולי 1789 · הסתיימה בהפיכה של נפוליאון, 9 בנובמבר 1799.","מהו יום הבסטיליה?":"14 ביולי 1789. חג לאומי בצרפת מאז 1880.","מי היה נפוליאון בונפרטה?":'הוכתר לקיסר ב-2 בדצמבר 1804 · ויתר על הכתר ב-6 באפריל 1814 · "מאה הימים": 20 במרץ – 22 ביוני 1815.',"מתי הובס נפוליאון סופית?":"קרב ווטרלו: 18 ביוני 1815.","מתי הוכרזה עצמאות ארצות הברית?":"4 ביולי 1776, בפילדלפיה.","מתי התרחשה מלחמת האזרחים האמריקאית?":"ההפגזה על פורט סאמטר: 12 באפריל 1861 · כניעת הגנרל לי באפומטוקס: 9 באפריל 1865.","מי היה אברהם לינקולן?":"נשיא 4 במרץ 1861 – 15 באפריל 1865 · הכרזת האמנציפציה: 1 בינואר 1863 · נורה ב-14 באפריל 1865 ומת למחרת.","מתי פרצה מלחמת העולם הראשונה?":"רצח פרנץ פרדיננד בסרייבו: 28 ביוני 1914 · אוסטרו-הונגריה הכריזה מלחמה על סרביה: 28 ביולי 1914.","מתי הסתיימה מלחמת העולם הראשונה?":"11 בנובמבר 1918, בשעה 11:00 — שביתת הנשק שנחתמה בקרון רכבת ביער קומפיין.","מהו הסכם ורסאי?":"נחתם ב-28 ביוני 1919 · נכנס לתוקף ב-10 בינואר 1920.","מתי התרחשה המהפכה הרוסית?":"מהפכת פברואר: 8–16 במרץ 1917 · מהפכת אוקטובר: 7 בנובמבר 1917 (25 באוקטובר בלוח הרוסי הישן).","מתי הוקמה ברית המועצות?":"30 בדצמבר 1922.","מי היה יוסיף סטלין?":"מות לנין: 21 בינואר 1924 · מות סטלין: 5 במרץ 1953.","מתי עלה היטלר לשלטון?":"מונה לקנצלר ב-30 בינואר 1933.","מתי פרצה מלחמת העולם השנייה?":"1 בספטמבר 1939, עם הפלישה לפולין · הסתיימה ב-2 בספטמבר 1945, בכניעת יפן.","מהו ליל הבדולח?":"9–10 בנובמבר 1938.","מהי ועידת ואנזה?":"20 בינואר 1942, בווילה על אגם ואנזה בברלין.","מהו יום הפלישה לנורמנדי?":"6 ביוני 1944.","מתי הסתיימה המלחמה באירופה?":'הכניעה נחתמה בריימס ב-7 במאי 1945 · נכנסה לתוקף ב-8 במאי — "יום הניצחון" (ברוסיה: 9 במאי).',"מתי הוטלה פצצת האטום על הירושימה?":"6 באוגוסט 1945 · על נגסקי: 9 באוגוסט 1945.","מתי נכנעה יפן?":"הודעת הכניעה: 15 באוגוסט 1945 · הכניעה נחתמה ב-2 בספטמבר 1945, על סיפון אוניית הקרב מיזורי.","מהם משפטי נירנברג?":"המשפט המרכזי: 20 בנובמבר 1945 – 1 באוקטובר 1946 · ההוצאות להורג: 16 באוקטובר 1946.","מהי המלחמה הקרה?":"דוקטרינת טרומן: 12 במרץ 1947 · התפרקות ברית המועצות: 26 בדצמבר 1991.","מתי נבנתה חומת ברלין?":"13 באוגוסט 1961.","מתי נפלה חומת ברלין?":"9 בנובמבר 1989.","מתי התפרקה ברית המועצות?":"גורבצ׳וב התפטר ב-25 בדצמבר 1991 · ברית המועצות התפרקה רשמית ב-26 בדצמבר 1991.","מהו משבר הטילים בקובה?":"16–28 באוקטובר 1962 — שלושה-עשר ימים.","מתי נחת האדם הראשון על הירח?":"20 ביולי 1969 · ארמסטרונג דרך על הירח ב-21 ביולי, בשעה 04:56 שעון ישראל (02:56 UTC).","מי היה האדם הראשון בחלל?":"12 באפריל 1961 — טיסה של 108 דקות.","מתי הסתיימה מלחמת וייטנאם?":"נפילת סייגון: 30 באפריל 1975.","מתי קיבלה הודו עצמאות?":"15 באוגוסט 1947.","מתי נרצח ג׳ון קנדי?":"22 בנובמבר 1963, בשעה 12:30, בדאלאס שבטקסס.","מהי פרשת ווטרגייט?":"הפריצה: 17 ביוני 1972 · ניקסון הודיע על התפטרותו ב-8 באוגוסט 1974, ופינה את הבית הלבן ב-9 באוגוסט.","מתי התרחשו פיגועי 11 בספטמבר?":"11 בספטמבר 2001.","מהו האביב הערבי?":"מוחמד בועזיזי הצית את עצמו בתוניסיה: 17 בדצמבר 2010 · בן עלי ברח: 14 בינואר 2011 · מובארק הודח: 11 בפברואר 2011.","מתי פלשה רוסיה לאוקראינה?":"24 בפברואר 2022.","מהי הרפורמציה?":"31 באוקטובר 1517 — היום שבו לותר פרסם את 95 התזות.","מתי נכבשה קונסטנטינופול?":"29 במאי 1453.","מתי גילה קולומבוס את אמריקה?":"יצא לדרך ב-3 באוגוסט 1492 · הגיע לאיי בהאמה ב-12 באוקטובר 1492.","מי הקיף ראשון את העולם?":"יצאה ב-20 בספטמבר 1519 · מגלן נהרג בפיליפינים ב-27 באפריל 1521 · הספינה ויקטוריה חזרה לספרד ב-6 בספטמבר 1522.","מהי האימפריה העות׳מאנית?":"הסולטנות בוטלה ב-1 בנובמבר 1922 · הרפובליקה הטורקית הוכרזה ב-29 באוקטובר 1923.","מהו הסכם סייקס-פיקו?":"נחתם ב-16 במאי 1916.","מי היה פרנקלין רוזוולט?":"4 במרץ 1933 – 12 באפריל 1945 (מת בתפקידו).","מהי מהפכת התרבות בסין?":"החלה ב-16 במאי 1966 · הסתיימה עם מות מאו, 9 בספטמבר 1976.","איזו מדינה הייתה הראשונה שהעניקה לנשים זכות בחירה?":"החוק נחתם ב-19 בספטמבר 1893 · נשים הצביעו לראשונה ב-28 בנובמבר 1893.","מהי המהפכה האיראנית?":"השאה עזב: 16 בינואר 1979 · חומייני חזר: 1 בפברואר 1979 · השלטון נפל: 11 בפברואר 1979 · הרפובליקה האסלאמית הוכרזה: 1 באפריל 1979.","מהי מלחמת המפרץ הראשונה?":'עיראק פלשה לכווית: 2 באוגוסט 1990 · "סערת המדבר": 17 בינואר – 28 בפברואר 1991.',"מהי האינקוויזיציה הספרדית?":"הבולה של האפיפיור: 1 בנובמבר 1478 · בוטלה סופית ב-15 ביולי 1834.","מתי גורשו יהודי ספרד?":"צו הגירוש נחתם ב-31 במרץ 1492 · היהודים האחרונים עזבו בתחילת אוגוסט 1492, סמוך לתשעה באב.","מהי מגילת המגנה כרטא?":"15 ביוני 1215, באחו רנימיד שליד לונדון.","מגלה הפניצילין":"הגילוי: 28 בספטמבר 1928, בלונדון · פורסם ב-1929 · פרס נובל לרפואה: 1945.","הסופר הישראלי, חתן נובל לספרות":"הוכרז ב-20 באוקטובר 1966 · הוענק ב-10 בדצמבר 1966, יחד עם המשוררת נלי זק״ש.","מהי המדינה המאוכלסת בעולם?":"לפי הערכת האו״ם, הודו עקפה את סין בסוף אפריל 2023.","מי היה נשיא ישראל הראשון?":"17 בפברואר 1949 – 9 בנובמבר 1952 (נפטר בתפקידו).","מי היה הרמטכ״ל במלחמת ששת הימים?":"המלחמה: 5–10 ביוני 1967 · רבין היה רמטכ״ל 1 בינואר 1964 – 1 בינואר 1968.","מי היה הרמטכ״ל במלחמת יום הכיפורים?":"המלחמה: 6–24 באוקטובר 1973 · אלעזר היה רמטכ״ל 1 בינואר 1972 – 3 באפריל 1974, והתפטר בעקבות דוח ועדת אגרנט.","מי היה הרמטכ״ל במבצע אנטבה?":"המבצע: בלילה שבין 3 ל-4 ביולי 1976 · גור היה רמטכ״ל 16 באפריל 1974 – 16 באפריל 1978.","מי היה הרמטכ״ל במלחמת לבנון הראשונה?":"המלחמה פרצה ב-6 ביוני 1982 · רפול היה רמטכ״ל 16 באפריל 1978 – 19 באפריל 1983.","מי היה הרמטכ״ל באינתיפאדה הראשונה?":"האינתיפאדה פרצה ב-9 בדצמבר 1987 · שומרון היה רמטכ״ל 19 באפריל 1987 – 1 באפריל 1991.","מי היה הרמטכ״ל שאחרי דן שומרון?":"ברק היה רמטכ״ל 1 באפריל 1991 – 1 בינואר 1995.","מי היה הרמטכ״ל בפרוץ האינתיפאדה השנייה?":"האינתיפאדה פרצה ב-28–29 בספטמבר 2000 · מופז היה רמטכ״ל 9 ביולי 1998 – 9 ביולי 2002.","מי היה הרמטכ״ל במבצע חומת מגן?":"המבצע: 29 במרץ – 10 במאי 2002 · מופז היה רמטכ״ל 9 ביולי 1998 – 9 ביולי 2002.","מי היה הרמטכ״ל במלחמת לבנון השנייה?":"המלחמה: 12 ביולי – 14 באוגוסט 2006 · חלוץ היה רמטכ״ל 1 ביוני 2005 – 14 בפברואר 2007.","מי היה הרמטכ״ל במבצע עופרת יצוקה?":"המבצע: 27 בדצמבר 2008 – 18 בינואר 2009 · אשכנזי היה רמטכ״ל 14 בפברואר 2007 – 14 בפברואר 2011.","מי היה הרמטכ״ל במבצע צוק איתן?":"המבצע: 8 ביולי – 26 באוגוסט 2014 · גנץ היה רמטכ״ל 14 בפברואר 2011 – 16 בפברואר 2015.","מי כינס את הקונגרס הציוני הראשון?":"29–31 באוגוסט 1897, באולם הקזינו העירוני בבאזל.","מי הקריא את מגילת העצמאות?":"יום שישי, 14 במאי 1948 (ה׳ באייר תש״ח), בשעה 16:00, בבית דיזנגוף בתל אביב.","מי נהרג בפיקוד על מבצע אנטבה?":"נהרג בלילה שבין 3 ל-4 ביולי 1976, בשדה התעופה באנטבה.","מי חתמו על הסכם השלום עם מצרים?":"ההסכם נחתם ב-26 במרץ 1979, בבית הלבן · שניהם זכו בפרס נובל לשלום לשנת 1978.","מי חתם על הסכם אוסלו הראשון מטעם ישראל?":"13 בספטמבר 1993, על מדשאת הבית הלבן.","מי פיתח את הטבלה המחזורית?":"הגרסה הראשונה הושלמה ב-1 במרץ 1869 · הוצגה לאגודה הכימית הרוסית ב-6 במרץ 1869.","מהי תורת היחסות הפרטית?":'המאמר "על האלקטרודינמיקה של גופים נעים" התקבל לפרסום ב-30 ביוני 1905, ופורסם ב-26 בספטמבר 1905.',"מהי תורת היחסות הכללית?":"המשוואות הוצגו לאקדמיה הפרוסית למדעים ב-25 בנובמבר 1915.","מי הנהיג את המהפכה הבולשביקית?":"7 בנובמבר 1917 (25 באוקטובר בלוח הרוסי הישן) · לנין עמד בראש המדינה עד מותו, 21 בינואר 1924.","מה פתח את מלחמת העולם השנייה?":"1 בספטמבר 1939, בשעה 04:45 · בריטניה וצרפת הכריזו מלחמה על גרמניה ב-3 בספטמבר.","מי היה מרטין לותר קינג?":'הנאום "יש לי חלום": 28 באוגוסט 1963, במצעד על וושינגטון · נרצח ב-4 באפריל 1968.',"מי היה מאו דזה-דונג?":"הכריז על הרפובליקה העממית של סין ב-1 באוקטובר 1949 · מת ב-9 בספטמבר 1976."};function N(u){return u.filter(l=>l[4]).length}function S(u){const l=new Map;for(const n of u.cards){const o=l.get(n[2]);o?o.push(n):l.set(n[2],[n])}return[...l.entries()].map(([n,o])=>({name:n,cards:o}))}function A(u){const l=u.trim();return{example:D[l]??null,dates:g[l]??null}}const f=[m,h,e,a,r,t,i,c,p,d];function E(){const u=new Map;for(const l of f)for(const[n,,,o,s]of l.cards)u.set(n.trim(),{reverse:s??null,extra:o??null,...A(n)});return l=>u.get(l.trim())}export{g as DATES,D as EXAMPLES,f as PACKS,A as detailsFor,E as libraryLookup,N as reverseCount,S as sectionsOf};
